import { buildSchemaUrl, ConfigLoader } from "@aliou/pi-utils-settings";
import pkg from "../package.json" with { type: "json" };

/**
 * Raw config shape (what gets saved to disk).
 * All fields optional -- only overrides are stored.
 *
 * JSDoc comments on fields become `description` in the generated JSON Schema.
 * Run `pnpm gen:schema` after changing this interface.
 */
export interface ExtensionTemplateConfig {
  /** Enable or disable the extension. */
  enabled?: boolean;
  /** Custom option value. */
  myOption?: string;
}

/**
 * Resolved config (defaults merged in).
 * All fields required.
 */
export interface ResolvedExtensionTemplateConfig {
  enabled: boolean;
  myOption: string;
}

const DEFAULTS: ResolvedExtensionTemplateConfig = {
  enabled: true,
  myOption: "default-value",
};

const schemaUrl = buildSchemaUrl(pkg.name, pkg.version);

/**
 * Config loader instance.
 * Config is stored at ~/.pi/agent/extensions/<extension-name>.json
 *
 * The schemaUrl option injects a $schema field into saved JSON files,
 * giving editors autocomplete and validation.
 */
export const configLoader = new ConfigLoader<
  ExtensionTemplateConfig,
  ResolvedExtensionTemplateConfig
>("extension-template", DEFAULTS, { schemaUrl });

# Extension Structure

This covers the standalone repository structure for a Pi extension. This is the recommended layout for new extensions.

## Directory Layout

```
my-extension/
  src/
    index.ts              # Entry point (default export)
    config.ts             # Config schema (types) + loader + defaults
    client.ts             # API client (if wrapping a third-party API)
    tools/
      my-tool.ts          # One file per tool (simple tool)
      my-multi-tool/      # Multi-action tool
        index.ts           # Tool registration + renderCall/renderResult
        actions/           # One file per action
          create.ts
          list.ts
          show.ts
        render.ts          # Separate render module (when rendering is complex)
        types.ts           # Serialized types for tool details
    commands/
      my-command.ts        # One file per command
    components/
      my-renderer.ts       # Shared TUI components
    providers/
      index.ts             # Provider registration
      models.ts            # Model definitions
    utils/                 # Internal helpers (matching, parsing, etc.)
      my-helper.ts
  package.json
  tsconfig.json
  biome.json               # Linting/formatting
  shell.nix                # Nix dev environment
  .changeset/
    config.json            # Changeset config for versioning
  README.md
```

Not every extension needs every directory. A simple extension with one tool might only have `src/index.ts` and `src/tools/my-tool.ts`.

### Organization principles

- **`index.ts` and `config.ts`** stay at root. These are the two core files every non-trivial extension has.
- **Tools, commands, components, providers, hooks** each get their own directory. One file per tool/command/component.
- **Config types live in `config.ts`**, not a separate `types.ts` or `config-schema.ts`. The config file exports both the types (raw and resolved) and the config loader instance.
- **Utility/helper files** go in `utils/`. This includes pattern matching, shell parsing, event helpers, migrations, etc. Anything that is not a tool, command, component, provider, or hook.
- **No separate `types.ts`** unless the extension has shared types unrelated to config (rare). Config types are the most common shared types, and they belong in `config.ts`.
- **Multi-action tools** get their own directory under `tools/`. The tool registration + rendering lives in `index.ts`, each action gets its own file in `actions/`, and complex rendering logic goes in `render.ts`. Serialized types for tool details go in `types.ts`.
- **Core/domain logic** lives in dedicated modules at the `src/` root (`client.ts`, `manager.ts`). These contain the business logic, are testable without the Pi framework, and don't import from `@mariozechner/pi-coding-agent`. Tools are thin wrappers that call these modules and format results.

## package.json

```json
{
  "name": "@scope/pi-my-extension",
  "version": "0.1.0",
  "description": "Description of the extension",
  "type": "module",
  "license": "MIT",
  "private": false,
  "keywords": ["pi-package", "pi-extension", "pi"],
  "repository": {
    "type": "git",
    "url": "https://github.com/your-org/pi-my-extension"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": ["src", "README.md"],
  "pi": {
    "extensions": ["./src/index.ts"],
    "skills": ["./skills"],
    "themes": ["./themes"],
    "prompts": ["./prompts"],
    "video": "https://example.com/demo.mp4"
  },
  "peerDependencies": {
    "@mariozechner/pi-coding-agent": ">=CURRENT_VERSION",
    "@mariozechner/pi-ai": ">=CURRENT_VERSION",
    "@mariozechner/pi-tui": ">=CURRENT_VERSION"
  },
  "peerDependenciesMeta": {
    "@mariozechner/pi-coding-agent": { "optional": true },
    "@mariozechner/pi-ai": { "optional": true },
    "@mariozechner/pi-tui": { "optional": true }
  },
  "devDependencies": {
    "@aliou/biome-plugins": "^0.3.0",
    "@biomejs/biome": "^2.0.0",
    "@changesets/cli": "^2.27.0",
    "@mariozechner/pi-ai": "CURRENT_VERSION",
    "@mariozechner/pi-coding-agent": "CURRENT_VERSION",
    "@mariozechner/pi-tui": "CURRENT_VERSION",
    "@types/node": "^25.0.0",
    "husky": "^9.0.0",
    "typescript": "^5.8.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "lint": "biome check",
    "format": "biome check --write",
    "check:lockfile": "pnpm install --frozen-lockfile --ignore-scripts",
    "prepare": "[ -d .git ] && husky || true",
    "changeset": "changeset",
    "version": "changeset version",
    "release": "pnpm changeset publish"
  },
  "pnpm": {
    "overrides": {
      "@mariozechner/pi-ai": "$@mariozechner/pi-coding-agent",
      "@mariozechner/pi-tui": "$@mariozechner/pi-coding-agent"
    }
  },
  "packageManager": "pnpm@10.26.1"
}
```

Replace `CURRENT_VERSION` with the actual installed version of pi (e.g., `0.52.7`).

Only include `pi` sub-fields that are actually used. `skills`, `themes`, `prompts`, and `video` are optional.

### Fields

**`pi` key**: Declares extension resources. All paths are relative to the package root.

| Field | Description |
|---|---|
| `extensions` | Array of entry point paths. Each is a TypeScript file with a default export function. |
| `skills` | Array of directories containing skill definitions. Optional. |
| `themes` | Array of directories containing theme files. Optional. |
| `prompts` | Array of directories containing prompt files. Optional. |
| `video` | URL to an `.mp4` demo video. Displayed on the pi website package listing. Not used by pi itself. Optional. |

**`peerDependencies`**: Declares the minimum pi version required. Pi ships these packages and injects them via jiti at runtime, so extensions never need to install them:

- `@mariozechner/pi-coding-agent` — core types, utilities, and extension APIs
- `@mariozechner/pi-tui` — TUI components
- `@mariozechner/pi-ai` — AI utilities (`StringEnum`, etc.)
- `@sinclair/typebox` — schema definitions for tool parameters and related types

List any of these you import at runtime in `peerDependencies` as optional peers. This prevents npm from installing duplicate copies when a user installs your extension. Use `>=` with the current version when creating.

**`peerDependenciesMeta`**: Marks peer dependencies as optional. Without `optional: true`, npm 7+ auto-installs peers that are not already present, which defeats the purpose — Pi already provides them.

**`devDependencies`**: Same packages at exact pinned versions for local type checking. `pnpm install` in your repo installs peerDependencies automatically, so local development is unaffected.

**`scripts.prepare`**: The `[ -d .git ] && husky || true` guard prevents husky from running in consumer environments (including when Pi installs your package). Without this, `husky` runs on every `npm install` and fails with a non-zero exit code in environments without a `.git` directory.

**`scripts.check:lockfile`**: Verifies the lockfile is in sync with `package.json`. Run in CI to catch accidental lockfile drift.

**`pnpm.overrides`**: Ensures pi sub-packages resolve to the version bundled with pi-coding-agent, avoiding duplicate installations.

## tsconfig.json

```json
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true,
    "resolveJsonModule": true,
    "noEmit": true
  },
  "include": ["src/**/*"],
  "exclude": ["node_modules"]
}
```

Extensions are loaded directly by pi (no build step). `noEmit: true` means TypeScript is only used for type checking.

**Do not add `jsx` or `jsxImportSource` settings.** Although `src/components/` exists, pi-tui components are not React components. They implement the `Component` interface from `@mariozechner/pi-tui` and render to plain strings. No JSX transpilation is involved.

## biome.json

All extensions use Biome for linting and formatting. Canonical config:

```json
{
  "$schema": "https://biomejs.dev/schemas/2.4.2/schema.json",
  "plugins": [
    "./node_modules/@aliou/biome-plugins/plugins/no-inline-imports.grit",
    "./node_modules/@aliou/biome-plugins/plugins/no-js-import-extension.grit",
    "./node_modules/@aliou/biome-plugins/plugins/no-emojis.grit"
  ],
  "vcs": {
    "enabled": true,
    "clientKind": "git",
    "useIgnoreFile": true
  },
  "files": {
    "includes": ["**/*.ts", "**/*.json"],
    "ignoreUnknown": true
  },
  "assist": {
    "actions": {
      "source": {
        "organizeImports": "on"
      }
    }
  },
  "linter": {
    "enabled": true,
    "rules": {
      "recommended": true
    }
  },
  "formatter": {
    "enabled": true,
    "indentStyle": "space",
    "indentWidth": 2
  }
}
```

The `plugins` field requires Biome 2.x for GritQL plugin support. The `@aliou/biome-plugins` package has five plugins; three apply to pi extensions:

- `no-inline-imports`: Disallows `await import()` and `require()` inside functions. All imports must be static.
- `no-js-import-extension`: Disallows `.js` extensions in import paths (enforces the rule in Critical Rules).
- `no-emojis`: Disallows emoji characters in code and strings.

The other two (`no-interpolated-classname`, `phosphor-icon-suffix`) are specific to React and Phosphor icons and are not applicable.

## config.ts

Non-trivial extensions have a `config.ts` that defines the config schema, types, and loader instance. Use plain TypeScript interfaces with a raw/resolved two-type pattern. The raw type has all fields optional — only overrides are stored to disk. The resolved type has all fields required — defaults are merged in at load time.

```typescript
import { ConfigLoader } from "@aliou/pi-utils-settings";

/**
 * Raw config shape (what gets saved to disk).
 * All fields optional -- only overrides are stored.
 */
export interface MyExtensionConfig {
  enabled?: boolean;
  myOption?: string;
}

/**
 * Resolved config (defaults merged in).
 * All fields required.
 */
export interface ResolvedMyExtensionConfig {
  enabled: boolean;
  myOption: string;
}

const DEFAULTS: ResolvedMyExtensionConfig = {
  enabled: true,
  myOption: "default-value",
};

/**
 * Config loader instance.
 * Config is stored at ~/.pi/agent/extensions/<name>.json
 */
export const configLoader = new ConfigLoader<
  MyExtensionConfig,
  ResolvedMyExtensionConfig
>("my-extension", DEFAULTS);
```

`ConfigLoader` comes from `@aliou/pi-utils-settings`, a standalone published package (source: `~/code/src/github.com/aliou/pi-extensions/packages/settings/`). It is listed as a regular dependency in `package.json`, not a peer dependency.

The name passed to `ConfigLoader` determines the filename: `"my-extension"` → `~/.pi/agent/extensions/my-extension.json`.

### Reading config

After calling `load()`, use `getConfig()` for the resolved config (defaults merged in) or `getRawConfig(scope)` for the raw config at a specific scope.

```typescript
await configLoader.load();
const config = configLoader.getConfig();        // ResolvedMyExtensionConfig
const raw = configLoader.getRawConfig("global"); // MyExtensionConfig | null
```

### Saving config

Use `save(scope, config)` to persist changes. The scope must be one of the enabled scopes (`"global"`, `"local"`, or `"memory"`). After saving, the loader automatically reloads and re-merges.

```typescript
await configLoader.save("global", { myOption: "new-value" });
// configLoader.getConfig() now reflects the saved change
```

Memory scope is ephemeral -- it resets on reload and is not written to disk.

### Scopes and merge order

Default scopes are `["global", "local"]`. Merge priority (lowest to highest): defaults -> global -> local -> memory. Only overrides are stored to disk; missing fields fall back to defaults.

For extensions with migrations or multi-scope config (global + local + in-memory), pass an options object:

```typescript
export const configLoader = new ConfigLoader<MyExtensionConfig, ResolvedMyExtensionConfig>(
  "my-extension",
  DEFAULTS,
  {
    scopes: ["global", "local", "memory"],
    migrations: [...],
  },
);
```

### Config Migrations

For evolving config shape across versions, pass named migrations to `ConfigLoader`:

```typescript
import { ConfigLoader, type Migration, buildSchemaUrl } from "@aliou/pi-utils-settings";
import pkg from "../package.json" with { type: "json" };

const legacyMigration: Migration<MyExtensionConfig> = {
  name: "legacy-flat-key-to-nested",
  shouldRun: (config) => Boolean(config.apiKey && !config.workspaces),
  run: (config) => {
    const migrated = structuredClone(config);
    migrated.workspaces = { default: { apiKey: config.apiKey } };
    delete migrated.apiKey;
    return migrated;
  },
};

const schemaUrl = buildSchemaUrl(pkg.name, pkg.version);

export const configLoader = new ConfigLoader<MyConfig, ResolvedMyConfig>(
  "my-extension",
  DEFAULTS,
  {
    schemaUrl,
    migrations: [legacyMigration],
  },
);
```

Each migration has:
- `name`: unique identifier for idempotency
- `shouldRun(config)`: predicate that returns true if migration is needed
- `run(config)`: returns the migrated config (must not mutate the input)

### JSON Schema for Config Validation

Use `buildSchemaUrl(pkg.name, pkg.version)` from `@aliou/pi-utils-settings` to generate a schema URL. Config files get a `$schema` field pointing to the published schema, enabling editor validation and autocompletion.

## Settings Command

Extensions with user-configurable settings use `registerSettingsCommand` from `@aliou/pi-utils-settings` to create a settings UI with Local/Global tabs:

```typescript
import { registerSettingsCommand, type SettingsSection } from "@aliou/pi-utils-settings";

registerSettingsCommand<MyConfig, ResolvedMyConfig>(pi, {
  commandName: "my-extension:settings",
  commandDescription: "Configure my extension",
  title: "My Extension Settings",
  configStore: configLoader,
  onSave: () => { /* invalidate caches */ },
  buildSections: (tabConfig, resolved, ctx): SettingsSection[] => [
    {
      label: "General",
      items: [
        {
          id: "enabled",
          label: "Enabled",
          description: "Enable or disable the extension",
          currentValue: (tabConfig?.enabled ?? resolved.enabled) ? "enabled" : "disabled",
          values: ["enabled", "disabled"],
        },
      ],
    },
  ],
});
```

For complex nested config (workspaces, profiles), use `submenu` fields with `SettingsDetailEditor` or `FuzzySelector` components. See `pi-linear/src/commands/settings.ts` for a full example.

### Auth Wizard

For extensions requiring API credentials, use the `Wizard` component from `@aliou/pi-utils-settings` for multi-step onboarding:

```typescript
import { Wizard, FuzzySelector, type WizardStepContext } from "@aliou/pi-utils-settings";

const wizard = new Wizard({
  title: "My Auth",
  theme,
  steps: [
    { label: "Key", build: (ctx) => new ApiKeyStep(state, ctx) },
    { label: "Validate", build: (ctx) => new ValidateStep(state, ctx) },
    { label: "Scope", build: (ctx) => new ScopeStep(state, ctx) },
  ],
  onComplete: async () => { /* save config */ },
  onCancel: () => done(false),
});
```

Each step receives a `WizardStepContext` with `markComplete()`/`markIncomplete()` to control navigation gates. See `pi-linear/src/commands/auth-wizard.ts` for a full example with async validation and spinner.

## Entry Point (src/index.ts)

The entry point is a default export function that receives the `ExtensionAPI` object.

### Standard Pattern

```typescript
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { configLoader } from "./config";
import { registerCommands } from "./commands";
import { registerHooks } from "./hooks";
import { registerTools } from "./tools";

export default async function (pi: ExtensionAPI) {
  await configLoader.load();
  const config = configLoader.getConfig();
  if (!config.enabled) return;

  registerTools(pi);
  registerCommands(pi);
  registerHooks(pi);
}
```

### Acceptable Exceptions

Not all extensions follow the standard pattern exactly. These deviations are valid:

**No config**: Extensions that use environment variables exclusively and have no user-configurable settings skip config loading entirely. The entry point reads the env var directly and gates registration on its presence.

**API-key-first**: Extensions wrapping a third-party API check for the API key before loading config or registering anything. If the key is missing, notify the user and return early. Config loads after the key check. See the API Key Pattern section.

**No `enabled` check**: Extensions that are always active by design omit the `enabled` field and the early-return check. The entry point still loads config for other settings. Document this decision in `AGENTS.md`.

When deviating from the standard pattern, note the reason in the extension's `AGENTS.md`.

## API Key Pattern

If your extension wraps a third-party API that requires an API key:

```typescript
export default function (pi: ExtensionAPI) {
  const apiKey = process.env.MY_API_KEY;

  // Register provider unconditionally if it exists
  // (provider handles missing key internally for model registration)
  pi.registerProvider(myProvider);

  // Only register tools that need the key
  if (!apiKey) {
    pi.on("session_start", async (_event, ctx) => {
      ctx.ui.notify("MY_API_KEY not set. Tools disabled.", "warning");
    });
    return;
  }

  pi.registerTool(createMyTool(apiKey));
  pi.registerCommand(createMyCommand(apiKey));
}
```

The principle: check for the API key before registering anything that requires it. If the extension also registers a provider, the provider can be registered regardless (it handles key presence internally for model listing).

## Imports

Do not use `.js` file extensions in imports. Use bare module paths:

```typescript
// Correct
import { myTool } from "./tools/my-tool";
import type { MyType } from "./types";

// Wrong
import { myTool } from "./tools/my-tool.js";
```

## Monorepo Variant

In a monorepo with pnpm workspaces, the structure differs slightly. There is no `src/` directory; the entry point and config live directly in the package root.

```
extensions/
  my-extension/
    index.ts              # Entry point (no src/ directory)
    config.ts             # Config schema (types) + loader + defaults
    commands/
      settings-command.ts
    hooks/
      my-hook.ts
    components/
      my-editor.ts
    utils/
      matching.ts
      shell-utils.ts
    package.json
```

Key differences from standalone:
- Entry point directly in the package root (no `src/` directory).
- `"pi": { "extensions": ["./index.ts"] }` instead of `["./src/index.ts"]`.
- Uses `peerDependencies` (resolved by workspace root).
- Shared `tsconfig` from a workspace package.
- Same organization principles apply: config types in `config.ts`, helpers in `utils/`, one directory per feature category.

### Workspace dependencies

When an extension depends on another workspace package (e.g., `@aliou/pi-utils-settings`, `@aliou/pi-agent-kit`), use the `workspace:^` protocol instead of a version range:

```json
{
  "dependencies": {
    "@aliou/pi-utils-settings": "workspace:^",
    "@aliou/sh": "^0.1.0"
  }
}
```

Use `workspace:^` only for packages that live in this monorepo (under `packages/` or `extensions/`). External published packages like `@aliou/sh` keep regular version ranges.

# Tools

Tools are functions the LLM can call. They are the primary way extensions add capabilities to pi.

## Imports

Use these imports at the top of your tool file:

```typescript
import { ToolCallHeader, ToolBody, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  AgentToolUpdateCallback,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { getMarkdownTheme, keyHint, truncateHead, formatSize } from "@mariozechner/pi-coding-agent";
import { Container, Markdown, Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@mariozechner/pi-coding-agent";
```

## Registration

```typescript
const myTool = {
  name: "my_tool",
  label: "My Tool", // Required: human-readable name for UI
  description: "What this tool does. The LLM reads this to decide when to call it.",
  promptSnippet: "Search for items by query", // One-liner for "Available tools" system prompt
  promptGuidelines: [ // Guideline bullets for "Guidelines" system prompt when active
    "Use this tool when the user asks about search",
    "Prefer specific queries over broad ones",
  ],
  parameters: Type.Object({
    query: Type.String({ description: "Search query" }),
    limit: Type.Optional(Type.Number({ description: "Max results", default: 10 })),
  }),

  async execute(
    toolCallId: string,
    params: MyToolParams,
    signal: AbortSignal | undefined,
    onUpdate: AgentToolUpdateCallback<MyToolDetails> | undefined,
    ctx: ExtensionContext,
  ): Promise<AgentToolResult<MyToolDetails>> {
    const results = await doSomething(params.query, params.limit);
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      details: { results },
    };
  },
};

// Typed param alias - define once, use everywhere
type MyToolParams = Static<typeof myTool.parameters>;
interface MyToolDetails {
  results: string[];
}

export default function (pi: ExtensionAPI) {
  pi.registerTool(myTool);
}
```

## Tool Definition Fields

| Field | Type | Required | Description |
|-------|------|----------|-------------|
| `name` | `string` | Yes | Snake_case identifier used in tool calls |
| `label` | `string` | Yes | Human-readable name shown in UI |
| `description` | `string` | Yes | What the tool does (LLM reads this) |
| `parameters` | `TSchema` | Yes | TypeBox schema for arguments |
| `promptSnippet` | `string` | No | One-liner injected into "Available tools" system prompt. Custom tools without this are omitted from that section. |
| `promptGuidelines` | `string[]` | No | Guideline bullets appended to "Guidelines" system prompt when this tool is active |
| `execute` | `function` | Yes | Implementation |
| `renderCall` | `function` | No | Custom call rendering |
| `renderResult` | `function` | No | Custom result rendering |

## Typed Param Alias

Define a type alias at the top of your file instead of repeating `Static<typeof parameters>`:

```typescript
const parameters = Type.Object({
  query: Type.String({ description: "Search query" }),
  limit: Type.Optional(Type.Number({ description: "Max results", default: 10 })),
});

type MyToolParams = Static<typeof parameters>;
// Use MyToolParams everywhere: execute params, renderCall args, context.args, etc.
```

## Execute Signature

```typescript
execute(
  toolCallId: string,
  params: Static<TParams>,      // Typed from the parameters schema
  signal: AbortSignal | undefined,
  onUpdate: AgentToolUpdateCallback<TDetails> | undefined,
  ctx: ExtensionContext,
): Promise<AgentToolResult<TDetails>>
```

**Parameter order matters.** The signal comes before onUpdate.

Always use optional chaining when calling `onUpdate`:

```typescript
onUpdate?.({ output: "partial result", details: { progress: 50 } });
```

The `onUpdate` parameter can be `undefined`. Calling it without optional chaining will throw.

## Tool Overrides and Delegation

If you override a built-in tool or wrap another tool, audit any delegated `tool.execute(...)` calls during upgrades. These forwarders often pass through `signal`, `onUpdate`, or `ctx` and can silently break when the execute signature changes. Always recheck the delegate call parameter order and include optional parameters that the target tool expects.

## Return Value

```typescript
return {
  content: (TextContent | ImageContent)[],  // Content blocks sent to the LLM
  details?: TDetails,                       // Arbitrary data available in the renderer
};
```

- `content` is what the LLM sees. Each block is `{ type: "text", text: "..." }` or an image. Keep it structured and concise.
- `details` is what the renderer sees. Put rich data here for custom display.

Common pattern:

```typescript
return {
  content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
  details: { results },
};
```

## Error Handling

To report a tool call failure, **throw an error**. The framework catches it and produces a result with `isError: true` on the context.

```typescript
execute: async (toolCallId, params, signal, onUpdate, ctx) => {
  const result = await fetchData(params.query);
  if (!result) {
    throw new Error("No results found. Try a different query.");
  }
  return {
    content: [{ type: "text", text: JSON.stringify(result) }],
    details: { result },
  };
},
```

The framework's `createErrorToolResult` sets `details: {}` (empty object, not `undefined`) and puts the error message in `content`:

```typescript
// Framework produces when tool throws:
{
  content: [{ type: "text", text: errorMessage }],
  details: {}
}
// And sets context.isError = true in renderResult
```

### Error rendering in `renderResult`

The framework passes `isError` on the 4th `context` parameter to `renderResult`, but `ToolRenderContext` is not currently exported from the public API. Two practical approaches:

**Approach 1: Check for missing expected fields in `details`** (recommended for extensions)

When a tool throws, the framework sets `details: {}` (empty object). Check for missing expected fields:

```typescript
renderResult(
  result: AgentToolResult<MyToolDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
) {
  const { details } = result;

  // details is {} when tool threw — expected fields are missing
  if (!details?.results) {
    const textBlock = result.content.find((c) => c.type === "text");
    const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Operation failed";
    return new Text(theme.fg("error", errorMsg), 0, 0);
  }
  // ... normal rendering
}
```

**Approach 2: Use the 4th context parameter** (used by native tools)

Define a minimal interface locally:

```typescript
interface RenderContext { isError: boolean }

renderResult(
  result: AgentToolResult<MyToolDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
  context: RenderContext,
) {
  if (context.isError) {
    const textBlock = result.content.find((c) => c.type === "text");
    const errorMsg = textBlock?.type === "text" ? textBlock.text : "Operation failed";
    return new Text(theme.fg("error", errorMsg), 0, 0);
  }
  // ... normal rendering
}
```

Both approaches work. Approach 1 is more common in published extensions. Approach 2 is what native tools use.

## Parameters Schema

Use TypeBox (`Type.*`) for parameter schemas. The LLM sees the schema to know what arguments to provide.

```typescript
import { Type } from "@mariozechner/pi-coding-agent";

// Required string
Type.String({ description: "File path to read" })

// Optional with default
Type.Optional(Type.Number({ description: "Max results", default: 10 }))

// Enum (string union)
Type.StringEnum(["created", "updated", "relevance"], { description: "Sort order" })

// Boolean
Type.Boolean({ description: "Include hidden files" })

// Nested object
Type.Object({
  name: Type.String(),
  value: Type.String(),
})

// Array
Type.Array(Type.String(), { description: "List of tags" })
```

Always provide `description` on parameters. The LLM uses these to understand what to pass.

## Streaming Updates

Use `onUpdate` to stream partial results while the tool executes. This gives the user feedback during long operations.

```typescript
execute: async (toolCallId, params, signal, onUpdate, ctx) => {
  for (const chunk of chunks) {
    const partial = processChunk(chunk);
    onUpdate?.({
      content: [{ type: "text", text: partial }],
      details: { progress: chunk.index / chunks.length },
    });
  }
  return {
    content: [{ type: "text", text: finalResult }],
    details: { complete: true },
  };
},
```

## Custom Rendering

Override how a tool's invocation and result appear in the TUI.

### `renderCall` Signature

```typescript
renderCall(args: MyToolParams, theme: Theme): Component
```

A 3rd `context` param is available from the framework but rarely needed in `renderCall`.

Use `ToolCallHeader` from `@aliou/pi-utils-ui`:

```typescript
renderCall(args: MyToolParams, theme: Theme) {
  return new ToolCallHeader(
    {
      toolName: "My Tool",
      action: "search",           // Optional: for multi-action tools
      mainArg: `"${args.query}"`, // Primary thing user scans for
      optionArgs: [`limit=${args.limit ?? 10}`], // Compact key-value pairs
      longArgs: [],               // Long text goes here
      showColon: true,            // Whether to show colon after tool name
    },
    theme,
  );
}
```

### `renderResult` Signature

```typescript
renderResult(
  result: AgentToolResult<TDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
): Component
```

- `options` has `expanded` and `isPartial`
- `result.details` is `{}` (empty object) when the tool threw an error
- A 4th `context` param is available (see Error Handling above) but not required

```typescript
renderResult(
  result: AgentToolResult<MyToolDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
) {
  // 1. Handle partial state first with stable message
  if (options.isPartial) {
    return new Text(theme.fg("muted", "MyTool: fetching..."), 0, 0);
  }

  const { details } = result;

  // 2. Handle errors: details is {} when tool threw
  if (!details?.results) {
    const textBlock = result.content.find((c) => c.type === "text");
    const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Operation failed";
    return new Text(theme.fg("error", errorMsg), 0, 0);
  }

  // 3. Build fields for ToolBody (showCollapsed controls collapsed/expanded visibility)
  const items = details.results;

  const fields: Array<{ label: string; value: string; showCollapsed?: boolean } | Text> = [
    { label: "Results", value: `${items.length} items`, showCollapsed: true },
  ];

  // 4. Build conditional footer
  const footerItems: Array<{ label: string; value: string }> = [];
  if (items.length > 0) {
    footerItems.push({ label: "count", value: `${items.length}` });
  }

  return new ToolBody(
    {
      fields,
      footer: footerItems.length > 0
        ? new ToolFooter(theme, { items: footerItems, separator: " | " })
        : undefined,
      includeSpacerBeforeFooter: fields.length > 0,
    },
    options,
    theme,
  );
}
```

### `renderCall` Design Guide

The `process` extension is a good baseline. Its call renderer is deterministic and keeps headers readable.

Use this extraction order when building header parts:

1. **Action first**: always show action for multi-action tools (`start`, `list`, `kill`, ...).
2. **Pick one main arg**: choose the single value the user scans for first (name, id, or short command).
3. **Promote short fields to options**: compact values become option args (`end=true`, `limit=10`).
4. **Demote long fields to long args**: commands/prompts/instructions move to labeled follow-up lines.
5. **Keep it stable**: same inputs should produce same ordering and formatting.

Implementation pattern:
- Build `mainArg`, `optionArgs`, `longArgs` first, then pass to `ToolCallHeader`.
- Quote user-provided names (`"backend"`) when that improves visual parsing.
- Cap inline length (e.g. 60-80 chars), then spill to `longArgs`.

### `renderResult` Guidelines

- Handle `isPartial` first with a **stable, tool-scoped message** like `"MyTool: fetching..."`. Do NOT echo streaming content.
- Handle errors by checking for missing expected fields in `details` (framework sets `details: {}` on throw). Alternatively use the 4th `context` param with `context.isError`.
- Use `ToolBody` with `showCollapsed: true` fields for collapsed/expanded filtering.
- Use `ToolFooter` for stats/metadata. Omit when empty: `footer: items.length > 0 ? new ToolFooter(...) : undefined`.
- Use `includeSpacerBeforeFooter: fields.length > 0` to avoid blank line when body is empty.
- Remove redundant success footer items — don't show `status: ok` when success is obvious.
- Use `Container` + `addChild()` for multi-element results instead of string concatenation.
- Use `Markdown` component for rich markdown content:
  ```typescript
  new Markdown(text, 0, 0, getMarkdownTheme(), { color: (t) => theme.fg("toolOutput", t) })
  ```
- Use `keyHint("app.tools.expand", "to expand")` for expand hints.
- Collapsed result should show **actionable preview** (last N lines, first N items with status), not just a status badge.
- Humanize error messages with names first: `"Could not get X for "name" (id)"`.

## Tool UI Rendering Guidelines

When customizing tool rendering, keep call/result UI predictable and scannable.

### `renderCall` format

Use this line model:

- First line: `[Tool Name]: [Action] [Main arg] [Option args]`
- Additional lines: long args only

Guidelines:
- Tool name should be a human display label (`label`), not a raw internal identifier (`name`).
- Show `action` only when it adds meaning (multi-action tools like process managers).
- Main arg should be the primary thing user cares about (query, session id, target id/name).
- Option args should be compact key-value pairs (`limit=10`, `cwd=/path`).
- Long text (prompt/task/question/context/instructions) goes to additional lines.
- Prefer wrapping to preserve full meaning over aggressive truncation.
- For tools without actions, omit colon suffix after tool name if that reads better in your UI system.

### `renderResult` layout

- Handle `isPartial` first. Return a short stable loading state with tool-scoped message.
- Keep the first non-loading line as a status summary (`Found N results`, `Updated 3 files`, `Failed: reason`).
- Use `expanded` to switch between compact and full output. Compact should show the top few items plus an omission hint.
- Keep body content focused on state + key output; avoid dumping raw JSON unless it is the actual output.
- If you render a footer (stats, backend, counts), use `includeSpacerBeforeFooter` to control blank line.
- Keep footer concise and stable across states.
- Return `undefined` when custom rendering adds no value; fallback rendering is better than noisy UI.

## Tool Call + UI Consistency Contract

Use this contract to keep tool UX consistent across extensions:

1. **Call line is for scanability**: `renderCall` first line follows `[Tool Name]: [Action] [Main arg] [Option args]`.
2. **Result detects errors** by checking for missing expected fields in `details` (framework sets `details: {}` on throw).
3. **Long text moves down**: prompts, instructions, and context go to follow-up lines, not the call header.
4. **Partial updates use a fixed tool-scoped string**, not echoed streaming content.
5. **Expanded controls density**: compact view shows summary + subset; expanded view shows full detail.
6. **No mode leaks in tool renderers**: `renderCall`/`renderResult` should not branch on mode. Mode-specific behavior belongs in command/tool logic (`references/modes.md`).

Related references:
- `references/modes.md` for `custom()` fallback behavior and RPC/Print handling.
- `references/components.md` for interactive component authoring.
- `references/messages.md` for persistent display via `sendMessage` + `registerMessageRenderer`.

## Naming Conventions

For extensions wrapping a third-party API, prefix tool names with the API name to avoid conflicts:

```
linkup_web_search
linkup_web_fetch
synthetic_web_search
```

For internal/custom tools, no prefix is needed:

```
get_current_time
processes
```

Use snake_case for all tool names.

## Abort Signal

The `signal` parameter lets you cancel long-running operations when the user interrupts (e.g. pressing Escape). If the tool does not forward the signal, the underlying operation keeps running even after the user cancels, wasting resources and API credits.

```typescript
execute: async (toolCallId, params, signal, onUpdate, ctx) => {
  const response = await fetch(url, { signal });
  // If the user cancels, fetch throws an AbortError
  return { content: [{ type: "text", text: await response.text() }], details: {} };
},
```

Pass `signal` to every async operation that supports it: `fetch()` calls, `pi.exec()` calls, SDK clients, etc.

When wrapping an API client, thread the signal through the entire call chain. The client methods should accept an optional `signal` and forward it to the underlying `fetch()`:

```typescript
// In the tool:
async execute(_toolCallId, params, signal, onUpdate, ctx) {
  const result = await client.search({ query: params.query, signal });
  // ...
}

// In the client:
async search(params: { query: string; signal?: AbortSignal }) {
  return this.request("/search", { method: "POST", body: ... }, params.signal);
}

private async request<T>(endpoint: string, options: RequestInit = {}, signal?: AbortSignal) {
  return fetch(`${BASE_URL}${endpoint}`, { ...options, signal, headers: { ... } });
}
```

Do not prefix signal with underscore (`_signal`) unless the tool genuinely cannot use it. A dangling `_signal` is a sign of a missing cancellation path.

## Output Truncation

For tools that may return large outputs, use `truncateHead()` which returns a `TruncationResult`:

```typescript
import { truncateHead, formatSize } from "@mariozechner/pi-coding-agent";
import { createWriteStream } from "fs";
import { tmpdir } from "os";
import { join } from "path";

interface FetchDetails {
  content: string;
  url: string;
  truncated: boolean;
  totalLines: number;
  totalBytes: number;
  outputLines: number;
  outputBytes: number;
  tempFile?: string;
}

async execute(
  _toolCallId: string,
  params: FetchParams,
  signal: AbortSignal | undefined,
  _onUpdate: undefined,
  _ctx: ExtensionContext,
): Promise<AgentToolResult<FetchDetails>> {
  const response = await fetch(params.url, { signal });
  const fullContent = await response.text();

  // truncateHead keeps the tail (most recent content)
  const truncated = truncateHead(fullContent, {
    maxBytes: 50000,
    maxLines: 2000,
  });

  const details: FetchDetails = {
    content: truncated.content,
    url: params.url,
    truncated: truncated.truncated,
    totalLines: truncated.totalLines,
    totalBytes: truncated.totalBytes,
    outputLines: truncated.outputLines,
    outputBytes: truncated.outputBytes,
  };

  // Write full content to temp file if truncated
  if (truncated.truncated) {
    const tempFile = join(tmpdir(), `web-fetch-${Date.now()}.txt`);
    const stream = createWriteStream(tempFile);
    stream.write(fullContent);
    stream.end();
    details.tempFile = tempFile;
  }

  return {
    content: [{ type: "text", text: truncated.content }],
    details,
  };
}
```

### Truncation Result Fields

```typescript
interface TruncationResult {
  content: string;      // The truncated content (or full if not truncated)
  truncated: boolean;   // Whether truncation occurred
  totalLines: number;   // Original total lines
  totalBytes: number;   // Original total bytes
  outputLines: number;  // Lines in output
  outputBytes: number;  // Bytes in output
}
```

### Rendering Truncated Output

```typescript
renderResult(
  result: AgentToolResult<FetchDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
) {
  if (options.isPartial) {
    return new Text(theme.fg("muted", "WebFetch: fetching..."), 0, 0);
  }

  const { details } = result;

  if (!details?.content) {
    const textBlock = result.content.find((c) => c.type === "text");
    const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Fetch failed";
    return new Text(theme.fg("error", errorMsg), 0, 0);
  }
  const container = new Container();

  // Body with content preview
  const fields = [
    { label: "URL", value: details.url, showCollapsed: true },
    { label: "Size", value: formatSize(details.totalBytes), showCollapsed: true },
  ];

  container.addChild(new ToolBody(theme, { fields, expanded: options.expanded }));

  // Footer with truncation info
  const footerItems = [];

  if (details.truncated) {
    footerItems.push(
      { label: "showing", value: `${details.outputLines}/${details.totalLines} lines` },
      { label: "full output", value: details.tempFile ?? "temp file" },
    );
  } else {
    footerItems.push({ label: "lines", value: `${details.totalLines}` });
  }

  container.addChild(
    new ToolFooter(theme, {
      items: footerItems,
      separator: " | ",
      includeSpacerBeforeFooter: fields.length > 0,
    }),
  );

  return container;
}
```

## Multi-Action Tools

For tools with multiple actions (e.g., `start`, `list`, `kill`), organize code for maintainability:

### File Structure

```
tools/
  my_tool/
    index.ts           // Tool definition, registration, execute switch
    actions/
      start.ts         // start action implementation
      list.ts          // list action implementation
      kill.ts          // kill action implementation
    render.ts          // renderCall and renderResult (when complex)
    types.ts           // Shared types and param schema
```

### Action Pattern

Each action takes an SDK client and typed params, returns typed results:

```typescript
// actions/start.ts
export interface StartParams {
  name: string;
  command: string;
  cwd?: string;
}

export interface StartResult {
  sessionId: string;
  pid: number;
}

export async function start(
  client: MyClient,
  params: StartParams,
  signal?: AbortSignal,
): Promise<StartResult> {
  return client.startSession({
    name: params.name,
    command: params.command,
    cwd: params.cwd,
    signal,
  });
}
```

### Execute Delegation

```typescript
// index.ts
async execute(
  toolCallId: string,
  params: MyToolParams,
  signal: AbortSignal | undefined,
  onUpdate: AgentToolUpdateCallback<MyToolDetails> | undefined,
  ctx: ExtensionContext,
): Promise<AgentToolResult<MyToolDetails>> {
  switch (params.action) {
    case "start":
      return startAction(client, params, signal, onUpdate, ctx);
    case "list":
      return listAction(client, params, signal);
    case "kill":
      return killAction(client, params, signal);
    default:
      throw new Error(`Unknown action: ${params.action}`);
  }
}
```

### Separate Render Module

When rendering is complex, extract to `render.ts`:

```typescript
// render.ts
export function renderCall(args: MyToolParams, theme: Theme) {
  return new ToolCallHeader(
    {
      toolName: "MyTool",
      action: args.action,
      mainArg: getMainArg(args),
      optionArgs: getOptionArgs(args),
      longArgs: getLongArgs(args),
    },
    theme,
  );
}

export function renderResult(
  result: AgentToolResult<MyToolDetails>,
  options: ToolRenderResultOptions,
  theme: Theme,
) {
  // Complex rendering logic here
}
```

```typescript
// index.ts
import { renderCall, renderResult } from "./render.js";

const myTool = {
  // ...
  renderCall,
  renderResult,
};
```

**Examples to reference:**
- `pi-processes`: Multi-action process management with complex rendering
- `pi-linear`: Multi-action Linear API integration

## Full Example

Here's a realistic tool demonstrating all the patterns:

```typescript
import { ToolCallHeader, ToolBody, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { keyHint, formatSize } from "@mariozechner/pi-coding-agent";
import { Container, Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@mariozechner/pi-coding-agent";

// Schema
const parameters = Type.Object({
  owner: Type.String({ description: "Repository owner" }),
  repo: Type.String({ description: "Repository name" }),
  path: Type.Optional(Type.String({ description: "File or directory path", default: "" })),
});

// Typed aliases
type RepoTreeParams = Static<typeof parameters>;

interface RepoTreeDetails {
  owner: string;
  repo: string;
  path: string;
  entries: Array<{ name: string; type: "file" | "dir"; size?: number }>;
  truncated: boolean;
}

// Tool definition
const repoTreeTool = {
  name: "repo_tree",
  label: "Repo Tree",
  description: "List files and directories in a GitHub repository.",
  promptSnippet: "Browse repository file structure",
  promptGuidelines: [
    "Use this to explore repository structure before reading files",
    "Start with root path, then drill down into directories",
  ],
  parameters,

  async execute(
    _toolCallId: string,
    params: RepoTreeParams,
    signal: AbortSignal | undefined,
    _onUpdate: undefined,
    _ctx: ExtensionContext,
  ): Promise<AgentToolResult<RepoTreeDetails>> {
    const response = await fetch(
      `https://api.github.com/repos/${params.owner}/${params.repo}/contents/${params.path ?? ""}`,
      { signal, headers: { Accept: "application/vnd.github.v3+json" } },
    );

    if (!response.ok) {
      if (response.status === 404) {
        throw new Error(
          `Could not find repository "${params.owner}/${params.repo}" or path "${params.path ?? ""}"`,
        );
      }
      throw new Error(`GitHub API error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();

    // GitHub returns a single object for files, array for directories
    const entries = Array.isArray(data) ? data : [data];

    const processed = entries.map((entry: any) => ({
      name: entry.name,
      type: entry.type === "dir" ? "dir" as const : "file" as const,
      size: entry.size,
    }));

    // Sort: directories first, then files, alphabetically within each
    processed.sort((a, b) => {
      if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
      return a.name.localeCompare(b.name);
    });

    const truncated = processed.length > 100;

    return {
      content: [
        {
          type: "text",
          text: JSON.stringify(truncated ? processed.slice(0, 100) : processed, null, 2),
        },
      ],
      details: {
        owner: params.owner,
        repo: params.repo,
        path: params.path ?? "",
        entries: processed,
        truncated,
      },
    };
  },

  renderCall(args: RepoTreeParams, theme: Theme) {
    return new ToolCallHeader(
      {
        toolName: "Repo Tree",
        mainArg: `${args.owner}/${args.repo}`,
        optionArgs: args.path ? [`path=${args.path}`] : [],
        longArgs: [],
      },
      theme,
    );
  },

  renderResult(
    result: AgentToolResult<RepoTreeDetails>,
    options: ToolRenderResultOptions,
    theme: Theme,
  ) {
    // 1. Stable partial message
    if (options.isPartial) {
      return new Text(theme.fg("muted", "RepoTree: fetching..."), 0, 0);
    }

    const { details } = result;

    // 2. Error handling: details is {} when tool threw
    if (!details?.entries) {
      const textBlock = result.content.find((c) => c.type === "text");
      const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Failed to list repository";
      return new Text(theme.fg("error", errorMsg), 0, 0);
    }
    const container = new Container();
    const entries = details?.entries ?? [];
    const dirs = entries.filter((e) => e.type === "dir");
    const files = entries.filter((e) => e.type === "file");

    // 3. Body fields with showCollapsed for collapsed/expanded control
    const fields: Array<{ label: string; value: string; showCollapsed: boolean }> = [
      {
        label: "Location",
        value: `${details.owner}/${details.repo}${details.path ? `/${details.path}` : ""}`,
        showCollapsed: true,
      },
      {
        label: "Contents",
        value: `${dirs.length} dirs, ${files.length} files`,
        showCollapsed: true,
      },
    ];

    container.addChild(new ToolBody(theme, { fields, expanded: options.expanded }));

    // 4. Entry list (in expanded view)
    if (options.expanded && entries.length > 0) {
      const entryLines = entries
        .slice(0, 50)
        .map((e) => {
          const icon = e.type === "dir" ? "📁" : "📄";
          const size = e.size !== undefined ? ` (${formatSize(e.size)})` : "";
          return `${icon} ${e.name}${size}`;
        })
        .join("\n");

      container.addChild(new Text(entryLines, 0, 0));

      if (entries.length > 50) {
        container.addChild(
          new Text(theme.fg("muted", `... and ${entries.length - 50} more`), 0, 0),
        );
      }
    }

    // 5. Conditional footer
    const footerItems = [];

    if (details?.truncated) {
      footerItems.push({ label: "showing", value: "first 100 entries" });
    }

    if (entries.length > 0) {
      footerItems.push({ label: "total", value: `${entries.length} items` });
    }

    if (!options.expanded && entries.length > 5) {
      footerItems.push({ label: "", value: keyHint("app.tools.expand", "to expand") });
    }

    if (footerItems.length > 0) {
      container.addChild(
        new ToolFooter(theme, {
          items: footerItems,
          separator: " | ",
          includeSpacerBeforeFooter: fields.length > 0,
        }),
      );
    }

    return container;
  },
};

export default function (pi: ExtensionAPI) {
  pi.registerTool(repoTreeTool);
}
```

# Commands

Commands are user-invoked actions triggered with `/command-name` in the input editor.

## Registration

```typescript
pi.registerCommand("my-command", {
  description: "What this command does",
  handler: async (args, ctx) => {
    // args: string (everything after the command name)
    // ctx: ExtensionContext
  },
});
```

## Command Context

The `ctx` parameter provides the same `ExtensionContext` as hooks, with access to `ctx.ui`, `ctx.hasUI`, `ctx.cwd`, etc.

Commands are interactive by nature (the user typed them), so `ctx.hasUI` is usually `true`. However, commands can also be invoked programmatically (for example via RPC), so the three-tier pattern still applies.

## Simple Command

```typescript
pi.registerCommand("balance", {
  description: "Check API balance",
  handler: async (_args, ctx) => {
    const balance = await fetchBalance();
    ctx.ui.notify(`Balance: $${balance.toFixed(2)}`, "info");
  },
});
```

## Command with Rich Display

When a command needs a rich TUI display, use the three-tier pattern from `references/modes.md`:

```typescript
pi.registerCommand("quotas", {
  description: "Show API quotas",
  handler: async (_args, ctx) => {
    const quotas = await fetchQuotas();

    // Print mode
    if (!ctx.hasUI) {
      console.log(formatQuotasPlain(quotas));
      return;
    }

    // Interactive mode: full TUI component.
    // Use explicit sentinel value for close/cancel, not undefined.
    const result = await ctx.ui.custom<"closed">((tui, theme, _kb, done) => {
      return new QuotasDisplay(theme, quotas, () => done("closed"));
    });

    // RPC mode: custom() returns undefined by design.
    if (result === undefined) {
      ctx.ui.notify(formatQuotasPlain(quotas), "info");
    }
  },
});
```

Do not use `done(undefined)` in normal interactive close paths if you rely on `result === undefined` to detect RPC fallback.

## Extracting Components

Keep command handlers thin. Extract the TUI component into a separate file:

```
src/
  commands/
    quotas.ts              # Handler + formatQuotasPlain
  components/
    quotas-display.ts      # QuotasDisplay component class
```

The component file should export the component class. The command file imports it and wires up the handler.

## Arguments

The `args` parameter is the raw string after the command name. Parse it yourself:

```typescript
handler: async (args, ctx) => {
  const parts = args.trim().split(/\s+/);
  const subcommand = parts[0];
  // ...
},
```

## Command vs Tool

| Aspect | Command | Tool |
|---|---|---|
| Invoked by | User (typing `/name`) | LLM (during a turn) |
| Purpose | User-facing actions, settings, displays | LLM capabilities |
| UI access | Full (user is present) | Limited (LLM is driving) |
| Return value | void | `AgentToolResult` (output for LLM) |

# Hooks (Events)

Hooks let extensions react to lifecycle events. They are registered with `pi.on(eventName, handler)`.

## Event Reference

### Session Events

| Event | When | Can Cancel | Payload |
|---|---|---|---|
| `session_start` | Session starts, reloads, or is replaced | No | `{ reason: "startup" \| "reload" \| "new" \| "resume" \| "fork", previousSessionFile? }` |
| `session_before_switch` | Before `/new` or `/resume` replaces the current session | Yes (`{ cancel: true }`) | `{ reason: "new" \| "resume", targetSessionFile? }` |
| `session_before_fork` | Before forking a session | Yes (`{ cancel: true }`) | `{ entryId }` |
| `session_shutdown` | Current session runtime is shutting down or being replaced | No | `{}` |
| `session_before_compact` | Before compaction | Yes (cancel or provide custom compaction) | event-specific compaction data |

### Agent Events

| Event | When | Payload |
|---|---|---|
| `before_agent_start` | Before agent turn starts | `{}` |
| `agent_start` | Agent turn started | `{}` |
| `turn_start` | Turn begins processing | `{}` |
| `turn_end` | Turn finishes processing | `{}` |
| `model_select` | User changed the model | `{ model: string }` |

### Tool Events

| Event | When | Can Block | Payload |
|---|---|---|---|
| `tool_call` | Before a tool executes | Yes (`{ block: true, reason }`) | `{ toolName, toolCallId, input }` |

### Input Events

| Event | When | Can Transform | Payload |
|---|---|---|---|
| `input` | User submitted a message | Yes (return transformed text) | `{ text: string }` |

### Bash Events

| Event | When | Can Modify | Payload |
|---|---|---|---|
| `user_bash` | Before bash command runs | Yes (return modified command/cwd/env) | `{ command, cwd }` |

## Handler Signature

```typescript
pi.on("event_name", async (event, ctx) => {
  // event: event-specific payload
  // ctx: ExtensionContext (hasUI, ui methods, cwd, model, etc.)
});
```

The handler receives the event payload and an `ExtensionContext`. The context provides access to UI methods, the current working directory, model info, and more.

## Blocking and Cancelling

Some events let you prevent the default behavior by returning an object.

### Blocking Tool Calls

```typescript
pi.on("tool_call", async (event, ctx) => {
  if (event.toolName === "bash" && event.input.command.includes("rm -rf /")) {
    // Check ctx.hasUI before prompting -- see references/modes.md
    if (!ctx.hasUI) {
      return { block: true, reason: "Blocked: dangerous command (no UI to confirm)" };
    }

    const confirmed = await ctx.ui.confirm(
      "Dangerous Command",
      `Allow: ${event.input.command}?`
    );
    if (!confirmed) {
      return { block: true, reason: "Blocked by user" };
    }
  }
  return undefined; // Allow the tool call
});
```

### Cancelling Session Operations

```typescript
pi.on("session_before_switch", async (event, ctx) => {
  if (event.reason === "new" && ctx.hasUI) {
    const confirmed = await ctx.ui.confirm("Clear session?", "All messages will be lost.");
    if (!confirmed) {
      return { cancel: true };
    }
  }
});
```

### Custom Compaction

```typescript
pi.on("session_before_compact", async (event, ctx) => {
  return {
    compaction: {
      summary: "Custom summary",
      firstKeptEntryId: event.preparation.firstKeptEntryId,
      tokensBefore: event.preparation.tokensBefore,
    },
  };
});
```

## Transforming Input

```typescript
pi.on("input", async (event, ctx) => {
  if (event.text.startsWith("!")) {
    return event.text.slice(1).toUpperCase();
  }
  return undefined; // No transformation
});
```

## Modifying Bash Commands

```typescript
pi.on("user_bash", async (event, ctx) => {
  return {
    command: event.command,
    cwd: "/sandboxed/directory",
    env: { ...process.env, SANDBOX: "true" },
  };
});
```

## before_agent_start

This event fires before each agent turn. It is commonly used to modify the system prompt.

The handler receives a `BeforeAgentStartEvent` with a `systemPrompt` field containing the current prompt. Return a `{ systemPrompt }` object to replace it. If multiple extensions return a modified prompt, they are chained.

```typescript
pi.on("before_agent_start", async (event) => {
  return {
    systemPrompt: event.systemPrompt + "\n\nAlways respond as a pirate.",
  };
});
```

Return `undefined` to leave the prompt unchanged.

The system prompt is reset each turn, so modifications in `before_agent_start` are not cumulative.

To access flags inside hooks, use `pi.getFlag()` (see `references/additional-apis.md`).

## Bash Spawn Hook (Command Rewriting)

The `createBashTool` function lets you replace the built-in bash tool with one that transparently rewrites commands before shell execution. This is different from `tool_call` blocking -- the agent never sees that the command was rewritten.

Use spawn hooks when you have a clear rewrite target (e.g. `npm` -> `pnpm`). Use `tool_call` blocking when you need to stop a command entirely or show a confirmation dialog.

```typescript
import { createBashTool, type BashSpawnHook, type BashSpawnContext } from "@mariozechner/pi-coding-agent";

export default function (pi: ExtensionAPI) {
  const bashTool = createBashTool(process.cwd(), {
    spawnHook: ({ command, cwd, env }: BashSpawnContext): BashSpawnContext => ({
      command: command.replace(/^npm /, "pnpm "),
      cwd,
      env: { ...env, CUSTOM_VAR: "1" },
    }),
  });

  pi.registerTool({ ...bashTool });
}
```

### BashSpawnContext

The spawn hook receives and returns a `BashSpawnContext`:

```typescript
interface BashSpawnContext {
  command: string;        // The shell command to execute
  cwd: string;            // Working directory
  env: NodeJS.ProcessEnv; // Environment variables
}
```

You can modify any of these fields. The hook runs after pi's own processing but before the shell spawns.

### Key Points

- **Replaces the built-in bash tool.** When you call `pi.registerTool()` with a tool named `"bash"`, it replaces the default. Only one extension should do this.
- **Transparent to the agent.** The agent sees the original command in the tool call UI but gets the output of the rewritten command.
- **Execution order with tool_call hooks.** `tool_call` event hooks (blockers) run first. If a blocker returns `{ block: true }`, the spawn hook never fires. This means you can combine blocking hooks for commands that should be stopped entirely with spawn hooks for commands that should be rewritten.
- **Prefer AST-based rewrites over regex.** A false positive rewrite corrupts a command silently. Use `@aliou/sh` or similar shell parsers to identify command names in the AST, then do surgical string replacement at the identified positions. If the parse fails, return the command unchanged.
- **Compose multiple rewriters.** Chain rewriter functions that each transform the context:

```typescript
const rewriters: ((ctx: BashSpawnContext) => BashSpawnContext)[] = [
  createPackageManagerRewriter(config),
  createGitRebaseRewriter(),
];

const spawnHook = (ctx: BashSpawnContext) => {
  let result = ctx;
  for (const rewrite of rewriters) {
    result = rewrite(result);
  }
  return result;
};

const bashTool = createBashTool(process.cwd(), { spawnHook });
pi.registerTool({ ...bashTool });
```

### When to Use What

| Pattern | Use When | Agent Sees |
|---|---|---|
| `tool_call` hook + `{ block: true }` | Command must be stopped entirely | Block reason (retries with correct command) |
| `tool_call` hook + `ctx.ui.confirm()` | User confirmation needed | Block reason if denied |
| Spawn hook (command rewrite) | Clear 1:1 rewrite target exists | Output of rewritten command (transparent) |
| Spawn hook (env injection) | Need to set env vars for specific commands | Output with injected env (transparent) |

## Multiple Handlers

Multiple extensions can register handlers for the same event. They execute in registration order. For blocking events (`tool_call`, `session_before_switch`, etc.), the first handler to return a blocking/cancelling result wins.

## Mode Awareness in Hooks

Always consider what happens in Print mode when your hook uses dialog methods. See `references/modes.md` for the full behavior matrix.

Common pattern for `tool_call` handlers:

```typescript
pi.on("tool_call", async (event, ctx) => {
  if (shouldBlock(event)) {
    if (!ctx.hasUI) {
      return { block: true, reason: "No UI to confirm" };
    }
    // Safe to use dialogs here
    const choice = await ctx.ui.select("Allow?", ["Yes", "No"]);
    if (choice !== "Yes") {
      return { block: true, reason: "Blocked by user" };
    }
  }
  return undefined;
});
```

# Additional APIs

These APIs are available on `ExtensionAPI` and `ExtensionContext` but are less commonly used. Each is shown with a minimal example.

When you implement something using one of these APIs, update this skill reference with a fuller example based on your actual usage.

## Shortcuts

Register global keyboard shortcuts:

```typescript
pi.registerShortcut("ctrl+shift+p", {
  description: "Toggle plan mode",
  handler: async (ctx) => {
    planModeEnabled = !planModeEnabled;
    ctx.ui.setStatus("plan", planModeEnabled ? "Plan Mode" : "");
  },
});
```

Shortcuts work only in Interactive mode.

## Flags

Register boolean flags that persist across sessions:

```typescript
// Register
pi.registerFlag("auto-commit", {
  description: "Auto-commit after each turn",
  default: false,
});

// Read (in any handler)
const autoCommit = pi.getFlag("auto-commit");
```

Users toggle flags with `/flag auto-commit` in the input editor.

## sendUserMessage

Inject a user message into the conversation programmatically:

```typescript
pi.sendUserMessage("Please summarize what we just discussed");
```

This triggers a full agent turn as if the user typed the message. Useful for file watchers, timers, or other automated triggers.

## Session Name

Set or get a name for the current session (shown in the session selector):

```typescript
pi.setSessionName("Feature: Auth Refactor");
const name = pi.getSessionName();
```

## Labels

Set a label on a specific session entry (shown in `/tree` view):

```typescript
pi.setLabel(entryId, "checkpoint: before refactor");
```

## exec

Run a shell command and get the result. This is the **only** way to run external binaries or shell scripts from an extension.

```typescript
const result = await pi.exec("git status --porcelain", { cwd: process.cwd() });
// result: { stdout, stderr, exitCode }
```

Useful for git operations, environment checks, running CLI tools, etc.

**Do not use Node `child_process` APIs** (`exec`, `execSync`, `spawn`, `spawnSync`, `execFile`, `execFileSync`). `pi.exec` handles CWD resolution, output capture, and integrates with the extension lifecycle. Using `child_process` directly bypasses these guarantees and creates inconsistent behavior across environments.

The only exception is a long-lived streaming process that requires direct stdin/stdout piping — document the reason in code comments if this applies.

## Active Tools

Get or set which tools are currently active:

```typescript
const tools = pi.getActiveTools(); // string[]
pi.setActiveTools(["bash", "read", "write", "my_custom_tool"]);
```

Setting active tools restricts which tools the LLM can use.

## Model Control

```typescript
// Set the active model
pi.setModel("anthropic/claude-sonnet-4-20250514");

// Get/set thinking level
const level = pi.getThinkingLevel(); // "none" | "low" | "medium" | "high"
pi.setThinkingLevel("high");
```

## System Prompt

Read or modify the system prompt (typically in `before_agent_start`):

```typescript
pi.on("before_agent_start", async (_event, ctx) => {
  const prompt = ctx.getSystemPrompt();
  ctx.setSystemPrompt(prompt + "\n\nExtra instructions.");
});
```

The system prompt resets each turn, so modifications are not cumulative.

### Guidance Injection Pattern

Extensions that add tools or behavioral patterns the agent may not know how to use correctly should inject guidance into the system prompt. Without it, agents fall back to bash workarounds even when a better tool is available.

**When to inject guidance:**
- Your extension adds a tool that competes with a natural bash fallback (e.g. a process manager, a CI watcher, a search tool)
- Correct usage depends on subtle conditions (alert flags, when-not-to-use, alert vs. poll)
- You have observed agents ignoring the tool or reaching for `bash` instead

**When not to:**
- The tool description alone is self-explanatory
- The tool has no plausible bash alternative

---

There are two ways to inject guidance, depending on complexity:

#### Tier 1: Per-Tool Metadata (Preferred for Simple Tools)

For most tools, use the SDK-level `promptSnippet` and `promptGuidelines` fields directly on the tool definition. No hook is needed.

- **`promptSnippet`** — Injected into the "Available tools" system prompt section. Use for a concise (1–2 sentence) description of when to prefer this tool.
- **`promptGuidelines`** — Appended to the "Guidelines" section. Use for a short list of usage rules.

```typescript
const myTool = {
  name: "my_tool",
  label: "My Tool",
  description: "...",
  promptSnippet: "Manage background processes without blocking the conversation.",
  promptGuidelines: [
    "Use this tool for long-running commands instead of bash.",
    "After starting a process, continue other work instead of waiting.",
  ],
  parameters: ...,
  execute: ...,
};
```

This is the simplest approach and works well when guidance is specific to a single tool.

#### Tier 2: System Prompt Hook (For Complex Cross-Tool Orchestration)

Use the `before_agent_start` hook when:
- Guidance involves **cross-tool workflow instructions** (e.g. "use tool A, then tool B, then tool C")
- You need **dynamic context from config** (e.g. workspace names, team keys, feature flags)
- The per-tool metadata fields aren't expressive enough

**Structure: three files**

`src/guidance.ts` — the guidance text as a named export:

```typescript
export const MY_EXTENSION_GUIDANCE = `
## My Extension

Use the \`my_tool\` tool for X. Don't use bash for X.

**Use \`my_tool\` when:**
- Situation A
- Situation B

**Use \`bash\` when:**
- You need the result immediately to proceed (quick commands that finish in seconds)

**Never do this:**
\`\`\`bash
workaround_command  # loses observability
\`\`\`

**Do this instead:**
\`\`\`
my_tool({ action: "start", ... })
\`\`\`
`;
```

`src/hooks/system-prompt.ts` — the hook:

```typescript
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { configLoader } from "../config";
import { MY_EXTENSION_GUIDANCE } from "../guidance";

export function registerGuidance(pi: ExtensionAPI): void {
  pi.on("before_agent_start", async (event) => {
    const config = configLoader.getConfig();
    if (!config.systemPromptGuidance) return;

    return {
      systemPrompt: `${event.systemPrompt}\n${MY_EXTENSION_GUIDANCE}`,
    };
  });
}
```

`src/config.ts` — add the toggle (default `true`):

```typescript
export interface MyExtensionConfig {
  // ...
  /** Inject tool guidance into the system prompt each turn. Default: true. */
  systemPromptGuidance?: boolean;
}
```

Call `registerGuidance(pi)` from your hooks setup function.

---

**What makes guidance effective:**

- Lead with the decision rule: **when to use AND when not to use**. The when-not-to-use is as important — it gives the agent permission to keep using `bash` for quick tasks and prevents overcorrection.
- Name anti-patterns explicitly by their exact form (`cmd &`, `nohup`, `sleep 30 &&`). Abstract descriptions ("don't use bash workarounds") are ignored.
- Use 2–3 tight code examples. More than that dilutes attention; fewer leave the pattern underspecified.
- Keep the guidance section header (`## My Extension`) so it reads as a named capability, not a restriction.
- Avoid stacking emphasis markers (`NEVER`, `ALWAYS`, `IMPORTANT`). One or two land; more are ignored.

**Reference implementations:**
- `pi-linkup` — Uses per-tool `promptSnippet`/`promptGuidelines` (simple tools, no hook needed).
- `pi-linear` — Uses `guidance.ts` + `before_agent_start` hook (cross-tool workflow instructions + dynamic workspace context).
- `pi-processes` — Uses both: `promptSnippet`/`promptGuidelines` on tools for basic guidance, plus system prompt hook for complex multi-tool orchestration patterns.

## Compaction

Trigger compaction programmatically:

```typescript
await pi.compact();
```

## Shutdown

Shut down pi gracefully:

```typescript
pi.shutdown();
```

## EventBus

Inter-extension communication via a shared event bus:

```typescript
// Extension A: emit
pi.events.emit("my-extension:data-ready", { items: [...] });

// Extension B: listen
pi.events.on("my-extension:data-ready", (data) => {
  console.log("Received:", data.items.length, "items");
});
```

Namespace event names with your extension name to avoid collisions. The event bus is supplementary -- most extensions do not need it. Use it when two extensions need to coordinate.

