import { ConfigLoader, buildSchemaUrl } from "@aliou/pi-utils-settings";
import pkg from "../package.json" with { type: "json" };

/**
 * Raw config shape (what gets saved to disk).
 * All fields optional -- only overrides are stored.
 *
 * JSDoc comments on fields become `description` in the generated JSON Schema.
 * Run `pnpm gen:schema` after changing this interface.
 */
export interface PlaydateConfig {
  /** Override the PLAYDATE_SDK_PATH environment variable. */
  sdkPath?: string;
  /** Default build/run target. */
  defaultTarget?: "simulator" | "device";
  /** Build mode for C projects. */
  buildMode?: "debug" | "release";
  /** Path to arm-none-eabi toolchain (for C builds on Windows/Linux if not auto-detected). */
  armToolchainPath?: string;
  /** Automatically open the simulator after building. */
  autoOpenSimulator?: boolean;
  /** Number of simulator log lines to keep in the ring buffer. */
  simulatorLogLines?: number;
}

/**
 * Resolved config (defaults merged in).
 * All fields required.
 */
export interface ResolvedPlaydateConfig {
  sdkPath: string;
  defaultTarget: "simulator" | "device";
  buildMode: "debug" | "release";
  armToolchainPath: string;
  autoOpenSimulator: boolean;
  simulatorLogLines: number;
}

const DEFAULTS: ResolvedPlaydateConfig = {
  sdkPath: "",
  defaultTarget: "simulator",
  buildMode: "debug",
  armToolchainPath: "",
  autoOpenSimulator: true,
  simulatorLogLines: 200,
};

const schemaUrl = buildSchemaUrl(pkg.name, pkg.version);

export const configLoader = new ConfigLoader<
  PlaydateConfig,
  ResolvedPlaydateConfig
>("playdate", DEFAULTS, { schemaUrl });

/**
 * Ephemeral runtime state -- lives in memory only, cleared on session_shutdown.
 */

import type { ChildProcess } from "node:child_process";

export interface BuildResult {
  kind: "lua" | "c" | "hybrid";
  target: "simulator" | "device";
  pdxPath: string;
  durationMs: number;
  warnings: DiagnosticEntry[];
  errors: DiagnosticEntry[];
}

export interface DiagnosticEntry {
  file: string;
  line: number;
  column?: number;
  message: string;
}

export interface RuntimeState {
  simProcess: ChildProcess | null;
  simPid: number | null;
  simStartedAt: string | null;
  simLogBuffer: string[];
  simLogTotalSeen: number;
  lastBuildResult: BuildResult | null;
  lastDevicePort: string | null;
}

export function createRuntimeState(): RuntimeState {
  return {
    simProcess: null,
    simPid: null,
    simStartedAt: null,
    simLogBuffer: [],
    simLogTotalSeen: 0,
    lastBuildResult: null,
    lastDevicePort: null,
  };
}

export function pushLogLine(state: RuntimeState, line: string, maxLines: number): void {
  state.simLogBuffer.push(line);
  state.simLogTotalSeen++;
  if (state.simLogBuffer.length > maxLines) {
    state.simLogBuffer.shift();
  }
}

/**
 * Thin wrapper around pi.exec for consistent error handling.
 */

import type { ExecResult, ExtensionAPI } from "@mariozechner/pi-coding-agent";

export interface ExecOpts {
  cwd?: string;
  signal?: AbortSignal;
  timeout?: number;
}

/**
 * Run a command via pi.exec. Throws if exit code is non-zero (unless allowNonZero).
 */
export async function run(
  pi: ExtensionAPI,
  cmd: string,
  args: string[],
  opts?: ExecOpts & { allowNonZero?: boolean },
): Promise<ExecResult> {
  const result = await pi.exec(cmd, args, {
    cwd: opts?.cwd,
    signal: opts?.signal,
    timeout: opts?.timeout,
  });

  if (result.code !== 0 && !opts?.allowNonZero) {
    const output = (result.stderr || result.stdout).trim();
    throw new Error(`${cmd} exited with code ${result.code}: ${output}`);
  }

  return result;
}

/**
 * SDK discovery: find PLAYDATE_SDK_PATH, detect version, locate binaries.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ResolvedPlaydateConfig } from "../config";

export interface SdkInfo {
  path: string;
  version: string;
  ok: boolean;
  error?: string;
}

export interface PdcInfo {
  path: string;
  ok: boolean;
  error?: string;
}

export interface SimulatorInfo {
  path: string;
  ok: boolean;
  error?: string;
}

export interface ArmToolchainInfo {
  path: string;
  ok: boolean;
  error?: string;
}

export interface CmakeInfo {
  ok: boolean;
  error?: string;
}

/**
 * Resolve the SDK root path from config override, env var, or platform default.
 */
export function resolveSDKPath(config: ResolvedPlaydateConfig): string {
  if (config.sdkPath) return config.sdkPath;
  if (process.env.PLAYDATE_SDK_PATH) return process.env.PLAYDATE_SDK_PATH;

  switch (process.platform) {
    case "darwin":
      return join(process.env.HOME ?? "/Users", "Developer/PlaydateSDK");
    case "win32":
      return join(process.env.USERPROFILE ?? "C:\\Users", "Documents/PlaydateSDK");
    case "linux":
      return join(process.env.HOME ?? "/home", "PlaydateSDK");
    default:
      return "";
  }
}

/**
 * Read SDK version from VERSION.txt at the SDK root.
 */
export function readSdkVersion(sdkPath: string): SdkInfo {
  if (!sdkPath) {
    return { path: "", version: "", ok: false, error: "No SDK path configured" };
  }

  const versionFile = join(sdkPath, "VERSION.txt");
  if (!existsSync(versionFile)) {
    return { path: sdkPath, version: "", ok: false, error: `VERSION.txt not found at ${sdkPath}` };
  }

  const version = readFileSync(versionFile, "utf-8").trim();
  return { path: sdkPath, version, ok: true };
}

/**
 * Locate the pdc compiler binary.
 */
export function findPdc(sdkPath: string): PdcInfo {
  const bin = process.platform === "win32" ? "pdc.exe" : "pdc";
  const path = join(sdkPath, "bin", bin);
  if (!existsSync(path)) {
    return { path, ok: false, error: `pdc not found at ${path}` };
  }
  return { path, ok: true };
}

/**
 * Locate the simulator binary (per-platform).
 */
export function findSimulator(sdkPath: string): SimulatorInfo {
  let path: string;
  switch (process.platform) {
    case "darwin":
      path = join(sdkPath, "bin", "Playdate Simulator.app", "Contents", "MacOS", "Playdate Simulator");
      break;
    case "win32":
      path = join(sdkPath, "bin", "PlaydateSimulator.exe");
      break;
    case "linux":
      path = join(sdkPath, "bin", "PlaydateSimulator");
      break;
    default:
      return { path: "", ok: false, error: `Unsupported platform: ${process.platform}` };
  }

  if (!existsSync(path)) {
    return { path, ok: false, error: `Simulator not found at ${path}` };
  }
  return { path, ok: true };
}

/**
 * Get the simulator app path for launching (e.g. the .app bundle on macOS).
 */
export function getSimulatorLaunchPath(sdkPath: string): string {
  switch (process.platform) {
    case "darwin":
      return join(sdkPath, "bin", "Playdate Simulator.app");
    case "win32":
      return join(sdkPath, "bin", "PlaydateSimulator.exe");
    case "linux":
      return join(sdkPath, "bin", "PlaydateSimulator");
    default:
      return "";
  }
}

/**
 * Find arm-none-eabi-gcc for C builds.
 */
export function findArmToolchain(config: ResolvedPlaydateConfig, sdkPath: string): ArmToolchainInfo {
  if (config.armToolchainPath) {
    const gcc = join(config.armToolchainPath, "bin", "arm-none-eabi-gcc");
    if (existsSync(gcc)) {
      return { path: config.armToolchainPath, ok: true };
    }
    return { path: config.armToolchainPath, ok: false, error: `arm-none-eabi-gcc not found at ${gcc}` };
  }

  // Check PATH
  const pathDirs = (process.env.PATH ?? "").split(":");
  for (const dir of pathDirs) {
    if (existsSync(join(dir, "arm-none-eabi-gcc"))) {
      return { path: dir, ok: true };
    }
  }

  // macOS: SDK installer puts it in a known location
  if (process.platform === "darwin") {
    const candidates = [
      "/usr/local/playdate/gcc-arm-none-eabi-9-2019-q4-major/bin",
      "/usr/local/playdate/gcc-arm-none-eabi/bin",
    ];

    // Also check SDK-relative location
    const sdkToolchain = join(sdkPath, "C_API", "gcc-arm-none-eabi");
    if (existsSync(sdkToolchain)) {
      candidates.unshift(join(sdkToolchain, "bin"));
    }

    for (const dir of candidates) {
      if (existsSync(join(dir, "arm-none-eabi-gcc"))) {
        return { path: dir.replace(/\/bin$/, ""), ok: true };
      }
    }
  }

  return { path: "", ok: false, error: "arm-none-eabi-gcc not found in PATH or known locations" };
}

/**
 * Get the arm.cmake toolchain file path.
 */
export function getArmToolchainFile(sdkPath: string): string {
  return join(sdkPath, "C_API", "buildsupport", "arm.cmake");
}

/**
 * Project detection: find project kind, pdxinfo, source/output dirs.
 */

import { existsSync } from "node:fs";
import { basename, join } from "node:path";

export type ProjectKind = "lua" | "c" | "hybrid";

export interface ProjectInfo {
  kind: ProjectKind;
  root: string;
  sourceDir: string;
  outputDir: string;
  pdxName: string;
  hasCMakeLists: boolean;
  hasPdxInfo: boolean;
}

/**
 * Detect project kind and resolve paths. Throws if no valid project found.
 */
export function detectProject(projectPath: string): ProjectInfo {
  const hasCMakeLists = existsSync(join(projectPath, "CMakeLists.txt"));
  const hasSourceDir = existsSync(join(projectPath, "Source")) || existsSync(join(projectPath, "source"));
  const hasPdxInfoUpper = existsSync(join(projectPath, "Source", "pdxinfo"));
  const hasPdxInfoLower = existsSync(join(projectPath, "source", "pdxinfo"));
  const hasPdxInfo = hasPdxInfoUpper || hasPdxInfoLower;

  const sourceDir = existsSync(join(projectPath, "Source")) ? "Source" : "source";

  let kind: ProjectKind;
  if (hasCMakeLists && hasSourceDir) {
    kind = "hybrid";
  } else if (hasCMakeLists) {
    kind = "c";
  } else if (hasSourceDir) {
    kind = "lua";
  } else {
    throw new Error(
      `No Playdate project found at ${projectPath}. Expected CMakeLists.txt or Source/ directory.`,
    );
  }

  const dirName = basename(projectPath);
  const pdxName = `${dirName}.pdx`;
  const outputDir = join(projectPath, pdxName);

  return {
    kind,
    root: projectPath,
    sourceDir: join(projectPath, sourceDir),
    outputDir,
    pdxName,
    hasCMakeLists,
    hasPdxInfo,
  };
}

/**
 * Find a .pdx directory in the given path.
 */
export function findPdxBundle(projectPath: string): string | null {
  const { readdirSync, statSync } = require("node:fs") as typeof import("node:fs");
  try {
    const entries = readdirSync(projectPath);
    for (const entry of entries) {
      if (entry.endsWith(".pdx")) {
        const full = join(projectPath, entry);
        if (statSync(full).isDirectory()) {
          return full;
        }
      }
    }
  } catch {
    // ignore
  }
  return null;
}

/**
 * Project detection: find project kind, pdxinfo, source/output dirs.
 */

import { existsSync, readdirSync, statSync } from "node:fs";
import { basename, join } from "node:path";

export type ProjectKind = "lua" | "c" | "hybrid";

export interface ProjectInfo {
  kind: ProjectKind;
  root: string;
  sourceDir: string;
  outputDir: string;
  pdxName: string;
  hasCMakeLists: boolean;
  hasPdxInfo: boolean;
