/**
 * Simulator management: spawn, track, log, screenshot.
 */

import { spawn } from "node:child_process";
import type { RuntimeState } from "./state";
import { pushLogLine } from "./state";

/**
 * Spawn the Playdate Simulator as a detached child.
 * Pipes stdout/stderr into the ring buffer in state.
 */
export function spawnSimulator(
  simLaunchPath: string,
  pdxPath: string,
  state: RuntimeState,
  maxLogLines: number,
): { pid: number } {
  // Kill existing simulator if running
  killSimulator(state);

  let cmd: string;
  let args: string[];

  if (process.platform === "darwin") {
    // On macOS, use `open` to launch the .app bundle
    cmd = "open";
    args = ["-a", simLaunchPath, pdxPath];
  } else {
    cmd = simLaunchPath;
    args = [pdxPath];
  }

  const child = spawn(cmd, args, {
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });

  child.unref();

  state.simProcess = child;
  state.simPid = child.pid ?? null;
  state.simStartedAt = new Date().toISOString();
  state.simLogBuffer = [];
  state.simLogTotalSeen = 0;

  const onData = (data: Buffer) => {
    const lines = data.toString().split("\n");
    for (const line of lines) {
      if (line.trim()) {
        pushLogLine(state, line, maxLogLines);
      }
    }
  };

  child.stdout?.on("data", onData);
  child.stderr?.on("data", onData);

  child.on("exit", () => {
    state.simProcess = null;
    state.simPid = null;
  });

  return { pid: child.pid ?? 0 };
}

/**
 * Kill the tracked simulator process.
 */
export function killSimulator(state: RuntimeState): boolean {
  if (state.simProcess) {
    try {
      state.simProcess.kill("SIGTERM");
    } catch {
      // already dead
    }
    state.simProcess = null;
    state.simPid = null;
    state.simStartedAt = null;
    return true;
  }
  return false;
}

/**
 * Check if the simulator process is still running.
 */
export function isSimulatorRunning(state: RuntimeState): boolean {
  if (!state.simProcess || !state.simPid) return false;
  try {
    process.kill(state.simPid, 0);
    return true;
  } catch {
    state.simProcess = null;
    state.simPid = null;
    return false;
  }
}

/**
 * Device management: serial port discovery, data-disk mode, volume mount detection.
 */

import { existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";

export interface DeviceInfo {
  port: string | null;
  connected: boolean;
}

/**
 * Scan for connected Playdate device by looking for serial ports.
 */
export function findDevice(): DeviceInfo {
  switch (process.platform) {
    case "darwin":
      return findDeviceMacOS();
    case "linux":
      return findDeviceLinux();
    case "win32":
      return findDeviceWindows();
    default:
      return { port: null, connected: false };
  }
}

function findDeviceMacOS(): DeviceInfo {
  try {
    const devDir = "/dev";
    const entries = readdirSync(devDir);
    for (const entry of entries) {
      if (entry.match(/^cu\.(usbmodem|PDU1)/i)) {
        return { port: join(devDir, entry), connected: true };
      }
    }
  } catch {
    // ignore
  }
  return { port: null, connected: false };
}

function findDeviceLinux(): DeviceInfo {
  try {
    const devDir = "/dev";
    const entries = readdirSync(devDir);
    for (const entry of entries) {
      if (entry.match(/^ttyACM\d+$/)) {
        return { port: join(devDir, entry), connected: true };
      }
    }
  } catch {
    // ignore
  }
  return { port: null, connected: false };
}

function findDeviceWindows(): DeviceInfo {
  // On Windows, serial ports are COM ports. We can't easily scan without
  // additional tooling, so return not-found and let pdutil handle detection.
  return { port: null, connected: false };
}

/**
 * Get the expected mount path for the Playdate data disk volume.
 */
export function getDataDiskMountPath(): string {
  switch (process.platform) {
    case "darwin":
      return "/Volumes/PLAYDATE";
    case "linux":
      return `/media/${process.env.USER ?? "user"}/PLAYDATE`;
    case "win32":
      // On Windows, check common drive letters
      for (const letter of ["D", "E", "F", "G"]) {
        const path = `${letter}:\\`;
        if (existsSync(join(path, "Games"))) {
          return path;
        }
      }
      return "D:\\";
    default:
      return "";
  }
}

/**
 * Enter data-disk mode via pdutil.
 */
export async function enterDataDiskMode(
  pi: ExtensionAPI,
  pdutilPath: string,
  port: string,
  opts?: { signal?: AbortSignal },
): Promise<void> {
  const result = await pi.exec(pdutilPath, [port, "datadisk"], {
    signal: opts?.signal,
  });
  if (result.code !== 0) {
    throw new Error(`Failed to enter data-disk mode: ${result.stderr || result.stdout}`);
  }
}

/**
 * Wait for the PLAYDATE volume to mount (polling with timeout).
 */
export async function waitForVolume(
  mountPath: string,
  timeoutMs: number = 15000,
  signal?: AbortSignal,
): Promise<void> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (signal?.aborted) throw new Error("Cancelled");
    if (existsSync(mountPath)) return;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`Playdate volume did not mount at ${mountPath} within ${timeoutMs / 1000}s`);
}

/**
 * Run a game on the device via pdutil.
 */
export async function runOnDevice(
  pi: ExtensionAPI,
  pdutilPath: string,
  port: string,
  gamePath: string,
  opts?: { signal?: AbortSignal },
): Promise<void> {
  const result = await pi.exec(pdutilPath, [port, "run", gamePath], {
    signal: opts?.signal,
  });
  if (result.code !== 0) {
    throw new Error(`Failed to run game on device: ${result.stderr || result.stdout}`);
  }
}

/**
 * Get pdutil binary path.
 */
export function findPdutil(sdkPath: string): string {
  const bin = process.platform === "win32" ? "pdutil.exe" : "pdutil";
  return join(sdkPath, "bin", bin);
}

import { ToolCallHeader, ToolBody, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { ResolvedPlaydateConfig } from "../config";
import { findDevice } from "../lib/device";
import {
  findArmToolchain,
  findPdc,
  findSimulator,
  readSdkVersion,
  resolveSDKPath,
} from "../lib/sdk";

interface DoctorDetails {
  sdk: { path: string; version: string; ok: boolean; error?: string };
  pdc: { path: string; ok: boolean; error?: string };
  simulator: { path: string; ok: boolean; error?: string };
  armToolchain: { path: string; ok: boolean; error?: string };
  device: { port: string | null; connected: boolean };
}

const parameters = Type.Object({});

export function createDoctorTool(config: ResolvedPlaydateConfig) {
  return {
    name: "playdate_doctor",
    label: "Playdate Doctor",
    description:
      "Check Playdate SDK installation and development environment. Verifies SDK, pdc, simulator, ARM toolchain, and connected device.",
    promptSnippet: "Check Playdate development environment health",
    parameters,

    async execute(
      _toolCallId: string,
      _params: Record<string, never>,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<DoctorDetails>> {
      const sdkPath = resolveSDKPath(config);
      const sdk = readSdkVersion(sdkPath);
      const pdc = findPdc(sdkPath);
      const simulator = findSimulator(sdkPath);
      const armToolchain = findArmToolchain(config, sdkPath);
      const device = findDevice();

      const details: DoctorDetails = {
        sdk,
        pdc,
        simulator,
        armToolchain,
        device,
      };

      const issues: string[] = [];
      if (!sdk.ok) issues.push(`SDK: ${sdk.error}`);
      if (!pdc.ok) issues.push(`pdc: ${pdc.error}`);
      if (!simulator.ok) issues.push(`Simulator: ${simulator.error}`);
      if (!armToolchain.ok) issues.push(`ARM toolchain: ${armToolchain.error}`);

      const summary = issues.length > 0
        ? `Issues found: ${issues.join("; ")}`
        : `SDK ${sdk.version} OK${device.connected ? ` · device: ${device.port}` : ""}`;

      return {
        content: [{ type: "text", text: summary }],
        details,
      };
    },

    renderCall(_args: Record<string, never>, theme: Theme) {
      return new ToolCallHeader(
        { toolName: "Playdate Doctor", mainArg: "", optionArgs: [], longArgs: [] },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<DoctorDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Playdate Doctor: checking..."), 0, 0);
      }

      const { details } = result;
      if (!details?.sdk) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Check failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const ok = (v: boolean) => (v ? "ok" : "missing");
      const fields = [
        { label: "SDK", value: details.sdk.ok ? `${details.sdk.version} (${details.sdk.path})` : (details.sdk.error ?? "not found"), showCollapsed: true },
        { label: "pdc", value: ok(details.pdc.ok), showCollapsed: true },
        { label: "Simulator", value: ok(details.simulator.ok), showCollapsed: true },
        { label: "ARM Toolchain", value: ok(details.armToolchain.ok), showCollapsed: false },
        { label: "Device", value: details.device.connected ? (details.device.port ?? "connected") : "not connected", showCollapsed: true },
      ];

      return new ToolBody({ fields }, options, theme);
    },
  };
}

export function registerDoctorTool(pi: ExtensionAPI, config: ResolvedPlaydateConfig) {
  pi.registerTool(createDoctorTool(config));
}

import { ToolCallHeader, ToolBody, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  AgentToolUpdateCallback,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { truncateTail, withFileMutationQueue } from "@mariozechner/pi-coding-agent";
import { StringEnum } from "@mariozechner/pi-ai";
import { Container, Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@sinclair/typebox";
import type { ResolvedPlaydateConfig } from "../config";
import { cmakeBuild } from "../lib/cmake";
import { runPdc } from "../lib/pdc";
import { detectProject } from "../lib/project";
import { findPdc, resolveSDKPath } from "../lib/sdk";
import type { BuildResult, RuntimeState } from "../lib/state";

const parameters = Type.Object({
  projectPath: Type.Optional(Type.String({ description: "Path to the project root. Defaults to cwd." })),
  target: Type.Optional(StringEnum(["simulator", "device"], { description: "Build target" })),
  clean: Type.Optional(Type.Boolean({ description: "Clean build directory before building", default: false })),
});

type BuildParams = Static<typeof parameters>;

interface BuildDetails extends BuildResult {
  output?: string;
}

export function createBuildTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_build",
    label: "Playdate Build",
    description: "Build a Playdate project (Lua or C). Auto-detects project kind.",
    promptSnippet: "Compile Playdate project to .pdx bundle",
    promptGuidelines: [
      "Always build before running in simulator or deploying to device",
      "Check build errors in details.errors before proceeding",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: BuildParams,
      signal: AbortSignal | undefined,
      _onUpdate: AgentToolUpdateCallback<BuildDetails> | undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<BuildDetails>> {
      const projectPath = params.projectPath || ctx.cwd;
      const target = params.target || config.defaultTarget;
      const sdkPath = resolveSDKPath(config);
      const start = Date.now();

      const project = detectProject(projectPath);
      const pdc = findPdc(sdkPath);
      if (!pdc.ok) throw new Error(pdc.error ?? "pdc not found");

      let allErrors: BuildResult["errors"] = [];
      let allWarnings: BuildResult["warnings"] = [];
      let buildOutput = "";

      // C build (if applicable)
      if (project.kind === "c" || project.kind === "hybrid") {
        const cmake = await cmakeBuild(pi, projectPath, target, {
          sdkPath,
          buildMode: config.buildMode,
          clean: params.clean,
          signal,
        });
        buildOutput += cmake.output;
        allErrors.push(...cmake.errors);
        allWarnings.push(...cmake.warnings);

        if (!cmake.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          throw new Error(
            `C build failed with ${allErrors.length} error(s). ${allErrors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("; ")}`,
          );
        }
      }

      // Lua/pdc build
      if (project.kind === "lua" || project.kind === "hybrid") {
        const pdcResult = await withFileMutationQueue(project.outputDir, async () => {
          return runPdc(pi, pdc.path, project.sourceDir, project.outputDir, {
            cwd: projectPath,
            signal,
          });
        });
        buildOutput += pdcResult.output;
        allErrors.push(...pdcResult.errors);
        allWarnings.push(...pdcResult.warnings);

        if (!pdcResult.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          throw new Error(
            `Build failed with ${allErrors.length} error(s). ${allErrors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("; ")}`,
          );
        }
      }

      const durationMs = Date.now() - start;
      const details: BuildDetails = {
        kind: project.kind,
        target,
        pdxPath: project.outputDir,
        durationMs,
        warnings: allWarnings,
        errors: allErrors,
      };
      state.lastBuildResult = details;

      const summary = allWarnings.length > 0
        ? `Built ${project.pdxName} (${durationMs}ms, ${allWarnings.length} warning(s))`
        : `Built ${project.pdxName} (${durationMs}ms)`;

      return {
        content: [{ type: "text", text: summary }],
        details,
      };
    },

    renderCall(args: BuildParams, theme: Theme) {
      const optionArgs: string[] = [];
      if (args.target) optionArgs.push(`target=${args.target}`);
      if (args.clean) optionArgs.push("clean");

      return new ToolCallHeader(
        {
          toolName: "Playdate Build",
          mainArg: args.projectPath || "",
          optionArgs,
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<BuildDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Playdate Build: compiling..."), 0, 0);
      }

      const { details } = result;
      if (!details?.kind) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Build failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "Kind", value: details.kind, showCollapsed: true },
        { label: "Target", value: details.target, showCollapsed: true },
        { label: "Output", value: details.pdxPath, showCollapsed: true },
      ];

      if (details.errors.length > 0) {
        fields.push({
          label: "Errors",
          value: details.errors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("\n"),
          showCollapsed: true,
        });
      }

      const footerItems = [
        { label: "time", value: `${details.durationMs}ms` },
      ];
      if (details.warnings.length > 0) {
        footerItems.push({ label: "warnings", value: `${details.warnings.length}` });
      }
      if (details.errors.length > 0) {
        footerItems.push({ label: "errors", value: `${details.errors.length}` });
      }

      return new ToolBody(
        {
          fields,
          footer: new ToolFooter(theme, { items: footerItems, separator: " | " }),
          includeSpacerBeforeFooter: true,
        },
        options,
        theme,
      );
    },
  };
}

