  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createRunDeviceTool(pi, config, state));
}

import { ToolCallHeader, ToolBody } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { StringEnum } from "@mariozechner/pi-ai";
import { Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@sinclair/typebox";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const parameters = Type.Object({
  name: Type.String({ description: "Project name" }),
  path: Type.String({ description: "Directory to create the project in" }),
  language: StringEnum(["lua", "c"], { description: "Project language" }),
});

type NewProjectParams = Static<typeof parameters>;

interface NewProjectDetails {
  files: string[];
  language: "lua" | "c";
  projectPath: string;
}

const LUA_MAIN = `import "CoreLibs/object"
import "CoreLibs/graphics"
import "CoreLibs/sprites"
import "CoreLibs/timer"

local gfx <const> = playdate.graphics

function playdate.update()
    gfx.sprite.update()
    playdate.timer.updateTimers()
end
`;

function generatePdxInfo(name: string): string {
  const bundleId = `com.example.${name.toLowerCase().replace(/[^a-z0-9]/g, "")}`;
  return `name=${name}
author=
description=
bundleID=${bundleId}
version=0.1.0
buildNumber=1
`;
}

const C_MAIN = `#include <stdio.h>
#include <stdlib.h>
#include "pd_api.h"

static int update(void* userdata);

#ifdef _WINDLL
__declspec(dllexport)
#endif
int eventHandler(PlaydateAPI* pd, PDSystemEvent event, uint32_t arg) {
    (void)arg;

    if (event == kEventInit) {
        pd->system->setUpdateCallback(update, pd);
    }

    return 0;
}

static int update(void* userdata) {
    PlaydateAPI* pd = (PlaydateAPI*)userdata;
    pd->graphics->clear(kColorWhite);
    pd->graphics->drawText("Hello World!", strlen("Hello World!"), kASCIIEncoding, 10, 10);
    return 1;
}
`;

function generateCMakeLists(name: string): string {
  return `cmake_minimum_required(VERSION 3.14)

set(CMAKE_C_STANDARD 11)

set(ENVSDK $ENV{PLAYDATE_SDK_PATH})

if (NOT \${ENVSDK} STREQUAL "")
    # Convert path from Windows
    file(TO_CMAKE_PATH \${ENVSDK} SDK)
else()
    execute_process(
        COMMAND bash -c "egrep '^\\\\s*SDKRoot' $HOME/.Playdate/config"
        COMMAND head -n 1
        COMMAND cut -c9-
        OUTPUT_VARIABLE SDK
        OUTPUT_STRIP_TRAILING_WHITESPACE
    )
endif()

if (NOT EXISTS \${SDK})
    message(FATAL_ERROR "SDK Path not found; set ENV value PLAYDATE_SDK_PATH")
    return()
endif()

set(CMAKE_CONFIGURATION_TYPES "Debug;Release")
set(CMAKE_XCODE_GENERATE_SCHEME TRUE)

project(${name} C ASM)

if (TOOLCHAIN STREQUAL "armgcc")
    add_executable(\${PROJECT_NAME} src/main.c)
else()
    add_library(\${PROJECT_NAME} SHARED src/main.c)
endif()

include(\${SDK}/C_API/buildsupport/playdate_game.cmake)
`;
}

export function createNewProjectTool() {
  return {
    name: "playdate_new_project",
    label: "Playdate New Project",
    description: "Scaffold a new Playdate project with Lua or C.",
    promptSnippet: "Create a new Playdate game project",
    parameters,

    async execute(
      _toolCallId: string,
      params: NewProjectParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<NewProjectDetails>> {
      const projectPath = params.path;
      const files: string[] = [];

      if (params.language === "lua") {
        const sourceDir = join(projectPath, "Source");
        mkdirSync(sourceDir, { recursive: true });

        writeFileSync(join(sourceDir, "main.lua"), LUA_MAIN);
        files.push("Source/main.lua");

        writeFileSync(join(sourceDir, "pdxinfo"), generatePdxInfo(params.name));
        files.push("Source/pdxinfo");
      } else {
        const srcDir = join(projectPath, "src");
        mkdirSync(srcDir, { recursive: true });

        writeFileSync(join(srcDir, "main.c"), C_MAIN);
        files.push("src/main.c");

        writeFileSync(join(projectPath, "CMakeLists.txt"), generateCMakeLists(params.name));
        files.push("CMakeLists.txt");

        // C projects still need pdxinfo in Source/
        const sourceDir = join(projectPath, "Source");
        mkdirSync(sourceDir, { recursive: true });
        writeFileSync(join(sourceDir, "pdxinfo"), generatePdxInfo(params.name));
        files.push("Source/pdxinfo");
      }

      return {
        content: [
          {
            type: "text",
            text: `Created ${params.language} project "${params.name}" with files: ${files.join(", ")}`,
          },
        ],
        details: {
          files,
          language: params.language,
          projectPath,
        },
      };
    },

    renderCall(args: NewProjectParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate New Project",
          mainArg: `"${args.name}"`,
          optionArgs: [`lang=${args.language}`],
          longArgs: args.path ? [{ label: "path", value: args.path }] : [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<NewProjectDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Playdate New Project: scaffolding..."), 0, 0);
      }

      const { details } = result;
      if (!details?.files) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "Language", value: details.language, showCollapsed: true },
        { label: "Path", value: details.projectPath, showCollapsed: true },
        { label: "Files", value: details.files.join(", "), showCollapsed: false },
      ];

      return new ToolBody({ fields }, options, theme);
    },
  };
}

export function registerNewProjectTool(pi: ExtensionAPI) {
  pi.registerTool(createNewProjectTool());
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { ResolvedPlaydateConfig } from "../config";
import type { RuntimeState } from "../lib/state";
import { registerBuildTool } from "./build";
import { registerDoctorTool } from "./doctor";
import { registerNewProjectTool } from "./new_project";
import { registerRunDeviceTool } from "./run_device";
import { registerRunSimTool } from "./run_sim";
import { registerScreenshotTool } from "./screenshot";
import { registerSimLogTool } from "./sim_log";
import { registerStopSimTool } from "./stop_sim";

export function registerTools(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  registerDoctorTool(pi, config);
  registerBuildTool(pi, config, state);
  registerRunSimTool(pi, config, state);
  registerStopSimTool(pi, state);
  registerSimLogTool(pi, state);
  registerScreenshotTool(pi, state);
  registerRunDeviceTool(pi, config, state);
  registerNewProjectTool(pi);
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { ResolvedPlaydateConfig } from "../config";
import { findDevice } from "../lib/device";
import {
  findArmToolchain,
  findPdc,
  findSimulator,
  readSdkVersion,
  resolveSDKPath,
} from "../lib/sdk";

export function registerDoctorCommand(pi: ExtensionAPI, config: ResolvedPlaydateConfig) {
  pi.registerCommand("playdate:doctor", {
    description: "Check Playdate SDK installation and environment",
    handler: async (_args, ctx) => {
      const sdkPath = resolveSDKPath(config);
      const sdk = readSdkVersion(sdkPath);
      const pdc = findPdc(sdkPath);
      const simulator = findSimulator(sdkPath);
      const armToolchain = findArmToolchain(config, sdkPath);
      const device = findDevice();

      const ok = (v: boolean) => (v ? "[ok]" : "[missing]");

      const lines = [
        `SDK: ${ok(sdk.ok)} ${sdk.ok ? `${sdk.version} at ${sdk.path}` : (sdk.error ?? "not found")}`,
        `pdc: ${ok(pdc.ok)}${!pdc.ok ? ` ${pdc.error}` : ""}`,
        `Simulator: ${ok(simulator.ok)}${!simulator.ok ? ` ${simulator.error}` : ""}`,
        `ARM Toolchain: ${ok(armToolchain.ok)}${!armToolchain.ok ? ` ${armToolchain.error}` : ""}`,
        `Device: ${device.connected ? `connected at ${device.port}` : "not connected"}`,
      ];

      ctx.ui.notify(lines.join("\n"), "info");
    },
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { ResolvedPlaydateConfig } from "../config";
import { detectProject, findPdxBundle } from "../lib/project";
import { findPdc, getSimulatorLaunchPath, resolveSDKPath } from "../lib/sdk";
import { spawnSimulator } from "../lib/sim";
import { runPdc } from "../lib/pdc";
import type { RuntimeState } from "../lib/state";

export function registerSimCommand(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerCommand("playdate:sim", {
    description: "Build and run the current project in the Playdate Simulator",
    handler: async (_args, ctx) => {
      const sdkPath = resolveSDKPath(config);
      const cwd = ctx.cwd;

      // Build first
      try {
        const project = detectProject(cwd);
        const pdc = findPdc(sdkPath);
        if (!pdc.ok) {
          ctx.ui.notify(`pdc not found: ${pdc.error}`, "error");
          return;
        }

        ctx.ui.notify("Building...", "info");
        const result = await runPdc(pi, pdc.path, project.sourceDir, project.outputDir, { cwd });
        if (!result.success) {
          ctx.ui.notify(`Build failed: ${result.errors.length} error(s)`, "error");
          return;
        }

        // Run simulator
        const simPath = getSimulatorLaunchPath(sdkPath);
        if (!simPath) {
          ctx.ui.notify("Simulator not found", "error");
          return;
        }

        spawnSimulator(simPath, project.outputDir, state, config.simulatorLogLines);
        ctx.ui.setStatus("playdate", "sim running");
        ctx.ui.notify("Simulator started", "info");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        ctx.ui.notify(msg, "error");
      }
    },
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { cpSync } from "node:fs";
import { basename, join } from "node:path";
import type { ResolvedPlaydateConfig } from "../config";
import {
  enterDataDiskMode,
  findDevice,
  findPdutil,
  getDataDiskMountPath,
  runOnDevice,
  waitForVolume,
} from "../lib/device";
import { runPdc } from "../lib/pdc";
import { detectProject } from "../lib/project";
import { findPdc, resolveSDKPath } from "../lib/sdk";
import type { RuntimeState } from "../lib/state";

export function registerDeviceCommand(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerCommand("playdate:device", {
    description: "Build and deploy the current project to a connected Playdate",
    handler: async (_args, ctx) => {
      const sdkPath = resolveSDKPath(config);
      const cwd = ctx.cwd;

      try {
        // Build
        const project = detectProject(cwd);
        const pdc = findPdc(sdkPath);
        if (!pdc.ok) {
          ctx.ui.notify(`pdc not found: ${pdc.error}`, "error");
          return;
        }

        ctx.ui.notify("Building...", "info");
        const result = await runPdc(pi, pdc.path, project.sourceDir, project.outputDir, { cwd });
        if (!result.success) {
          ctx.ui.notify(`Build failed: ${result.errors.length} error(s)`, "error");
          return;
        }

        // Find device
        const device = findDevice();
        if (!device.connected || !device.port) {
          ctx.ui.notify("No Playdate device connected", "error");
          return;
        }

        const port = device.port;
        const pdxName = basename(project.outputDir);
        state.lastDevicePort = port;

        // Confirm
        const confirmed = await ctx.ui.confirm(
          "Install on Playdate?",
          `Upload ${pdxName} to device at ${port}?`,
        );
        if (!confirmed) {
          ctx.ui.notify("Deployment cancelled", "info");
          return;
        }

        // Deploy
        const pdutilPath = findPdutil(sdkPath);
        await enterDataDiskMode(pi, pdutilPath, port);

        const volumePath = getDataDiskMountPath();
        await waitForVolume(volumePath);

        const destPath = join(volumePath, "Games", pdxName);
        cpSync(project.outputDir, destPath, { recursive: true });

        await pi.exec("sync", [], {});

        if (process.platform === "darwin") {
          await pi.exec("diskutil", ["eject", volumePath], {});
        } else if (process.platform === "linux") {
          await pi.exec("umount", [volumePath], {});
        }

        await new Promise((resolve) => setTimeout(resolve, 2000));
        await runOnDevice(pi, pdutilPath, port, `/Games/${pdxName}`);

        ctx.ui.notify(`${pdxName} deployed and launched`, "info");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        ctx.ui.notify(msg, "error");
      }
    },
  });
}

import {
  registerSettingsCommand,
  type SettingsSection,
} from "@aliou/pi-utils-settings";
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { PlaydateConfig, ResolvedPlaydateConfig } from "../config";
import { configLoader } from "../config";

export function registerPlaydateSettings(
  pi: ExtensionAPI,
  onSave?: () => void,
): void {
  registerSettingsCommand<PlaydateConfig, ResolvedPlaydateConfig>(pi, {
    commandName: "playdate:settings",
    title: "Playdate Settings",
    configStore: configLoader,
    buildSections: (
      tabConfig: PlaydateConfig | null,
      resolved: ResolvedPlaydateConfig,
    ): SettingsSection[] => [
      {
        label: "SDK",
        items: [
          {
            id: "sdkPath",
            label: "SDK Path",
            description:
              "Override PLAYDATE_SDK_PATH env var. Leave empty to use env/default.",
            currentValue:
              (tabConfig?.sdkPath ?? resolved.sdkPath) || "(auto-detect)",
            values: undefined,
          },
          {
            id: "armToolchainPath",
            label: "ARM Toolchain Path",
            description:
              "Path to arm-none-eabi toolchain for C builds (auto-detected on macOS).",
            currentValue:
              (tabConfig?.armToolchainPath ?? resolved.armToolchainPath) ||
              "(auto-detect)",
            values: undefined,
          },
        ],
      },
      {
        label: "Build",
        items: [
          {
            id: "defaultTarget",
            label: "Default Target",
            description: "Default build/run target",
            currentValue:
              tabConfig?.defaultTarget ?? resolved.defaultTarget,
            values: ["simulator", "device"],
          },
          {
            id: "buildMode",
            label: "Build Mode",
            description: "Build mode for C projects",
            currentValue: tabConfig?.buildMode ?? resolved.buildMode,
            values: ["debug", "release"],
          },
        ],
      },
      {
        label: "Simulator",
        items: [
          {
            id: "autoOpenSimulator",
            label: "Auto-open Simulator",
            description: "Automatically open the simulator after building",
            currentValue:
              (tabConfig?.autoOpenSimulator ?? resolved.autoOpenSimulator)
                ? "on"
                : "off",
            values: ["on", "off"],
          },
          {
            id: "simulatorLogLines",
            label: "Log Buffer Size",
            description: "Number of simulator log lines to keep in memory",
            currentValue: String(
              tabConfig?.simulatorLogLines ?? resolved.simulatorLogLines,
            ),
            values: undefined,
          },
        ],
      },
    ],
    onSettingChange: (id, newValue, config) => {
      const updated = structuredClone(config);
      switch (id) {
        case "autoOpenSimulator":
          updated.autoOpenSimulator = newValue === "on";
          break;
        case "simulatorLogLines":
          updated.simulatorLogLines = Number.parseInt(newValue, 10) || 200;
          break;
        default:
          (updated as Record<string, unknown>)[id] = newValue;
          break;
      }
      return updated;
    },
    onSave: () => {
      onSave?.();
    },
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { ResolvedPlaydateConfig } from "../config";
import type { RuntimeState } from "../lib/state";
import { registerDeviceCommand } from "./device";
import { registerDoctorCommand } from "./doctor";
import { registerPlaydateSettings } from "./settings";
import { registerSimCommand } from "./sim";

export function registerCommands(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  registerDoctorCommand(pi, config);
  registerSimCommand(pi, config, state);
  registerDeviceCommand(pi, config, state);
  registerPlaydateSettings(pi);
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { configLoader } from "./config";
import { registerCommands } from "./commands/index";
import { createRuntimeState } from "./lib/state";
import { killSimulator } from "./lib/sim";
import { registerTools } from "./tools/index";

export default async function (pi: ExtensionAPI) {
  await configLoader.load();
  const config = configLoader.getConfig();
  const state = createRuntimeState();

  registerTools(pi, config, state);
  registerCommands(pi, config, state);

  // Clean shutdown: kill simulator, clear status
  pi.on("session_shutdown", async (_event, ctx) => {
    killSimulator(state);
    ctx.ui.setStatus("playdate", "");
  });
}

