import { ToolCallHeader, ToolBody, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  AgentToolUpdateCallback,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@sinclair/typebox";
import { cpSync } from "node:fs";
import { basename, join } from "node:path";
import type { ResolvedPlaydateConfig } from "../config";
import {
  enterDataDiskMode,
  findDevice,
  findPdutil,
  getDataDiskMountPath,
  runOnDevice,
  waitForVolume,
} from "../lib/device";
import { findPdxBundle } from "../lib/project";
import { resolveSDKPath } from "../lib/sdk";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({
  pdxPath: Type.Optional(
    Type.String({ description: "Path to .pdx bundle. Defaults to last build or auto-detect." }),
  ),
});

type RunDeviceParams = Static<typeof parameters>;

interface RunDeviceDetails {
  port: string;
  volumePath: string;
  pdxName: string;
  durationMs: number;
  launched: boolean;
}

export function createRunDeviceTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_run_device",
    label: "Playdate Run Device",
    description:
      "Deploy and run a .pdx bundle on a connected Playdate device. Requires user confirmation every time.",
    promptSnippet: "Deploy game to connected Playdate device",
    promptGuidelines: [
      "Always asks for user confirmation before deploying",
      "Device must be connected via USB",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: RunDeviceParams,
      signal: AbortSignal | undefined,
      _onUpdate: AgentToolUpdateCallback<Partial<RunDeviceDetails>> | undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<RunDeviceDetails>> {
      const start = Date.now();
      const sdkPath = resolveSDKPath(config);
      const pdutilPath = findPdutil(sdkPath);

      let pdxPath = params.pdxPath;
      if (!pdxPath && state.lastBuildResult) {
        pdxPath = state.lastBuildResult.pdxPath;
      }
      if (!pdxPath) {
        pdxPath = findPdxBundle(ctx.cwd) ?? undefined;
      }
      if (!pdxPath) {
        throw new Error("No .pdx bundle found. Build the project first with playdate_build.");
      }

      const pdxName = basename(pdxPath);

      // Find device
      const device = findDevice();
      if (!device.connected || !device.port) {
        throw new Error("No Playdate device connected. Connect via USB and try again.");
      }

      const port = device.port;
      state.lastDevicePort = port;

      // User confirmation required every time
      const confirmed = await ctx.ui.confirm(
        "Install on Playdate?",
        `Upload ${pdxName} to device at ${port}?`,
      );
      if (!confirmed) {
        return {
          content: [{ type: "text", text: "Deployment cancelled by user" }],
          details: {
            port,
            volumePath: "",
            pdxName,
            durationMs: Date.now() - start,
            launched: false,
          },
        };
      }

      // Enter data-disk mode
      ctx.ui.setWidget("playdate", ["Entering data-disk mode..."]);
      await enterDataDiskMode(pi, pdutilPath, port, { signal });

      // Wait for volume mount
      ctx.ui.setWidget("playdate", ["Waiting for volume..."]);
      const volumePath = getDataDiskMountPath();
      await waitForVolume(volumePath, 15000, signal);

      // Copy .pdx bundle
      ctx.ui.setWidget("playdate", [`Copying ${pdxName}...`]);
      const destPath = join(volumePath, "Games", pdxName);
      cpSync(pdxPath, destPath, { recursive: true });

      // Sync
      await pi.exec("sync", [], { signal });

      // Eject/unmount
      if (process.platform === "darwin") {
        await pi.exec("diskutil", ["eject", volumePath], { signal });
      } else if (process.platform === "linux") {
        await pi.exec("umount", [volumePath], { signal });
      }

      // Wait a moment for device to reboot
      await new Promise((resolve) => setTimeout(resolve, 2000));

      // Launch game
      ctx.ui.setWidget("playdate", ["Launching..."]);
      await runOnDevice(pi, pdutilPath, port, `/Games/${pdxName}`, { signal });

      ctx.ui.setWidget("playdate", undefined);
      ctx.ui.notify(`${pdxName} deployed and launched`, "info");

      const durationMs = Date.now() - start;

      return {
        content: [{ type: "text", text: `Deployed ${pdxName} to device (${durationMs}ms)` }],
        details: {
          port,
          volumePath,
          pdxName,
          durationMs,
          launched: true,
        },
      };
    },

    renderCall(args: RunDeviceParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Run Device",
          mainArg: args.pdxPath || "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<RunDeviceDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Playdate Run Device: deploying..."), 0, 0);
      }

      const { details } = result;
      if (!details?.pdxName) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Deployment failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      if (!details.launched) {
        return new Text(theme.fg("muted", "Deployment cancelled"), 0, 0);
      }

      const fields = [
        { label: "Game", value: details.pdxName, showCollapsed: true },
        { label: "Port", value: details.port, showCollapsed: true },
      ];

      const footerItems = [
        { label: "time", value: `${details.durationMs}ms` },
      ];

      return new ToolBody(
        {
          fields,
          footer: new ToolFooter(theme, { items: footerItems, separator: " | " }),
          includeSpacerBeforeFooter: true,
        },
        options,
        theme,
      );
    },
  };
}

export function registerRunDeviceTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createRunDeviceTool(pi, config, state));
}

import { ToolCallHeader, ToolBody } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { StringEnum } from "@mariozechner/pi-ai";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const parameters = Type.Object({
  name: Type.String({ description: "Project name" }),
  path: Type.String({ description: "Directory to create the project in" }),
  language: StringEnum(["lua", "c"] as const, { description: "Project language" }),
});

interface NewProjectParams {
  name: string;
  path: string;
  language: "lua" | "c";
}

interface NewProjectDetails {
  files: string[];
  language: "lua" | "c";
  projectPath: string;
}

const LUA_MAIN = `import "CoreLibs/object"
import "CoreLibs/graphics"
import "CoreLibs/sprites"
import "CoreLibs/timer"

local gfx <const> = playdate.graphics

function playdate.update()
    gfx.sprite.update()
    playdate.timer.updateTimers()
end
`;

function generatePdxInfo(name: string): string {
  const bundleId = `com.example.${name.toLowerCase().replace(/[^a-z0-9]/g, "")}`;
  return `name=${name}
author=
description=
bundleID=${bundleId}
version=0.1.0
buildNumber=1
`;
}

const C_MAIN = `#include <stdio.h>
#include <stdlib.h>
#include "pd_api.h"

static int update(void* userdata);

#ifdef _WINDLL
__declspec(dllexport)
#endif
int eventHandler(PlaydateAPI* pd, PDSystemEvent event, uint32_t arg) {
    (void)arg;

    if (event == kEventInit) {
        pd->system->setUpdateCallback(update, pd);
    }

    return 0;
}

static int update(void* userdata) {
    PlaydateAPI* pd = (PlaydateAPI*)userdata;
    pd->graphics->clear(kColorWhite);
    pd->graphics->drawText("Hello World!", strlen("Hello World!"), kASCIIEncoding, 10, 10);
    return 1;
}
`;

function generateCMakeLists(name: string): string {
  return `cmake_minimum_required(VERSION 3.14)

set(CMAKE_C_STANDARD 11)

set(ENVSDK $ENV{PLAYDATE_SDK_PATH})

if (NOT \${ENVSDK} STREQUAL "")
    # Convert path from Windows
    file(TO_CMAKE_PATH \${ENVSDK} SDK)
else()
    execute_process(
        COMMAND bash -c "egrep '^\\\\s*SDKRoot' $HOME/.Playdate/config"
        COMMAND head -n 1
        COMMAND cut -c9-
        OUTPUT_VARIABLE SDK
        OUTPUT_STRIP_TRAILING_WHITESPACE
    )
endif()

if (NOT EXISTS \${SDK})
    message(FATAL_ERROR "SDK Path not found; set ENV value PLAYDATE_SDK_PATH")
    return()
endif()

set(CMAKE_CONFIGURATION_TYPES "Debug;Release")
set(CMAKE_XCODE_GENERATE_SCHEME TRUE)

project(${name} C ASM)

if (TOOLCHAIN STREQUAL "armgcc")
    add_executable(\${PROJECT_NAME} src/main.c)
else()
    add_library(\${PROJECT_NAME} SHARED src/main.c)
endif()

include(\${SDK}/C_API/buildsupport/playdate_game.cmake)
`;
}

export function createNewProjectTool() {
  return {
    name: "playdate_new_project",
    label: "Playdate New Project",
    description: "Scaffold a new Playdate project with Lua or C.",
    promptSnippet: "Create a new Playdate game project",
    parameters,

    async execute(
      _toolCallId: string,
      params: NewProjectParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<NewProjectDetails>> {
      const projectPath = params.path;
      const files: string[] = [];

      if (params.language === "lua") {
        const sourceDir = join(projectPath, "Source");
        mkdirSync(sourceDir, { recursive: true });

        writeFileSync(join(sourceDir, "main.lua"), LUA_MAIN);
        files.push("Source/main.lua");

        writeFileSync(join(sourceDir, "pdxinfo"), generatePdxInfo(params.name));
        files.push("Source/pdxinfo");
      } else {
        const srcDir = join(projectPath, "src");
        mkdirSync(srcDir, { recursive: true });

        writeFileSync(join(srcDir, "main.c"), C_MAIN);
        files.push("src/main.c");

        writeFileSync(join(projectPath, "CMakeLists.txt"), generateCMakeLists(params.name));
        files.push("CMakeLists.txt");

        // C projects still need pdxinfo in Source/
        const sourceDir = join(projectPath, "Source");
        mkdirSync(sourceDir, { recursive: true });
        writeFileSync(join(sourceDir, "pdxinfo"), generatePdxInfo(params.name));
        files.push("Source/pdxinfo");
      }

      return {
        content: [
          {
            type: "text",
            text: `Created ${params.language} project "${params.name}" with files: ${files.join(", ")}`,
          },
        ],
        details: {
          files,
          language: params.language,
          projectPath,
        },
      };
    },

    renderCall(args: NewProjectParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate New Project",
          mainArg: `"${args.name}"`,
          optionArgs: [{ label: "lang", value: args.language }],
          longArgs: args.path ? [{ label: "path", value: args.path }] : [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<NewProjectDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Playdate New Project: scaffolding..."), 0, 0);
      }

      const { details } = result;
      if (!details?.files) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg = (textBlock?.type === "text" && textBlock.text) || "Failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "Language", value: details.language, showCollapsed: true },
        { label: "Path", value: details.projectPath, showCollapsed: true },
        { label: "Files", value: details.files.join(", "), showCollapsed: false },
      ];

      return new ToolBody({ fields }, options, theme);
    },
  };
}

export function registerNewProjectTool(pi: ExtensionAPI) {
  pi.registerTool(createNewProjectTool());
}

