name: Publish

on:
  workflow_run:
    workflows: ["CI"]
    types: [completed]
    branches: [main]

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

jobs:
  publish:
    name: Publish
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    permissions:
      contents: write
      packages: write
      pull-requests: write
      id-token: write

    steps:
      - name: Checkout
        uses: actions/checkout@v6
        with:
          fetch-depth: 0

      - name: Setup pnpm
        uses: pnpm/action-setup@v5

      - name: Setup Node.js
        uses: actions/setup-node@v6
        with:
          node-version: "24"
          registry-url: "https://registry.npmjs.org"
          scope: "@aliou"
          cache: "pnpm"

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      - name: Get release info
        id: release-info
        run: |
          pnpm changeset status --output=release.json 2>/dev/null || echo '{"releases":[]}' > release.json
          node <<NODE
          const fs = require('fs');
          const release = JSON.parse(fs.readFileSync('release.json', 'utf8'));
          const releases = release.releases?.filter(r => r.type !== 'none') || [];

          const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
          const packageName = pkg.name || 'unknown-package';
          const fallbackVersion = pkg.version || '0.0.0';

          let title = 'Updating ' + packageName + ' to version ' + fallbackVersion;
          let commit = packageName + '@' + fallbackVersion;
          if (releases.length === 1) {
            const { name, newVersion } = releases[0];
            title = 'Updating ' + name + ' to version ' + newVersion;
            commit = name + '@' + newVersion;
          } else if (releases.length > 1) {
            const summary = releases.map(r => r.name + '@' + r.newVersion).join(', ');
            title = 'Updating ' + summary;
            commit = summary;
          }

          fs.appendFileSync(process.env.GITHUB_OUTPUT, 'title=' + title + '\n');
          fs.appendFileSync(process.env.GITHUB_OUTPUT, 'commit=' + commit + '\n');
          NODE
          rm -f release.json
        continue-on-error: true

      - name: Create Release PR or Publish
        id: changesets
        uses: changesets/action@v1
        with:
          version: pnpm changeset version
          publish: pnpm changeset publish
          title: ${{ steps.release-info.outputs.title }}
          commit: ${{ steps.release-info.outputs.commit }}
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          NPM_CONFIG_PROVENANCE: true

      - name: Create GitHub releases
        if: steps.changesets.outputs.published == 'true'
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          PUBLISHED_PACKAGES: ${{ steps.changesets.outputs.publishedPackages }}
        run: |
          node <<'NODE'
          const { execSync } = require("node:child_process");

          const published = JSON.parse(process.env.PUBLISHED_PACKAGES || "[]");

          for (const pkg of published) {
            const tag = `v${pkg.version}`;

            const existing = execSync(`git tag --list ${tag}`, { encoding: "utf8" }).trim();
            if (!existing) {
              execSync(`git tag ${tag}`);
              execSync(`git push origin ${tag}`);
            }

            let hasRelease = false;
            try {
              const output = execSync(`gh release view ${tag} --json tagName --jq .tagName`, {
                stdio: ["ignore", "pipe", "ignore"],
              }).toString().trim();
              hasRelease = output.length > 0;
            } catch {
              hasRelease = false;
            }

            if (!hasRelease) {
              execSync(`gh release create ${tag} --title ${tag} --notes "Release ${tag}"`, {
                stdio: "inherit",
              });
            }
          }
          NODE

import { ToolBody, ToolCallHeader, ToolFooter } from "@aliou/pi-utils-ui";
import { StringEnum } from "@mariozechner/pi-ai";
import type {
  AgentToolResult,
  AgentToolUpdateCallback,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import {
  truncateTail,
  withFileMutationQueue,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { ResolvedPlaydateConfig } from "../config";
import { cmakeBuild } from "../lib/cmake";
import { runPdc } from "../lib/pdc";
import { detectProject } from "../lib/project";
import { findPdc, resolveSDKPath } from "../lib/sdk";
import type { BuildResult, RuntimeState } from "../lib/state";

const parameters = Type.Object({
  projectPath: Type.Optional(
    Type.String({ description: "Path to the project root. Defaults to cwd." }),
  ),
  target: Type.Optional(
    StringEnum(["simulator", "device"], { description: "Build target" }),
  ),
  clean: Type.Optional(
    Type.Boolean({
      description: "Clean build directory before building",
      default: false,
    }),
  ),
});

interface BuildParams {
  projectPath?: string;
  target?: string;
  clean?: boolean;
}

interface BuildDetails extends BuildResult {
  output?: string;
}

export function createBuildTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_build",
    label: "Playdate Build",
    description:
      "Build a Playdate project (Lua or C). Auto-detects project kind.",
    promptSnippet: "Compile Playdate project to .pdx bundle",
    promptGuidelines: [
      "Use playdate_build before running in simulator or deploying to device.",
      "After playdate_build, check details.errors before proceeding.",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: BuildParams,
      signal: AbortSignal | undefined,
      _onUpdate: AgentToolUpdateCallback<BuildDetails> | undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<BuildDetails>> {
      const projectPath = params.projectPath || ctx.cwd;
      const rawTarget = params.target || config.defaultTarget;
      const target: "simulator" | "device" =
        rawTarget === "device" ? "device" : "simulator";
      const sdkPath = resolveSDKPath(config);
      const start = Date.now();

      const project = detectProject(projectPath);
      const pdc = findPdc(sdkPath);
      if (!pdc.ok) throw new Error(pdc.error ?? "pdc not found");

      const allErrors: BuildResult["errors"] = [];
      const allWarnings: BuildResult["warnings"] = [];
      let buildOutput = "";

      // C build (if applicable)
      if (project.kind === "c" || project.kind === "hybrid") {
        const cmake = await cmakeBuild(pi, projectPath, target, {
          sdkPath,
          buildMode: config.buildMode,
          clean: params.clean,
          signal,
        });
        buildOutput += cmake.output;
        allErrors.push(...cmake.errors);
        allWarnings.push(...cmake.warnings);

        if (!cmake.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          throw new Error(
            `C build failed with ${allErrors.length} error(s). ${allErrors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("; ")}`,
          );
        }
      }

      // Lua/pdc build
      if (project.kind === "lua" || project.kind === "hybrid") {
        const pdcResult = await withFileMutationQueue(
          project.outputDir,
          async () => {
            return runPdc(pi, pdc.path, project.sourceDir, project.outputDir, {
              cwd: projectPath,
              signal,
            });
          },
        );
        buildOutput += pdcResult.output;
        allErrors.push(...pdcResult.errors);
        allWarnings.push(...pdcResult.warnings);

        if (!pdcResult.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          throw new Error(
            `Build failed with ${allErrors.length} error(s). ${allErrors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("; ")}`,
          );
        }
      }

      const durationMs = Date.now() - start;
      const details: BuildDetails = {
        kind: project.kind,
        target,
        pdxPath: project.outputDir,
        durationMs,
        warnings: allWarnings,
        errors: allErrors,
      };
      state.lastBuildResult = details;

      const summary =
        allWarnings.length > 0
          ? `Built ${project.pdxName} (${durationMs}ms, ${allWarnings.length} warning(s))`
          : `Built ${project.pdxName} (${durationMs}ms)`;

      return {
        content: [{ type: "text", text: summary }],
        details,
      };
    },

    renderCall(args: BuildParams, theme: Theme) {
      const optionArgs: Array<{ label: string; value: string }> = [];
      if (args.target) optionArgs.push({ label: "target", value: args.target });
      if (args.clean) optionArgs.push({ label: "clean", value: "true" });

      return new ToolCallHeader(
        {
          toolName: "Playdate Build",
          mainArg: args.projectPath || "",
          optionArgs,
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<BuildDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Build: compiling..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.kind) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Build failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "Kind", value: details.kind, showCollapsed: true },
        { label: "Target", value: details.target, showCollapsed: true },
        { label: "Output", value: details.pdxPath, showCollapsed: true },
      ];

      if (details.errors.length > 0) {
        fields.push({
          label: "Errors",
          value: details.errors
            .map((e) => `${e.file}:${e.line}: ${e.message}`)
            .join("\n"),
          showCollapsed: true,
        });
      }

      const footerItems = [{ label: "time", value: `${details.durationMs}ms` }];
      if (details.warnings.length > 0) {
        footerItems.push({
          label: "warnings",
          value: `${details.warnings.length}`,
        });
      }
      if (details.errors.length > 0) {
        footerItems.push({
          label: "errors",
          value: `${details.errors.length}`,
        });
      }

      return new ToolBody(
        {
          fields,
          footer: new ToolFooter(theme, {
            items: footerItems,
            separator: " | ",
          }),
          includeSpacerBeforeFooter: true,
        },
        options,
        theme,
      );
    },
  };
}

export function registerBuildTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createBuildTool(pi, config, state));
}

import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ToolCallHeader } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import { isSimulatorRunning } from "../lib/sim";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({});

interface ScreenshotDetails {
  path: string;
  width: number;
  height: number;
}

export function createScreenshotTool(pi: ExtensionAPI, state: RuntimeState) {
  return {
    name: "playdate_screenshot",
    label: "Playdate Screenshot",
    description: "Take a screenshot of the running Playdate Simulator.",
    promptSnippet: "Capture screenshot from Playdate Simulator",
    parameters,

    async execute(
      _toolCallId: string,
      _params: Record<string, never>,
      signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<ScreenshotDetails>> {
      if (!isSimulatorRunning(state)) {
        throw new Error(
          "Simulator is not running. Start it first with playdate_run_sim.",
        );
      }

      if (process.platform === "darwin") {
        return screenshotMacOS(pi, signal);
      }
      if (process.platform === "linux") {
        return screenshotLinux(pi, signal);
      }
      throw new Error(`Screenshot not yet supported on ${process.platform}`);
    },

    renderCall(_args: Record<string, never>, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Screenshot",
          mainArg: "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<ScreenshotDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Screenshot: capturing..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.path) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Screenshot failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      return new Text(`Screenshot saved to ${details.path}`, 0, 0);
    },
  };
}

async function screenshotMacOS(
  pi: ExtensionAPI,
  signal?: AbortSignal,
): Promise<AgentToolResult<ScreenshotDetails>> {
  // Get the window ID of the simulator
  const listResult = await pi.exec(
    "osascript",
    [
      "-e",
      'tell application "System Events" to get the id of every window of process "Playdate Simulator"',
    ],
    { signal },
  );

  if (listResult.code !== 0 || !listResult.stdout.trim()) {
    throw new Error("Could not find Playdate Simulator window. Is it running?");
  }

  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);

  const captureResult = await pi.exec(
    "screencapture",
    ["-l", listResult.stdout.trim().split(",")[0].trim(), "-o", outputPath],
    { signal },
  );

  if (captureResult.code !== 0) {
    throw new Error(`Screenshot failed: ${captureResult.stderr}`);
  }

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: `Screenshot saved to ${outputPath}` },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}

async function screenshotLinux(
  pi: ExtensionAPI,
  signal?: AbortSignal,
): Promise<AgentToolResult<ScreenshotDetails>> {
  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);

  const result = await pi.exec(
    "import",
    ["-window", "Playdate Simulator", outputPath],
    { signal },
  );

  if (result.code !== 0) {
    throw new Error(
      `Screenshot failed: ${result.stderr}. Is ImageMagick installed?`,
    );
  }

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: `Screenshot saved to ${outputPath}` },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}

