import { findPdxBundle } from "../lib/project";
import { getSimulatorLaunchPath, resolveSDKPath } from "../lib/sdk";
import { spawnSimulator } from "../lib/sim";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({
  pdxPath: Type.Optional(
    Type.String({
      description:
        "Path to .pdx bundle. Defaults to last build or auto-detect.",
    }),
  ),
});

type RunSimParams = Static<typeof parameters>;

interface RunSimDetails {
  pid: number;
  pdxPath: string;
  startedAt: string;
}

export function createRunSimTool(
  _pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_run_sim",
    label: "Playdate Run Sim",
    description: "Launch the Playdate Simulator with a .pdx bundle.",
    promptSnippet: "Start the Playdate Simulator",
    parameters,

    async execute(
      _toolCallId: string,
      params: RunSimParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<RunSimDetails>> {
      const sdkPath = resolveSDKPath(config);
      const simPath = getSimulatorLaunchPath(sdkPath);
      if (!simPath) {
        throw new Error(
          "Simulator not found. Run playdate_doctor to check your setup.",
        );
      }

      let pdxPath = params.pdxPath;
      if (!pdxPath && state.lastBuildResult) {
        pdxPath = state.lastBuildResult.pdxPath;
      }
      if (!pdxPath) {
        pdxPath = findPdxBundle(ctx.cwd) ?? undefined;
      }
      if (!pdxPath) {
        throw new Error(
          "No .pdx bundle found. Build the project first with playdate_build.",
        );
      }

      const { pid } = spawnSimulator(
        simPath,
        pdxPath,
        state,
        config.simulatorLogLines,
      );

      ctx.ui.setStatus("playdate", "sim running");
      ctx.ui.notify("Simulator started", "info");

      return {
        content: [{ type: "text", text: `Simulator started (PID ${pid})` }],
        details: {
          pid,
          pdxPath,
          startedAt: state.simStartedAt ?? new Date().toISOString(),
        },
      };
    },

    renderCall(args: RunSimParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Run Sim",
          mainArg: args.pdxPath || "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<RunSimDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Run Sim: starting..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.pid) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Failed to start";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "PID", value: `${details.pid}`, showCollapsed: true },
        { label: "Bundle", value: details.pdxPath, showCollapsed: true },
      ];

      return new ToolBody({ fields }, options, theme);
    },
  };
}

export function registerRunSimTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createRunSimTool(pi, config, state));
}

1. **TL;DR**

The core fix is to stop treating the macOS `open` helper as the simulator process. Launch the actual simulator binary on macOS, and make build failure reporting resilient when `pdc` exits non-zero but diagnostic parsing finds no structured errors. For simulator logs, keep a best-effort stdout/stderr capture on direct launch, but make screenshot/log tools rely on real process/window presence rather than the stale tracked child alone.

**Effort:** M (about 1–3h) for the primary path.

---

2. **Recommended approach**

### 1) Fix Issue 1: `pdc` false negative / `"Build failed with 0 error(s)"`

#### A. Make `runPdc()` return richer failure info
Keep `success = result.code === 0`, but add a fallback “unstructured failure” diagnostic when exit code is non-zero and no parsed errors were found.

**Change `src/lib/pdc.ts`:**
- Broaden parsing to recognize more `pdc` output forms.
- Add a fallback synthetic error entry when compilation failed without parseable diagnostics.

Example:

```ts
export interface PdcResult {
  success: boolean;
  output: string;
  errors: DiagnosticEntry[];
  warnings: DiagnosticEntry[];
  exitCode?: number;
}
```

```ts
export async function runPdc(
  pi: ExtensionAPI,
  pdcPath: string,
  sourceDir: string,
  outputDir: string,
  opts?: { signal?: AbortSignal; cwd?: string },
): Promise<PdcResult> {
  const args = [sourceDir, outputDir];
  const result = await pi.exec(pdcPath, args, {
    cwd: opts?.cwd,
    signal: opts?.signal,
  });

  const combined = `${result.stdout}\n${result.stderr}`.trim();
  const errors = parsePdcDiagnostics(combined, "error");
  const warnings = parsePdcDiagnostics(combined, "warning");

  if (result.code !== 0 && errors.length === 0) {
    errors.push({
      file: sourceDir,
      line: 1,
      message:
        extractBestPdcFailureMessage(combined) ??
        `pdc exited with code ${result.code}`,
    });
  }

  return {
    success: result.code === 0,
    output: combined,
    errors,
    warnings,
    exitCode: result.code,
  };
}
```

Add a helper:

```ts
function extractBestPdcFailureMessage(output: string): string | null {
  const lines = output
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);

  for (const line of lines) {
    const lower = line.toLowerCase();
    if (
      lower.includes("error") ||
      lower.includes("failed") ||
      lower.includes("cannot") ||
      lower.includes("could not")
    ) {
      return line;
    }
  }

  return lines.at(-1) ?? null;
}
```

#### B. Broaden diagnostic parsing
Current regex only catches `file:line[:col]: message`. That is too narrow.

Replace `parsePdcDiagnostics()` with:
- file:line[:col]: message
- explicit `warning:` / `error:` prefixes
- Windows-like paths safely handled by greedy file capture from the right

Practical version:

```ts
function parsePdcDiagnostics(
  output: string,
  kind: "error" | "warning",
): DiagnosticEntry[] {
  const entries: DiagnosticEntry[] = [];
  const lines = output.split("\n");

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;

    // file:line:col: message
    let match = line.match(/^(.*):(\d+):(\d+):\s*(.+)$/);
    if (match) {
      const [, file, lineStr, colStr, message] = match;
      const isWarning = /^warning\b[:\s-]*/i.test(message);
      const isError = /^error\b[:\s-]*/i.test(message) || !isWarning;

      if ((kind === "warning" && isWarning) || (kind === "error" && isError)) {
        entries.push({
          file,
          line: Number.parseInt(lineStr, 10),
          column: Number.parseInt(colStr, 10),
          message: message.replace(/^(warning|error)\b[:\s-]*/i, "").trim(),
        });
      }
      continue;
    }

    // file:line: message
    match = line.match(/^(.*):(\d+):\s*(.+)$/);
    if (match) {
      const [, file, lineStr, message] = match;
      const isWarning = /^warning\b[:\s-]*/i.test(message);
      const isError = /^error\b[:\s-]*/i.test(message) || !isWarning;

      if ((kind === "warning" && isWarning) || (kind === "error" && isError)) {
        entries.push({
          file,
          line: Number.parseInt(lineStr, 10),
          message: message.replace(/^(warning|error)\b[:\s-]*/i, "").trim(),
        });
      }
      continue;
    }

    // warning: message / error: message (no file)
    match = line.match(/^(warning|error)\b[:\s-]*(.+)$/i);
    if (match) {
      const [, level, message] = match;
      if (level.toLowerCase() === kind) {
        entries.push({
          file: "",
          line: 1,
          message: message.trim(),
        });
      }
    }
  }

  return entries;
}
```

#### C. Improve build error message in `build.ts`
If `pdcResult.success === false`, do not assume parsed errors are meaningful. Use output fallback.

Replace this block:

```ts
throw new Error(
  `Build failed with ${allErrors.length} error(s). ${allErrors.map((e) => `${e.file}:${e.line}: ${e.message}`).join("; ")}`,
);
```

with:

```ts
const errorSummary =
  pdcResult.errors.length > 0
    ? pdcResult.errors
        .map((e) => `${e.file ? `${e.file}:` : ""}${e.line}: ${e.message}`)
        .join("; ")
    : truncateTail(pdcResult.output).content || "Unknown pdc failure";

throw new Error(
  `Build failed${pdcResult.exitCode !== undefined ? ` (pdc exit ${pdcResult.exitCode})` : ""}. ${errorSummary}`,
);
```

---

### 2) Fix Issue 2: simulator PID tracking on macOS

#### Primary recommendation: launch the real simulator binary, not `open -a`
This is the cleanest fix and also gives you a chance to capture stdout/stderr.

On macOS, instead of:

```ts
cmd = "open";
args = ["-a", simLaunchPath, pdxPath];
```

resolve:

```ts
$SDK/bin/Playdate Simulator.app/Contents/MacOS/Playdate Simulator
```

and spawn that directly.

#### A. Add a helper to resolve the executable inside the `.app`
In `src/lib/sim.ts`:

```ts
import { existsSync } from "node:fs";
import { join } from "node:path";
```

```ts
function resolveSimulatorExecutable(simLaunchPath: string): string {
  if (process.platform !== "darwin") return simLaunchPath;

  if (simLaunchPath.endsWith(".app")) {
    const appName = simLaunchPath.replace(/\.app$/, "").split("/").pop();
    const candidate = join(
      simLaunchPath,
      "Contents",
      "MacOS",
      appName || "Playdate Simulator",
    );
    if (existsSync(candidate)) return candidate;
  }

  return simLaunchPath;
}
```

#### B. Spawn direct binary on macOS
Update `spawnSimulator()`:

```ts
if (process.platform === "darwin") {
  cmd = resolveSimulatorExecutable(simLaunchPath);
  args = [pdxPath];
} else {
  cmd = simLaunchPath;
  args = [pdxPath];
}
```

#### C. Track “launched simulator” more defensively
`ChildProcess` can still exit if simulator daemonizes internally, but with direct exec this is much less likely. Still, don’t clear state too aggressively on `exit` unless it matches the tracked PID.

Current:

```ts
child.on("exit", () => {
  state.simProcess = null;
  state.simPid = null;
});
```

Prefer:

```ts
const trackedPid = child.pid ?? null;

child.on("exit", () => {
  if (state.simPid === trackedPid) {
    state.simProcess = null;
    state.simPid = null;
    state.simStartedAt = null;
  }
});
```

#### D. Update `killSimulator()` to kill by PID, not child handle only
Detached process handling is more reliable by PID.

```ts
export function killSimulator(state: RuntimeState): boolean {
  if (!state.simPid) return false;

  try {
    process.kill(state.simPid, "SIGTERM");
  } catch {
    // already exited
  }

  state.simProcess = null;
  state.simPid = null;
  state.simStartedAt = null;
  return true;
}
```

---

### 3) Fix Issue 3: screenshot wrongly blocked

This is mostly solved by Issue 2, but the screenshot tool should not depend only on in-memory tracked PID. It should check actual simulator/window presence on macOS.

#### A. Relax precondition in `screenshot.ts`
Replace:

```ts
if (!isSimulatorRunning(state)) {
  throw new Error(
    "Simulator is not running. Start it first with playdate_run_sim.",
  );
}
```

with platform-aware probing:

```ts
if (process.platform !== "darwin" && !isSimulatorRunning(state)) {
  throw new Error(
    "Simulator is not running. Start it first with playdate_run_sim.",
  );
}
```

Then let `screenshotMacOS()` do the real check via AppleScript, since that already verifies the window exists.

#### B. Optional: add explicit macOS process/window probe helper
If you want consistency, add to `sim.ts` a lightweight helper like:

```ts
export async function isSimulatorWindowOpenMacOS(
  pi: ExtensionAPI,
  signal?: AbortSignal,
): Promise<boolean> {
  const result = await pi.exec(
    "osascript",
    [
      "-e",
      'tell application "System Events" to count windows of process "Playdate Simulator"',
    ],
    { signal },
  );

  return result.code === 0 && Number.parseInt(result.stdout.trim(), 10) > 0;
}
```

But this is optional; `screenshotMacOS()` already does enough.

---

### 4) Fix Issue 4: sim log empty

There are two separate problems:
1. the tracked process is wrong today
2. even with the right process, simulator logs may not reliably come through stdout/stderr on all setups

#### A. First fix the root cause by launching the real binary
Direct binary launch may make stdout/stderr capture work immediately. Keep the existing `stdout`/`stderr` ring-buffer code.

#### B. Stop presenting empty buffer as authoritative
If there is no buffer content, report that logs may not be piped by the simulator.

In `src/tools/sim_log.ts`, change the returned text fallback:

```ts
{ type: "text", text: truncated.content || "(no log output)" }
```

to something more helpful:

```ts
{
  type: "text",
  text:
    truncated.content ||
    "(no captured log output; the simulator may not emit logs to stdout/stderr on this platform/build)",
}
```

#### C. Add best-effort macOS fallback to Console/system log only if docs confirm a stable source
If Playdate SDK docs specify a simulator log file path or a unified logging subsystem, add a second source. Since the current context only says “the SDK docs mention simulator features” but does not provide a concrete path, **do not guess a log path in the primary fix**.

So for now:
- keep ring-buffer capture from direct spawn
- make tool status truthful
- don’t promise logs if no logs are being emitted

#### D. Make `simRunning` in `sim_log` less dependent on stale state on macOS
Because the tool is informational, use an actual process/window check when possible.

If you implement a macOS helper, use it here; otherwise keep `isSimulatorRunning(state)` after fixing direct spawn.

---

## Suggested concrete patch set

### `src/lib/sim.ts`
Primary changes:
- resolve direct executable on macOS
- spawn executable, not `open`
- kill by PID
- clear state carefully

Example full shape:

```ts
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import type { RuntimeState } from "./state";
import { pushLogLine } from "./state";

function resolveSimulatorExecutable(simLaunchPath: string): string {
  if (process.platform !== "darwin") return simLaunchPath;

  if (simLaunchPath.endsWith(".app")) {
    const appName =
      simLaunchPath.replace(/\.app$/, "").split("/").pop() ||
      "Playdate Simulator";
    const candidate = join(simLaunchPath, "Contents", "MacOS", appName);
    if (existsSync(candidate)) return candidate;
  }

  return simLaunchPath;
}

export function spawnSimulator(
  simLaunchPath: string,
  pdxPath: string,
  state: RuntimeState,
  maxLogLines: number,
): { pid: number } {
  killSimulator(state);

  const cmd =
    process.platform === "darwin"
      ? resolveSimulatorExecutable(simLaunchPath)
      : simLaunchPath;
  const args = [pdxPath];

  const child = spawn(cmd, args, {
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });

  child.unref();

  state.simProcess = child;
  state.simPid = child.pid ?? null;
  state.simStartedAt = new Date().toISOString();
  state.simLogBuffer = [];
  state.simLogTotalSeen = 0;

  const onData = (data: Buffer) => {
    const lines = data.toString().split("\n");
    for (const line of lines) {
      if (line.trim()) {
        pushLogLine(state, line, maxLogLines);
      }
    }
  };

  child.stdout?.on("data", onData);
  child.stderr?.on("data", onData);

  const trackedPid = child.pid ?? null;
  child.on("exit", () => {
    if (state.simPid === trackedPid) {
      state.simProcess = null;
      state.simPid = null;
      state.simStartedAt = null;
    }
  });

  return { pid: child.pid ?? 0 };
}

export function killSimulator(state: RuntimeState): boolean {
  if (!state.simPid) return false;

  try {
    process.kill(state.simPid, "SIGTERM");
  } catch {
    // already exited
  }

  state.simProcess = null;
  state.simPid = null;
  state.simStartedAt = null;
  return true;
}

export function isSimulatorRunning(state: RuntimeState): boolean {
  if (!state.simPid) return false;
  try {
