arguments.instructions:
Rewrite `src/tools/screenshot.ts` to use DAP for screenshots when available, falling back to the previous screencapture approach.

Key changes:

1. The execute method should try DAP first:
```ts
async execute(...): Promise<AgentToolResult<ScreenshotDetails>> {
  // Try DAP screenshot first (clean 400x240 game display, no chrome)
  if (state.dap?.isConnected()) {
    return screenshotDAP(state.dap);
  }

  // Fallback: OS-level window capture
  if (process.platform === "darwin") {
    return screenshotMacOS(pi, signal);
  }

  if (!isSimulatorRunning(state)) {
    throw new Error(
      "Simulator is not running. Start it first with playdate_run_sim.",
    );
  }

  if (process.platform === "linux") {
    return screenshotLinux(pi, signal);
  }
  throw new Error(`Screenshot not yet supported on ${process.platform}`);
}
```

2. Add a new `screenshotDAP` function:
```ts
async function screenshotDAP(
  dap: DapClient,
): Promise<AgentToolResult<ScreenshotDetails>> {
  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);
  await dap.screenshot(outputPath);

  // Small delay for file write to complete
  await new Promise((resolve) => setTimeout(resolve, 100));

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: "Screenshot captured from Playdate Simulator" },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}
```

3. Add import for DapClient: `import type { DapClient } from "../lib/dap";`

4. Keep all existing imports and fallback functions (screenshotMacOS, screenshotLinux) unchanged.

Verify: `pnpm typecheck && pnpm lint`

Rewrite `src/tools/sim_input.ts` to use DAP for input when available, falling back to osascript.

Key changes:

1. Add `state: RuntimeState` parameter to `createSimInputTool(pi, state)` and the register function.

2. Add imports:
```ts
import type { RuntimeState } from "../lib/state";
```

3. Replace the button→keycode mapping with a button→Lua callback mapping:
```ts
const BUTTON_CALLBACKS: Record<string, { down: string; up: string }> = {
  up: { down: "playdate.upButtonDown", up: "playdate.upButtonUp" },
  down: { down: "playdate.downButtonDown", up: "playdate.downButtonUp" },
  left: { down: "playdate.leftButtonDown", up: "playdate.leftButtonUp" },
  right: { down: "playdate.rightButtonDown", up: "playdate.rightButtonUp" },
  a: { down: "playdate.AButtonDown", up: "playdate.AButtonUp" },
  b: { down: "playdate.BButtonDown", up: "playdate.BButtonUp" },
};
```

4. In `execute`, try DAP first:
```ts
// Try DAP input (calls Lua callbacks directly, no window focus needed)
if (state.dap?.isConnected() && button !== "menu") {
  return sendInputDAP(state.dap, button, action, repeat);
}

// Fallback: osascript keystrokes (macOS only)
if (process.platform !== "darwin") {
  throw new Error(
    `Simulator input not yet supported on ${process.platform} without DAP connection`,
  );
}
```

5. Add `sendInputDAP` function:
```ts
async function sendInputDAP(
  dap: DapClient,
  button: string,
  action: string,
  repeat: number,
): Promise<AgentToolResult<SimInputDetails>> {
  const callbacks = BUTTON_CALLBACKS[button];
  if (!callbacks) {
    throw new Error(`Unknown button: ${button}`);
  }

  for (let i = 0; i < repeat; i++) {
    if (action === "hold") {
      await dap.evalLua(
        `if ${callbacks.down} then ${callbacks.down}() end`,
      );
      // For hold, we call down then up after a brief delay
      await new Promise((resolve) => setTimeout(resolve, 50));
      await dap.evalLua(
        `if ${callbacks.up} then ${callbacks.up}() end`,
      );
    } else if (action === "release") {
      await dap.evalLua(
        `if ${callbacks.up} then ${callbacks.up}() end`,
      );
    } else {
      // press: call down callback (game typically handles input on down)
      await dap.evalLua(
        `if ${callbacks.down} then ${callbacks.down}() end`,
      );
    }
  }

  const label =
    repeat > 1 ? `${button} x${repeat} (${action})` : `${button}`;

  return {
    content: [{ type: "text", text: `Sent ${label} to simulator` }],
    details: { button, action, repeat },
  };
}
```

6. Add import: `import type { DapClient } from "../lib/dap";`

7. Keep the osascript fallback code (MAC_KEY_CODES, buildKeypressScript, sendMenuAction) as-is.

8. Update the register function signature:
```ts
export function registerSimInputTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createSimInputTool(pi, state));
}
```

Verify: `pnpm typecheck && pnpm lint`

