import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ToolCallHeader } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import { isSimulatorRunning } from "../lib/sim";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({});

interface ScreenshotDetails {
  path: string;
  width: number;
  height: number;
}

export function createScreenshotTool(pi: ExtensionAPI, state: RuntimeState) {
  return {
    name: "playdate_screenshot",
    label: "Playdate Screenshot",
    description: "Take a screenshot of the running Playdate Simulator.",
    promptSnippet: "Capture screenshot from Playdate Simulator",
    parameters,

    async execute(
      _toolCallId: string,
      _params: Record<string, never>,
      signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<ScreenshotDetails>> {
      if (process.platform === "darwin") {
        // macOS: screenshotMacOS validates the window via osascript
        return screenshotMacOS(pi, signal);
      }

      if (!isSimulatorRunning(state)) {
        throw new Error(
          "Simulator is not running. Start it first with playdate_run_sim.",
        );
      }

      if (process.platform === "linux") {
        return screenshotLinux(pi, signal);
      }
      throw new Error(`Screenshot not yet supported on ${process.platform}`);
    },

    renderCall(_args: Record<string, never>, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Screenshot",
          mainArg: "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<ScreenshotDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Screenshot: capturing..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.path) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Screenshot failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      return new Text(`Screenshot saved to ${details.path}`, 0, 0);
    },
  };
}

async function screenshotMacOS(
  pi: ExtensionAPI,
  signal?: AbortSignal,
): Promise<AgentToolResult<ScreenshotDetails>> {
  // Get CGWindowID via CoreGraphics (osascript window IDs don't work for screencapture)
  const swiftScript = `
import CoreGraphics
let wl = CGWindowListCopyWindowInfo(.optionOnScreenOnly, kCGNullWindowID) as? [[String: Any]] ?? []
for w in wl {
  if (w["kCGWindowOwnerName"] as? String) == "Playdate Simulator",
     let wid = w["kCGWindowNumber"] as? Int {
    print(wid)
    break
  }
}`;

  const idResult = await pi.exec("swift", ["-e", swiftScript], { signal });
  const windowId = idResult.stdout.trim();

  if (idResult.code !== 0 || !windowId) {
    throw new Error("Could not find Playdate Simulator window. Is it running?");
  }

  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);

  const captureResult = await pi.exec(
    "screencapture",
    ["-l", windowId, "-o", outputPath],
    { signal },
  );

  if (captureResult.code !== 0) {
    throw new Error(`Screenshot failed: ${captureResult.stderr}`);
  }

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: `Screenshot captured from Playdate Simulator` },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}

async function screenshotLinux(
  pi: ExtensionAPI,
  signal?: AbortSignal,
): Promise<AgentToolResult<ScreenshotDetails>> {
  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);

  const result = await pi.exec(
    "import",
    ["-window", "Playdate Simulator", outputPath],
    { signal },
  );

  if (result.code !== 0) {
    throw new Error(
      `Screenshot failed: ${result.stderr}. Is ImageMagick installed?`,
    );
  }

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: `Screenshot saved to ${outputPath}` },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}

export function registerScreenshotTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createScreenshotTool(pi, state));
}

