import { createConnection, type Socket } from "node:net";

export const DAP_PORT = 55934;

export interface DapResponse {
  seq: number;
  type: string;
  command: string;
  success: boolean;
  message?: string;
  body?: Record<string, unknown>;
}

export interface DapEvalResult {
  success: boolean;
  result?: string;
  output?: string;
}

type PendingEntry = {
  resolve: (value: DapResponse) => void;
  reject: (reason: unknown) => void;
  timer: ReturnType<typeof setTimeout>;
};

export class DapClient {
  private socket: Socket | null = null;
  private seq: number = 0;
  private pending: Map<number, PendingEntry> = new Map();
  private buffer: Buffer = Buffer.alloc(0);
  private connected: boolean = false;
  private injected: boolean = false;

  async connect(port: number = DAP_PORT): Promise<void> {
    if (this.connected) return;

    await new Promise<void>((resolve, reject) => {
      const sock = createConnection({ port }, () => {
        this.connected = true;
        resolve();
      });

      sock.on("data", (chunk: Buffer) => this.onData(chunk));

      sock.on("close", () => {
        this.clearState();
      });

      sock.on("error", (err) => {
        if (!this.connected) {
          reject(err);
        }
        this.clearState();
      });

      this.socket = sock;
    });

    await this.send("initialize", {
      clientID: "pi-playdate",
      clientName: "pi-playdate",
      adapterID: "playdate",
      linesStartAt1: true,
      columnsStartAt1: true,
      pathFormat: "path",
    });

    await this.send("configurationDone");

    await this.injectHelpers();
  }

  disconnect(): void {
    this.socket?.destroy();
    this.clearState();
  }

  isConnected(): boolean {
    return this.connected;
  }

  private clearState(): void {
    this.connected = false;
    this.injected = false;
    this.socket = null;
    this.buffer = Buffer.alloc(0);
    for (const entry of this.pending.values()) {
      clearTimeout(entry.timer);
      entry.reject(new Error("DAP connection closed"));
    }
    this.pending.clear();
  }

  private send(
    command: string,
    args?: Record<string, unknown>,
  ): Promise<DapResponse> {
    return new Promise<DapResponse>((resolve, reject) => {
      if (!this.socket || !this.connected) {
        reject(new Error("DAP client not connected"));
        return;
      }

      const seq = ++this.seq;
      const message: Record<string, unknown> = {
        seq,
        type: "request",
        command,
      };
      if (args !== undefined) {
        message.arguments = args;
      }

      const body = JSON.stringify(message);
      const frame = `Content-Length: ${Buffer.byteLength(body)}\r\n\r\n${body}`;

      const timer = setTimeout(() => {
        this.pending.delete(seq);
        reject(new Error(`DAP request timed out: ${command}`));
      }, 10000);

      this.pending.set(seq, { resolve, reject, timer });

      this.socket.write(frame, (err) => {
        if (err) {
          this.pending.delete(seq);
          clearTimeout(timer);
          reject(err);
        }
      });
    });
  }

  private onData(chunk: Buffer): void {
    this.buffer = Buffer.concat([this.buffer, chunk]);

    while (true) {
      const headerEnd = this.buffer.indexOf("\r\n\r\n");
      if (headerEnd === -1) break;

      const headerStr = this.buffer.slice(0, headerEnd).toString("utf8");
      const match = /Content-Length:\s*(\d+)/i.exec(headerStr);
      if (!match) {
        // Malformed, skip ahead
        this.buffer = this.buffer.slice(headerEnd + 4);
        continue;
      }

      const contentLength = parseInt(match[1], 10);
      const bodyStart = headerEnd + 4;
      const bodyEnd = bodyStart + contentLength;

      if (this.buffer.length < bodyEnd) break;

      const bodyStr = this.buffer.slice(bodyStart, bodyEnd).toString("utf8");
      this.buffer = this.buffer.slice(bodyEnd);

      let msg: Record<string, unknown>;
      try {
        msg = JSON.parse(bodyStr) as Record<string, unknown>;
      } catch (parseError) {
        // Skip malformed JSON messages
        void parseError;
        continue;
      }

      if (msg.type === "response") {
        const requestSeq = msg.request_seq as number;
        const entry = this.pending.get(requestSeq);
        if (entry) {
          clearTimeout(entry.timer);
          this.pending.delete(requestSeq);
          entry.resolve(msg as unknown as DapResponse);
        }
      }
      // events are ignored
    }
  }

  async evaluate(expression: string): Promise<DapEvalResult> {
    const response = await this.send("evaluate", {
      expression,
      context: "repl",
    });

    if (!response.success) {
      return { success: false, result: response.message };
    }

    const result = response.body?.result as string | undefined;
    return { success: true, result };
  }

  async evalLua(code: string): Promise<string> {
    const result = await this.evaluate(`eval ${code}`);
    if (!result.success) {
      throw new Error(result.result ?? "evalLua failed");
    }
    return result.result ?? "";
  }

  async printExpr(expression: string): Promise<string> {
    const result = await this.evaluate(`p ${expression}`);
    return result.result ?? "";
  }

  async screenshot(outputPath: string): Promise<void> {
    await this.evalLua(
      `playdate.simulator.writeToFile(playdate.graphics.getDisplayImage(), "${outputPath}")`,
    );
  }

  private async injectHelpers(): Promise<void> {
    if (this.injected) return;

    const lua = `
function __pd_inspect(v, depth)
  depth = depth or 3
  if depth <= 0 then return tostring(v) end
  local t = type(v)
  if t ~= "table" then return tostring(v) end
  local parts = {}
  local arr = #v > 0
  if arr then
    for i = 1, math.min(#v, 50) do
      parts[#parts+1] = __pd_inspect(v[i], depth - 1)
    end
    if #v > 50 then parts[#parts+1] = "..." end
  else
    local count = 0
    for k, val in pairs(v) do
      if count >= 50 then parts[#parts+1] = "..."; break end
      parts[#parts+1] = tostring(k) .. "=" .. __pd_inspect(val, depth - 1)
      count = count + 1
    end
  end
  return "{" .. table.concat(parts, ", ") .. "}"
end
`.trim();

    await this.evalLua(lua);
    this.injected = true;
  }
}

/**
 * Simulator management: spawn, track, log, screenshot.
 */

// biome-ignore plugin: Uses node:child_process directly instead of pi.exec()
// because the simulator is a long-lived detached process that needs
// stdout/stderr piping into a ring buffer. pi.exec() does not support
// detached processes or streaming output.
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { DapClient } from "./dap";
import type { RuntimeState } from "./state";
import { pushLogLine } from "./state";

/**
 * Resolve the actual simulator executable path.
 * On macOS, if given a .app bundle, returns the internal binary so we get
 * the real long-lived process instead of a short-lived `open -a` launcher.
 */
function resolveSimulatorExecutable(simLaunchPath: string): string {
  if (process.platform !== "darwin") return simLaunchPath;

  if (simLaunchPath.endsWith(".app")) {
    const appName = simLaunchPath
      .split("/")
      .pop()
      ?.replace(/\.app$/, "");
    if (!appName) return simLaunchPath;
    const binaryPath = join(simLaunchPath, "Contents", "MacOS", appName);
    if (existsSync(binaryPath)) return binaryPath;
  }

  return simLaunchPath;
}

/**
 * Spawn the Playdate Simulator as a detached child.
 * Pipes stdout/stderr into the ring buffer in state.
 */
export function spawnSimulator(
  simLaunchPath: string,
  pdxPath: string,
  state: RuntimeState,
  maxLogLines: number,
): { pid: number } {
  // Kill existing simulator if running
  killSimulator(state);

  const cmd =
    process.platform === "darwin"
      ? resolveSimulatorExecutable(simLaunchPath)
      : simLaunchPath;
  const args = [pdxPath];

  const child = spawn(cmd, args, {
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });

  child.unref();

  const dap = new DapClient();
  state.dap = dap;

  // Connect to DAP server after simulator starts (needs time to initialize)
  setTimeout(async () => {
    try {
      await dap.connect();
    } catch (_e) {
      // DAP connection is best-effort; tools fall back gracefully
      state.dap = null;
    }
  }, 1500);

  state.simProcess = child;
  state.simPid = child.pid ?? null;
  state.simStartedAt = new Date().toISOString();
  state.simLogBuffer = [];
  state.simLogTotalSeen = 0;

  const onData = (data: Buffer) => {
    const lines = data.toString().split("\n");
    for (const line of lines) {
      if (line.trim()) {
        pushLogLine(state, line, maxLogLines);
      }
    }
  };

  child.stdout?.on("data", onData);
  child.stderr?.on("data", onData);

  const trackedPid = child.pid ?? null;
  child.on("exit", () => {
    if (state.simPid === trackedPid) {
      if (state.dap) {
        state.dap.disconnect();
        state.dap = null;
      }
      state.simProcess = null;
      state.simPid = null;
      state.simStartedAt = null;
    }
  });

  return { pid: child.pid ?? 0 };
}

/**
 * Kill the tracked simulator process.
 */
export function killSimulator(state: RuntimeState): boolean {
  if (!state.simPid) return false;
  if (state.dap) {
    state.dap.disconnect();
    state.dap = null;
  }
  try {
    process.kill(state.simPid, "SIGTERM");
  } catch (_e) {
    void _e; // process already exited
  }
  state.simProcess = null;
  state.simPid = null;
  state.simStartedAt = null;
  return true;
}

/**
 * Check if the simulator process is still running.
 */
export function isSimulatorRunning(state: RuntimeState): boolean {
  if (!state.simProcess || !state.simPid) return false;
  try {
    process.kill(state.simPid, 0);
    return true;
  } catch {
    state.simProcess = null;
    state.simPid = null;
    return false;
  }
}

import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ToolCallHeader } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { DapClient } from "../lib/dap";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({});

interface ScreenshotDetails {
  path: string;
  width: number;
  height: number;
}

export function createScreenshotTool(_pi: ExtensionAPI, state: RuntimeState) {
  return {
    name: "playdate_screenshot",
    label: "Playdate Screenshot",
    description: "Take a screenshot of the running Playdate Simulator.",
    promptSnippet: "Capture screenshot from Playdate Simulator",
    parameters,

    async execute(
      _toolCallId: string,
      _params: Record<string, never>,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<ScreenshotDetails>> {
      if (!state.dap?.isConnected()) {
        throw new Error(
          "DAP not connected. Start the simulator first with playdate_run_sim (Lua games only).",
        );
      }

      return screenshotDAP(state.dap);
    },

    renderCall(_args: Record<string, never>, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Screenshot",
          mainArg: "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<ScreenshotDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Screenshot: capturing..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.path) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Screenshot failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      return new Text(`Screenshot saved to ${details.path}`, 0, 0);
    },
  };
}

async function screenshotDAP(
  dap: DapClient,
): Promise<AgentToolResult<ScreenshotDetails>> {
  const outputPath = join(tmpdir(), `playdate-screenshot-${Date.now()}.png`);
  await dap.screenshot(outputPath);

  // Small delay for file write to complete
  await new Promise((resolve) => setTimeout(resolve, 100));

  const imageData = readFileSync(outputPath);
  const base64 = imageData.toString("base64");

  return {
    content: [
      { type: "text", text: "Screenshot captured from Playdate Simulator" },
      { type: "image", data: base64, mimeType: "image/png" },
    ],
    details: { path: outputPath, width: 400, height: 240 },
  };
}

export function registerScreenshotTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createScreenshotTool(pi, state));
}

import { ToolCallHeader } from "@aliou/pi-utils-ui";
import { StringEnum } from "@mariozechner/pi-ai";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { RuntimeState } from "../lib/state";

const BUTTONS = ["up", "down", "left", "right", "a", "b", "menu"] as const;

const ACTIONS = ["press", "release", "hold"] as const;

const parameters = Type.Object({
  button: StringEnum([...BUTTONS], {
    description: "Button to press: up/down/left/right (D-pad), a, b, or menu.",
  }),
  action: Type.Optional(
    StringEnum([...ACTIONS], {
      description:
        'Action type. "press" sends a tap (default), "hold" holds for duration_ms then releases.',
      default: "press",
    }),
  ),
  duration_ms: Type.Optional(
    Type.Number({
      description: "Hold duration in ms (only for action=hold). Default 200.",
      default: 200,
    }),
  ),
  repeat: Type.Optional(
    Type.Number({
      description: "Number of times to repeat the press. Default 1.",
      default: 1,
    }),
  ),
});

interface SimInputParams {
  button: string;
  action?: string;
  duration_ms?: number;
  repeat?: number;
}

interface SimInputDetails {
  button: string;
  action: string;
  repeat: number;
}

const BUTTON_CALLBACKS: Record<string, { down: string; up: string }> = {
  up: { down: "playdate.upButtonDown", up: "playdate.upButtonUp" },
  down: { down: "playdate.downButtonDown", up: "playdate.downButtonUp" },
  left: { down: "playdate.leftButtonDown", up: "playdate.leftButtonUp" },
  right: { down: "playdate.rightButtonDown", up: "playdate.rightButtonUp" },
  a: { down: "playdate.AButtonDown", up: "playdate.AButtonUp" },
  b: { down: "playdate.BButtonDown", up: "playdate.BButtonUp" },
};

export function createSimInputTool(_pi: ExtensionAPI, state: RuntimeState) {
  return {
    name: "playdate_sim_input",
    label: "Playdate Sim Input",
    description:
      "Send button input to the Playdate Simulator (D-pad, A, B, menu).",
    promptSnippet: "Send input to the Playdate Simulator",
    promptGuidelines: [
      "Use playdate_sim_input to interact with the game in the simulator.",
      "The simulator must be running with a Lua game. Use playdate_run_sim first.",
      "Use playdate_screenshot after sending input to see the result.",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: SimInputParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<SimInputDetails>> {
      const button = params.button;
      const action = params.action || "press";
      const repeat = params.repeat ?? 1;

      if (!state.dap?.isConnected()) {
        throw new Error(
          "DAP not connected. Start the simulator first with playdate_run_sim (Lua games only).",
        );
      }

      if (button === "menu") {
        // Menu has no Lua callback -- use DAP eval to toggle the system menu
        await state.dap.evalLua(
          "playdate.setAutoLockDisabled(not playdate.isAutoLockDisabled())",
        );
        return {
          content: [{ type: "text", text: "Toggled Playdate system menu" }],
          details: { button: "menu", action: "press", repeat: 1 },
        };
      }

      return sendInputDAP(state.dap, button, action, repeat);
    },

    renderCall(args: SimInputParams, theme: Theme) {
      const optionArgs: Array<{ label: string; value: string }> = [];
      if (args.action && args.action !== "press") {
        optionArgs.push({ label: "action", value: args.action });
      }
      if (args.repeat && args.repeat > 1) {
        optionArgs.push({ label: "repeat", value: `${args.repeat}` });
      }

      return new ToolCallHeader(
        {
          toolName: "Playdate Sim Input",
          mainArg: args.button || "",
          optionArgs,
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<SimInputDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Sim Input: sending..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.button) {
        const textBlock = result.content.find((c) => c.type === "text");
        const msg =
          (textBlock?.type === "text" && textBlock.text) || "Input failed";
        return new Text(theme.fg("error", msg), 0, 0);
      }

      const label =
        details.repeat > 1
          ? `${details.button} x${details.repeat}`
          : details.button;
      return new Text(`Sent ${label} to simulator`, 0, 0);
    },
  };
}

async function sendInputDAP(
  dap: { evalLua(code: string): Promise<string> },
  button: string,
  action: string,
  repeat: number,
): Promise<AgentToolResult<SimInputDetails>> {
  const callbacks = BUTTON_CALLBACKS[button];
  if (!callbacks) {
    throw new Error(`Unknown button: ${button}`);
  }

  for (let i = 0; i < repeat; i++) {
    if (action === "hold") {
      await dap.evalLua(`if ${callbacks.down} then ${callbacks.down}() end`);
      // For hold, we call down then up after a brief delay
      await new Promise((resolve) => setTimeout(resolve, 50));
      await dap.evalLua(`if ${callbacks.up} then ${callbacks.up}() end`);
    } else if (action === "release") {
      await dap.evalLua(`if ${callbacks.up} then ${callbacks.up}() end`);
    } else {
      // press: call down callback (game typically handles input on down)
      await dap.evalLua(`if ${callbacks.down} then ${callbacks.down}() end`);
    }
  }

  const label = repeat > 1 ? `${button} x${repeat} (${action})` : `${button}`;

  return {
    content: [{ type: "text", text: `Sent ${label} to simulator` }],
    details: { button, action, repeat },
  };
}

export function registerSimInputTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createSimInputTool(pi, state));
}

import { ToolBody, ToolCallHeader } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { truncateTail } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({
  expression: Type.String({
    description:
      'Lua expression or code to evaluate. Use "p <expr>" to print a value, or "eval <code>" to execute code.',
  }),
});

interface SimEvalParams {
  expression: string;
}

interface SimEvalDetails {
  success: boolean;
  result?: string;
  expression: string;
}

export function createSimEvalTool(state: RuntimeState) {
  return {
    name: "playdate_sim_eval",
    label: "Playdate Sim Eval",
    description:
      "Evaluate Lua expressions in the running Playdate Simulator. Use 'p <expr>' to read values, 'eval <code>' to execute code.",
    promptSnippet: "Evaluate Lua in the Playdate Simulator",
    promptGuidelines: [
      'playdate_sim_eval can read game state: expression "p variableName" returns its value.',
      'playdate_sim_eval can run code: expression "eval print(someTable)" executes it.',
      "Use __pd_inspect(table) to pretty-print tables instead of getting memory addresses.",
      'Example: "p __pd_inspect(myTable)" returns a readable representation.',
      "The simulator must be running with a Lua game loaded.",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: SimEvalParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<SimEvalDetails>> {
      if (!state.dap?.isConnected()) {
        throw new Error(
          "DAP not connected. Start the simulator first with playdate_run_sim (Lua games only).",
        );
      }

      const result = await state.dap.evaluate(params.expression);

      if (!result.success) {
        return {
          content: [
            { type: "text", text: result.result || "Evaluation failed" },
          ],
          details: {
            success: false,
            result: result.result,
            expression: params.expression,
          },
        };
      }

      const output = result.result || "(no return value)";
      const truncated = truncateTail(output);

      return {
        content: [{ type: "text", text: truncated.content }],
        details: {
          success: true,
          result: output,
          expression: params.expression,
        },
      };
    },

    renderCall(args: SimEvalParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Sim Eval",
          mainArg: args.expression || "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<SimEvalDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Sim Eval: evaluating..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details) {
        const textBlock = result.content.find((c) => c.type === "text");
        const msg =
          (textBlock?.type === "text" && textBlock.text) || "Eval failed";
        return new Text(theme.fg("error", msg), 0, 0);
      }

      const fields = [
        {
          label: "Expression",
          value: details.expression,
          showCollapsed: true,
        },
      ];

      if (details.result) {
        fields.push({
          label: "Result",
          value: details.result,
          showCollapsed: true,
        });
      }

      return new ToolBody(
        {
          fields,
        },
        options,
        theme,
      );
    },
  };
}

export function registerSimEvalTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createSimEvalTool(state));
}

/**
 * Ephemeral runtime state -- lives in memory only, cleared on session_shutdown.
 */

// biome-ignore plugin: ChildProcess type needed for simulator process tracking
import type { ChildProcess } from "node:child_process";
import type { DapClient } from "./dap";

export interface BuildResult {
  kind: "lua" | "c" | "hybrid";
  target: "simulator" | "device";
  pdxPath: string;
  durationMs: number;
  warnings: DiagnosticEntry[];
  errors: DiagnosticEntry[];
}

export interface DiagnosticEntry {
  file: string;
  line: number;
  column?: number;
  message: string;
}

export interface RuntimeState {
  simProcess: ChildProcess | null;
  simPid: number | null;
  simStartedAt: string | null;
  simLogBuffer: string[];
  simLogTotalSeen: number;
  lastBuildResult: BuildResult | null;
  lastDevicePort: string | null;
  dap: DapClient | null;
}

export function createRuntimeState(): RuntimeState {
  return {
    simProcess: null,
    simPid: null,
    simStartedAt: null,
    simLogBuffer: [],
    simLogTotalSeen: 0,
    lastBuildResult: null,
    lastDevicePort: null,
    dap: null,
  };
}

export function pushLogLine(
  state: RuntimeState,
  line: string,
  maxLines: number,
): void {
  state.simLogBuffer.push(line);
  state.simLogTotalSeen++;
  if (state.simLogBuffer.length > maxLines) {
    state.simLogBuffer.shift();
  }
}

