const parameters = Type.Object({
  pdxPath: Type.Optional(
    Type.String({
      description:
        "Path to .pdx bundle. Defaults to last build or auto-detect.",
    }),
  ),
});

type RunSimParams = Static<typeof parameters>;

interface RunSimDetails {
  pid: number;
  pdxPath: string;
  startedAt: string;
}

export function createRunSimTool(
  _pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_run_sim",
    label: "Playdate Run Sim",
    description: "Launch the Playdate Simulator with a .pdx bundle.",
    promptSnippet: "Start the Playdate Simulator",
    parameters,

    async execute(
      _toolCallId: string,
      params: RunSimParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<RunSimDetails>> {
      const sdkPath = resolveSDKPath(config);
      const simPath = getSimulatorLaunchPath(sdkPath);
      if (!simPath) {
        throw new Error(
          "Simulator not found. Run playdate_doctor to check your setup.",
        );
      }

      let pdxPath = params.pdxPath;
      if (!pdxPath && state.lastBuildResult) {
        pdxPath = state.lastBuildResult.pdxPath;
      }
      if (!pdxPath) {
        pdxPath = findPdxBundle(ctx.cwd) ?? undefined;
      }
      if (!pdxPath) {
        throw new Error(
          "No .pdx bundle found. Build the project first with playdate_build.",
        );
      }

      const { pid } = spawnSimulator(
        simPath,
        pdxPath,
        state,
        config.simulatorLogLines,
      );

      ctx.ui.setStatus("playdate", "sim running");
      ctx.ui.notify("Simulator started", "info");

      return {
        content: [{ type: "text", text: `Simulator started (PID ${pid})` }],
        details: {
          pid,
          pdxPath,
          startedAt: state.simStartedAt ?? new Date().toISOString(),
        },
      };
    },

    renderCall(args: RunSimParams, theme: Theme) {
      return new ToolCallHeader(
        {
          toolName: "Playdate Run Sim",
          mainArg: args.pdxPath || "",
          optionArgs: [],
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<RunSimDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Run Sim: starting..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.pid) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Failed to start";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "PID", value: `${details.pid}`, showCollapsed: true },
        { label: "Bundle", value: details.pdxPath, showCollapsed: true },
      ];

      return new ToolBody({ fields }, options, theme);
    },
  };
}

export function registerRunSimTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createRunSimTool(pi, config, state));
}

import { ToolBody, ToolCallHeader, ToolFooter } from "@aliou/pi-utils-ui";
import { StringEnum } from "@mariozechner/pi-ai";
import type {
  AgentToolResult,
  AgentToolUpdateCallback,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import {
  truncateTail,
  withFileMutationQueue,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import type { ResolvedPlaydateConfig } from "../config";
import { cmakeBuild } from "../lib/cmake";
import { runPdc } from "../lib/pdc";
import { detectProject } from "../lib/project";
import { findPdc, resolveSDKPath } from "../lib/sdk";
import type { BuildResult, RuntimeState } from "../lib/state";

const parameters = Type.Object({
  projectPath: Type.Optional(
    Type.String({ description: "Path to the project root. Defaults to cwd." }),
  ),
  target: Type.Optional(
    StringEnum(["simulator", "device"], { description: "Build target" }),
  ),
  clean: Type.Optional(
    Type.Boolean({
      description: "Clean build directory before building",
      default: false,
    }),
  ),
});

interface BuildParams {
  projectPath?: string;
  target?: string;
  clean?: boolean;
}

interface BuildDetails extends BuildResult {
  output?: string;
}

export function createBuildTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  return {
    name: "playdate_build",
    label: "Playdate Build",
    description:
      "Build a Playdate project (Lua or C). Auto-detects project kind.",
    promptSnippet: "Compile Playdate project to .pdx bundle",
    promptGuidelines: [
      "Use playdate_build before running in simulator or deploying to device.",
      "After playdate_build, check details.errors before proceeding.",
    ],
    parameters,

    async execute(
      _toolCallId: string,
      params: BuildParams,
      signal: AbortSignal | undefined,
      _onUpdate: AgentToolUpdateCallback<BuildDetails> | undefined,
      ctx: ExtensionContext,
    ): Promise<AgentToolResult<BuildDetails>> {
      const projectPath = params.projectPath || ctx.cwd;
      const rawTarget = params.target || config.defaultTarget;
      const target: "simulator" | "device" =
        rawTarget === "device" ? "device" : "simulator";
      const sdkPath = resolveSDKPath(config);
      const start = Date.now();

      const project = detectProject(projectPath);
      const pdc = findPdc(sdkPath);
      if (!pdc.ok) throw new Error(pdc.error ?? "pdc not found");

      const allErrors: BuildResult["errors"] = [];
      const allWarnings: BuildResult["warnings"] = [];
      let buildOutput = "";

      // C build (if applicable)
      if (project.kind === "c" || project.kind === "hybrid") {
        const cmake = await cmakeBuild(pi, projectPath, target, {
          sdkPath,
          buildMode: config.buildMode,
          clean: params.clean,
          signal,
        });
        buildOutput += cmake.output;
        allErrors.push(...cmake.errors);
        allWarnings.push(...cmake.warnings);

        if (!cmake.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          const errorSummary =
            allErrors.length > 0
              ? allErrors
                  .map(
                    (e) =>
                      `${e.file ? `${e.file}:` : ""}${e.line}: ${e.message}`,
                  )
                  .join("; ")
              : truncateTail(buildOutput).content || "Unknown C build failure";
          throw new Error(`C build failed. ${errorSummary}`);
        }
      }

      // Lua/pdc build
      if (project.kind === "lua" || project.kind === "hybrid") {
        const pdcResult = await withFileMutationQueue(
          project.outputDir,
          async () => {
            return runPdc(pi, pdc.path, project.sourceDir, project.outputDir, {
              cwd: projectPath,
              signal,
            });
          },
        );
        buildOutput += pdcResult.output;
        allErrors.push(...pdcResult.errors);
        allWarnings.push(...pdcResult.warnings);

        if (!pdcResult.success) {
          const details: BuildDetails = {
            kind: project.kind,
            target,
            pdxPath: project.outputDir,
            durationMs: Date.now() - start,
            warnings: allWarnings,
            errors: allErrors,
            output: truncateTail(buildOutput).content,
          };
          state.lastBuildResult = details;
          const errorSummary =
            allErrors.length > 0
              ? allErrors
                  .map(
                    (e) =>
                      `${e.file ? `${e.file}:` : ""}${e.line}: ${e.message}`,
                  )
                  .join("; ")
              : truncateTail(buildOutput).content || "Unknown pdc failure";
          throw new Error(`Build failed. ${errorSummary}`);
        }
      }

      const durationMs = Date.now() - start;
      const details: BuildDetails = {
        kind: project.kind,
        target,
        pdxPath: project.outputDir,
        durationMs,
        warnings: allWarnings,
        errors: allErrors,
      };
      state.lastBuildResult = details;

      const summary =
        allWarnings.length > 0
          ? `Built ${project.pdxName} (${durationMs}ms, ${allWarnings.length} warning(s))`
          : `Built ${project.pdxName} (${durationMs}ms)`;

      return {
        content: [{ type: "text", text: summary }],
        details,
      };
    },

    renderCall(args: BuildParams, theme: Theme) {
      const optionArgs: Array<{ label: string; value: string }> = [];
      if (args.target) optionArgs.push({ label: "target", value: args.target });
      if (args.clean) optionArgs.push({ label: "clean", value: "true" });

      return new ToolCallHeader(
        {
          toolName: "Playdate Build",
          mainArg: args.projectPath || "",
          optionArgs,
          longArgs: [],
        },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<BuildDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Build: compiling..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.kind) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Build failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        { label: "Kind", value: details.kind, showCollapsed: true },
        { label: "Target", value: details.target, showCollapsed: true },
        { label: "Output", value: details.pdxPath, showCollapsed: true },
      ];

      if (details.errors.length > 0) {
        fields.push({
          label: "Errors",
          value: details.errors
            .map((e) => `${e.file}:${e.line}: ${e.message}`)
            .join("\n"),
          showCollapsed: true,
        });
      }

      const footerItems = [{ label: "time", value: `${details.durationMs}ms` }];
      if (details.warnings.length > 0) {
        footerItems.push({
          label: "warnings",
          value: `${details.warnings.length}`,
        });
      }
      if (details.errors.length > 0) {
        footerItems.push({
          label: "errors",
          value: `${details.errors.length}`,
        });
      }

      return new ToolBody(
        {
          fields,
          footer: new ToolFooter(theme, {
            items: footerItems,
            separator: " | ",
          }),
          includeSpacerBeforeFooter: true,
        },
        options,
        theme,
      );
    },
  };
}

export function registerBuildTool(
  pi: ExtensionAPI,
  config: ResolvedPlaydateConfig,
  state: RuntimeState,
) {
  pi.registerTool(createBuildTool(pi, config, state));
}

import { ToolBody, ToolCallHeader, ToolFooter } from "@aliou/pi-utils-ui";
import type {
  AgentToolResult,
  ExtensionAPI,
  ExtensionContext,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { truncateTail } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@sinclair/typebox";
import { isSimulatorRunning } from "../lib/sim";
import type { RuntimeState } from "../lib/state";

const parameters = Type.Object({
  lines: Type.Optional(
    Type.Number({ description: "Number of log lines to return", default: 50 }),
  ),
  grep: Type.Optional(
    Type.String({ description: "Filter log lines by pattern" }),
  ),
});

type SimLogParams = Static<typeof parameters>;

interface SimLogDetails {
  lines: string[];
  totalSeen: number;
  simRunning: boolean;
}

export function createSimLogTool(state: RuntimeState) {
  return {
    name: "playdate_sim_log",
    label: "Playdate Sim Log",
    description: "Get recent simulator log output.",
    promptSnippet: "Read Playdate Simulator log output",
    parameters,

    async execute(
      _toolCallId: string,
      params: SimLogParams,
      _signal: AbortSignal | undefined,
      _onUpdate: undefined,
      _ctx: ExtensionContext,
    ): Promise<AgentToolResult<SimLogDetails>> {
      const maxLines = params.lines ?? 50;
      let lines = [...state.simLogBuffer];

      if (params.grep) {
        const pattern = new RegExp(params.grep, "i");
        lines = lines.filter((l) => pattern.test(l));
      }

      lines = lines.slice(-maxLines);
      const simRunning = isSimulatorRunning(state);

      const truncated = truncateTail(lines.join("\n"));

      return {
        content: [
          {
            type: "text",
            text:
              truncated.content ||
              "(no log output captured; use print() in your game code to see output here)",
          },
        ],
        details: {
          lines,
          totalSeen: state.simLogTotalSeen,
          simRunning,
        },
      };
    },

    renderCall(args: SimLogParams, theme: Theme) {
      const optionArgs: Array<{ label: string; value: string }> = [];
      if (args.lines)
        optionArgs.push({ label: "lines", value: `${args.lines}` });
      if (args.grep)
        optionArgs.push({ label: "grep", value: `"${args.grep}"` });

      return new ToolCallHeader(
        { toolName: "Playdate Sim Log", mainArg: "", optionArgs, longArgs: [] },
        theme,
      );
    },

    renderResult(
      result: AgentToolResult<SimLogDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
    ) {
      if (options.isPartial) {
        return new Text(
          theme.fg("muted", "Playdate Sim Log: reading..."),
          0,
          0,
        );
      }

      const { details } = result;
      if (!details?.lines) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) || "Failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      const fields = [
        {
          label: "Status",
          value: details.simRunning ? "running" : "stopped",
          showCollapsed: true,
        },
        {
          label: "Lines",
          value: `${details.lines.length} (${details.totalSeen} total)`,
          showCollapsed: true,
        },
      ];

      const footerItems = [
        { label: "total seen", value: `${details.totalSeen}` },
      ];

      return new ToolBody(
        {
          fields,
          footer: new ToolFooter(theme, {
            items: footerItems,
            separator: " | ",
          }),
          includeSpacerBeforeFooter: true,
        },
        options,
        theme,
      );
    },
  };
}

export function registerSimLogTool(pi: ExtensionAPI, state: RuntimeState) {
  pi.registerTool(createSimLogTool(state));
}

/**
 * Simulator management: spawn, track, log, screenshot.
 */

// biome-ignore plugin: Uses node:child_process directly instead of pi.exec()
// because the simulator is a long-lived detached process that needs
// stdout/stderr piping into a ring buffer. pi.exec() does not support
// detached processes or streaming output.
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { DapClient } from "./dap";
import type { RuntimeState } from "./state";
import { pushLogLine } from "./state";

/**
 * Resolve the actual simulator executable path.
 * On macOS, if given a .app bundle, returns the internal binary so we get
 * the real long-lived process instead of a short-lived `open -a` launcher.
 */
function resolveSimulatorExecutable(simLaunchPath: string): string {
  if (process.platform !== "darwin") return simLaunchPath;

  if (simLaunchPath.endsWith(".app")) {
    const appName = simLaunchPath
      .split("/")
      .pop()
      ?.replace(/\.app$/, "");
    if (!appName) return simLaunchPath;
    const binaryPath = join(simLaunchPath, "Contents", "MacOS", appName);
    if (existsSync(binaryPath)) return binaryPath;
  }

  return simLaunchPath;
}

/**
 * Spawn the Playdate Simulator as a detached child.
 * Pipes stdout/stderr into the ring buffer in state.
 */
export function spawnSimulator(
  simLaunchPath: string,
  pdxPath: string,
  state: RuntimeState,
  maxLogLines: number,
): { pid: number } {
  // Kill existing simulator if running
  killSimulator(state);

  const cmd =
    process.platform === "darwin"
      ? resolveSimulatorExecutable(simLaunchPath)
      : simLaunchPath;
  const args = [pdxPath];

  const child = spawn(cmd, args, {
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });

  child.unref();

  const dap = new DapClient();
  state.dap = dap;

  // Best-effort eager connect. Tools also connect lazily on demand.
  setTimeout(async () => {
    try {
      await dap.connect();
    } catch (_e) {
      void _e;
    }
  }, 1500);

  state.simProcess = child;
  state.simPid = child.pid ?? null;
  state.simStartedAt = new Date().toISOString();
  state.simLogBuffer = [];
  state.simLogTotalSeen = 0;

  const onData = (data: Buffer) => {
    const lines = data.toString().split("\n");
    for (const line of lines) {
      if (line.trim()) {
        pushLogLine(state, line, maxLogLines);
      }
    }
  };

  child.stdout?.on("data", onData);
  child.stderr?.on("data", onData);

  const trackedPid = child.pid ?? null;
  child.on("exit", () => {
    if (state.simPid === trackedPid) {
      if (state.dap) {
        state.dap.disconnect();
        state.dap = null;
      }
      state.simProcess = null;
      state.simPid = null;
      state.simStartedAt = null;
    }
  });

  return { pid: child.pid ?? 0 };
}

/**
 * Kill the tracked simulator process.
 */
export function killSimulator(state: RuntimeState): boolean {
  if (!state.simPid) return false;
  if (state.dap) {
    state.dap.disconnect();
    state.dap = null;
  }
  try {
    process.kill(state.simPid, "SIGTERM");
  } catch (_e) {
    void _e; // process already exited
  }
  state.simProcess = null;
  state.simPid = null;
  state.simStartedAt = null;
  return true;
}

/**
 * Check if the simulator process is still running.
 */
export function isSimulatorRunning(state: RuntimeState): boolean {
  if (!state.simProcess || !state.simPid) return false;
  try {
    process.kill(state.simPid, 0);
    return true;
  } catch {
    state.simProcess = null;
    state.simPid = null;
    return false;
  }
}

export async function ensureSimulatorDap(
  state: RuntimeState,
  signal?: AbortSignal,
): Promise<DapClient> {
  if (!isSimulatorRunning(state)) {
    throw new Error(
      "Simulator is not running. Start it first with playdate_run_sim.",
    );
  }

  if (!state.dap) {
    state.dap = new DapClient();
  }

  await state.dap.connect(undefined, signal);
  return state.dap;
}

import { ToolBody } from "@aliou/pi-utils-ui";
import { StringEnum } from "@mariozechner/pi-ai";
import type {
  AgentToolResult,
  ExtensionAPI,
  Theme,
  ToolRenderResultOptions,
} from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { type Static, Type } from "@sinclair/typebox";
import type { ProcessesDetails } from "../constants";
import type { ProcessManager } from "../manager";
import { executeAction, renderActionCall, renderActionResult } from "./actions";

const DEBUG_PREVIEW_ENABLED = process.env.PI_PROCESSES_DEBUG_PREVIEW === "1";

const PROCESS_ACTIONS = [
  "start",
  "list",
  "output",
  "logs",
  "kill",
  "clear",
  "write",
  ...(DEBUG_PREVIEW_ENABLED ? (["debug_preview"] as const) : []),
] as const;

const ProcessesParams = Type.Object({
  action: StringEnum(PROCESS_ACTIONS, {
    description: DEBUG_PREVIEW_ENABLED
      ? "Action: start (run command), list (show all), output (get recent output), logs (get log file paths), kill (terminate), clear (remove finished), write (write to stdin), debug_preview (temporary UI preview, no side effects)"
      : "Action: start (run command), list (show all), output (get recent output), logs (get log file paths), kill (terminate), clear (remove finished), write (write to stdin)",
  }),
  command: Type.Optional(
    Type.String({ description: "Command to run (required for start)" }),
  ),
  name: Type.Optional(
    Type.String({
      description:
        "Friendly name for the process (required for start, e.g. 'backend-dev', 'test-runner')",
    }),
  ),
  id: Type.Optional(
    Type.String({
      description:
        "Process ID, returned by start and list actions (required for output/kill/logs/write)",
    }),
  ),
  input: Type.Optional(
    Type.String({
      description: "Data to write to process stdin (required for write action)",
    }),
  ),
  end: Type.Optional(
    Type.Boolean({
      description:
        "Close stdin after writing (optional for write action, use for programs reading until EOF)",
    }),
  ),
  alertOnSuccess: Type.Optional(
    Type.Boolean({
      description:
        "Get a turn to react when process completes successfully (default: false). Use for builds/tests where you need confirmation.",
    }),
  ),
  alertOnFailure: Type.Optional(
    Type.Boolean({
      description:
        "Get a turn to react when process fails/crashes (default: true). Use to be alerted of unexpected failures.",
    }),
  ),
  alertOnKill: Type.Optional(
    Type.Boolean({
      description:
        "Get a turn to react when process is killed by external signal (default: false). Note: killing via tool never triggers a turn.",
    }),
  ),
  ...(DEBUG_PREVIEW_ENABLED
    ? {
        preview: Type.Optional(
          StringEnum(["start", "list", "output", "logs", "error"] as const, {
            description:
              "For action=debug_preview only: which rendered result variant to preview (default: start)",
          }),
        ),
      }
    : {}),
  logWatches: Type.Optional(
    Type.Array(
      Type.Object(
        {
          pattern: Type.String({
            description:
              "Regular expression pattern to match against process output lines",
          }),
          stream: Type.Optional(
            StringEnum(["stdout", "stderr", "both"] as const, {
              description:
                "Which stream to watch (default: both). Use stdout/stderr to reduce noise.",
            }),
          ),
          repeat: Type.Optional(
            Type.Boolean({
              description:
                "Trigger every time this pattern matches (default: false, one-time)",
            }),
          ),
        },
        { additionalProperties: false },
      ),
    ),
  ),
});

type ProcessesParamsType = Static<typeof ProcessesParams>;

export function setupProcessesTools(pi: ExtensionAPI, manager: ProcessManager) {
  pi.registerTool<typeof ProcessesParams, ProcessesDetails>({
    name: "process",
    label: "Process",
    description: `Manage background processes. Actions:
- start: Run command in background (requires 'name' and 'command')
  - alertOnSuccess (default: false): Get a turn to react when process completes successfully
  - alertOnFailure (default: true): Get a turn to react when process crashes/fails
  - alertOnKill (default: false): Get a turn to react if killed by external signal (killing via tool never triggers a turn)
  - logWatches (optional): Runtime output watches that trigger immediate alerts while running
    - pattern: regex string to match per output line
    - stream: stdout | stderr | both (default both)
    - repeat: false by default (single-fire). Set true for repeat alerts
- list: Show all managed processes with their IDs and names
- output: Get recent stdout/stderr (requires 'id')
- logs: Get log file paths to inspect with read tool (requires 'id')
- kill: Terminate a process (requires 'id')
- clear: Remove all finished processes from the list
- write: Write to process stdin (requires 'id' and 'input', optional 'end' to close stdin)
${
  DEBUG_PREVIEW_ENABLED
    ? "- debug_preview: Temporary renderer preview for process tool UIs (no process side effects)\n  - preview: start | list | output | logs | error (default: start)\n"
    : ""
}
Important: You DON'T need to poll or wait for processes. Notifications arrive automatically based on your preferences. Start processes and continue with other work - you'll be informed if something requires attention.

Note: User always sees process updates in the UI. The notify flags control whether YOU (the agent) get a turn to react (e.g. check results, fix code, restart).`,
    promptSnippet:
      "Manage background processes without blocking the conversation",
    promptGuidelines: [
      "Use this tool for long-running commands such as dev servers, test watchers, build watchers, and log tails instead of bash.",
      "Avoid shell background patterns such as &, nohup, disown, or setsid when the process tool fits.",
      "After starting a process, continue other work instead of waiting for it.",
      "Use the pi-processes skill for examples and best practices when a task depends on background processes.",
    ],

    parameters: ProcessesParams,

    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      return executeAction(params, manager, ctx);
    },

    renderCall(args: ProcessesParamsType, theme: Theme, _context) {
      return renderActionCall(args, theme);
    },

    renderResult(
      result: AgentToolResult<ProcessesDetails>,
      options: ToolRenderResultOptions,
      theme: Theme,
      _context,
    ) {
      if (options.isPartial) {
        return new Text(theme.fg("muted", "Process: running..."), 0, 0);
      }

      const { details } = result;

      // Framework sets details to {} when tool throws.
      // Detect by checking for missing expected fields.
      if (!details?.action) {
        const textBlock = result.content.find((c) => c.type === "text");
        const errorMsg =
          (textBlock?.type === "text" && textBlock.text) ||
          "Tool execution failed";
        return new Text(theme.fg("error", errorMsg), 0, 0);
      }

      if (!details.success) {
        return new ToolBody(
          {
            fields: [
              {
                label: "Error",
                value: theme.fg("error", details.message),
                showCollapsed: true,
              },
            ],
          },
          options,
          theme,
        );
      }

      return renderActionResult(result, options, theme);
    },
  });
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { setupProcessesCommands } from "./commands";
import { registerProcessesSettings } from "./commands/settings";
import { configLoader } from "./config";
import { setupProcessesHooks } from "./hooks";
import { ProcessManager } from "./manager";
import { setupProcessesTools } from "./tools";

export default async function (pi: ExtensionAPI) {
  if (process.platform === "win32") {
    pi.on("session_start", async (_event, ctx) => {
      if (!ctx.hasUI) return;
      ctx.ui.notify("processes extension not available on Windows", "warning");
    });
    return;
  }

  await configLoader.load();
  const manager = new ProcessManager({
    getConfiguredShellPath: () => configLoader.getConfig().execution.shellPath,
  });

  const config = configLoader.getConfig();

  const { update: updateWidget, dockActions } = setupProcessesHooks(
    pi,
    manager,
    config,
  );
  setupProcessesCommands(pi, manager, dockActions);
  setupProcessesTools(pi, manager);
  registerProcessesSettings(pi, () => {
    updateWidget();
  });
}

