/**
 * Kill the simulator -- tracked process + any system-wide instances.
 */
export function killSimulator(state: RuntimeState): boolean {
  if (state.dap) {
    state.dap.disconnect();
    state.dap = null;
  }

  const hadPid = !!state.simPid;

  if (state.simPid) {
    try {
      process.kill(state.simPid, "SIGTERM");
    } catch (_e) {
      void _e;
    }
  }

