/**
 * Run pdc (Playdate compiler) and parse error output.
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import type { DiagnosticEntry } from "./state";

export interface PdcResult {
  success: boolean;
  output: string;
  errors: DiagnosticEntry[];
  warnings: DiagnosticEntry[];
  exitCode: number;
}

/**
 * Run pdc to compile a Lua project to .pdx.
 */
export async function runPdc(
  pi: ExtensionAPI,
  pdcPath: string,
  sourceDir: string,
  outputDir: string,
  opts?: { signal?: AbortSignal; cwd?: string },
): Promise<PdcResult> {
  const args = [sourceDir, outputDir];
  const result = await pi.exec(pdcPath, args, {
    cwd: opts?.cwd,
    signal: opts?.signal,
  });

  const combined = `${result.stdout}\n${result.stderr}`.trim();
  const errors = parsePdcDiagnostics(combined, "error");
  const warnings = parsePdcDiagnostics(combined, "warning");

  if (result.code !== 0 && errors.length === 0) {
    const fallback = extractFallbackMessage(combined);
    errors.push({
      file: sourceDir,
      line: 1,
      message: fallback ?? `pdc exited with code ${result.code}`,
    });
  }

  return {
    success: result.code === 0,
    output: combined,
    errors,
    warnings,
    exitCode: result.code,
  };
}

/**
 * Parse pdc output for diagnostics.
 * pdc errors look like: `filename.lua:LINE: error message`
 * or: `filename.lua:LINE:COL: error message`
 * Warnings may have "warning:" prefix.
 */
function parsePdcDiagnostics(
  output: string,
  kind: "error" | "warning",
): DiagnosticEntry[] {
  const entries: DiagnosticEntry[] = [];
  const lines = output.split("\n");

  for (const line of lines) {
    // Pattern: file:line: message or file:line:col: message
    const match = line.match(/^(.+?):(\d+)(?::(\d+))?:\s*(.+)$/);
    if (!match) {
      // Pattern: error: message or warning: message (no file)
      const prefixMatch = line.match(/^(warning|error):\s*(.+)$/i);
      if (prefixMatch) {
        const [, level, msg] = prefixMatch;
        if (level.toLowerCase() === kind) {
          entries.push({ file: "", line: 1, message: msg.trim() });
        }
      }
      continue;
    }

    const [, file, lineStr, colStr, message] = match;
    const isWarning = message.toLowerCase().startsWith("warning");
    const isError = !isWarning;

    if ((kind === "error" && isError) || (kind === "warning" && isWarning)) {
      entries.push({
        file,
        line: Number.parseInt(lineStr, 10),
        column: colStr ? Number.parseInt(colStr, 10) : undefined,
        message: message.replace(/^(warning|error):\s*/i, "").trim(),
      });
    }
  }

  return entries;
}

/**
 * Extract a meaningful error message from raw pdc output.
 * Prefers lines containing error keywords; falls back to the last non-empty line.
 */
function extractFallbackMessage(output: string): string | null {
  const lines = output
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);

  if (lines.length === 0) return null;

  const keywords = /error|failed|cannot|could not/i;
  const keywordLine = lines.find((l) => keywords.test(l));
  if (keywordLine) return keywordLine;

  return lines[lines.length - 1];
}

/**
 * Project detection: find project kind, pdxinfo, source/output dirs.
 */

import { existsSync, readdirSync, statSync } from "node:fs";
import { basename, join } from "node:path";

export type ProjectKind = "lua" | "c" | "hybrid";

export interface ProjectInfo {
  kind: ProjectKind;
  root: string;
  sourceDir: string;
  outputDir: string;
  pdxName: string;
  hasCMakeLists: boolean;
  hasPdxInfo: boolean;
}

/**
 * Detect project kind and resolve paths. Throws if no valid project found.
 */
export function detectProject(projectPath: string): ProjectInfo {
  const hasCMakeLists = existsSync(join(projectPath, "CMakeLists.txt"));
  const hasSourceDir =
    existsSync(join(projectPath, "Source")) ||
    existsSync(join(projectPath, "source"));
  const hasPdxInfoUpper = existsSync(join(projectPath, "Source", "pdxinfo"));
  const hasPdxInfoLower = existsSync(join(projectPath, "source", "pdxinfo"));
  const hasPdxInfo = hasPdxInfoUpper || hasPdxInfoLower;

  const sourceDir = existsSync(join(projectPath, "Source"))
    ? "Source"
    : "source";

  let kind: ProjectKind;
  if (hasCMakeLists && hasSourceDir) {
    kind = "hybrid";
  } else if (hasCMakeLists) {
    kind = "c";
  } else if (hasSourceDir) {
    kind = "lua";
  } else {
    throw new Error(
      `No Playdate project found at ${projectPath}. Expected CMakeLists.txt or Source/ directory.`,
    );
  }

  const dirName = basename(projectPath);
  const pdxName = `${dirName}.pdx`;
  const outputDir = join(projectPath, pdxName);

  return {
    kind,
    root: projectPath,
    sourceDir: join(projectPath, sourceDir),
    outputDir,
    pdxName,
    hasCMakeLists,
    hasPdxInfo,
  };
}

/**
 * Find a .pdx directory in the given path.
 */
export function findPdxBundle(projectPath: string): string | null {
  try {
    const entries = readdirSync(projectPath);
    for (const entry of entries) {
      if (entry.endsWith(".pdx")) {
        const full = join(projectPath, entry);
        if (statSync(full).isDirectory()) {
          return full;
        }
      }
    }
  } catch (_e) {
    return null;
  }
  return null;
}

