import { OnTaskRunnerMessage, TaskRunner } from "../core";
import { exec } from "../util";

import { getKillSimulatorCommand } from "./getKillSimulatorCommand";
import { getMacOSSimulatorCommand } from "./getMacOSSimulatorCommand";

/**
 * SimulatorMacOSTaskRunnerOptions contains extra properties asigned to the
 * `playdate-simulator` task in `tasks.json`.
 */
export interface SimulatorMacOSTaskRunnerOptions {
 sdkPath: string;
 openGamePath?: string;
 kill?: boolean;
 argv?: string[];
}

/**
 * SimulatorMacOSTaskRunner is responsible for launching the Playdate Simulator
 * executable on MacOS if it is not already running.
 */
export class SimulatorMacOSTaskRunner implements TaskRunner {
 constructor(private options: SimulatorMacOSTaskRunnerOptions) {}

 async run(onMessage: OnTaskRunnerMessage): Promise {
 const { sdkPath, openGamePath, kill, argv } = this.options;

 if (kill === true) {
 onMessage("Stopping Playdate Simulator...");
 const killCommand = getKillSimulatorCommand("darwin");
 onMessage(`> ${killCommand}`);
 try {
 await exec(killCommand);
 } catch (_err) {
 // noop
 }
 }

 onMessage("Starting Playdate Simulator...");
 const command = getMacOSSimulatorCommand({
 sdkPath,
 openGamePath,
 argv,
 });
 onMessage(`> ${command}`);

 await exec(command);
 }
}

import * as childProcess from "child_process";
import * as path from "path";

import { OnTaskRunnerMessage, TaskRunner } from "../core";
import { exec, quote } from "../util";

import { getKillSimulatorCommand } from "./getKillSimulatorCommand";

/**
 * SimulatorLinuxTaskRunnerOptions contains extra properties asigned to the
 * `playdate-simulator` task in `tasks.json`.
 */
export interface SimulatorLinuxTaskRunnerOptions {
 sdkPath: string;
 openGamePath?: string;
 kill?: boolean;
 argv?: string[];
}

/**
 * SimulatorLinuxTaskRunner is responsible for launching the Playdate Simulator
 * executable on Linux if it is not already running.
 */
export class SimulatorLinuxTaskRunner implements TaskRunner {
 constructor(private options: SimulatorLinuxTaskRunnerOptions) {}

 async run(onMessage: OnTaskRunnerMessage): Promise {
 const { sdkPath, openGamePath, kill, argv } = this.options;

 if (kill === true) {
 onMessage("Stopping Playdate Simulator...");
 const killCommand = getKillSimulatorCommand("linux");
 onMessage(`> ${killCommand}`);
 try {
 await exec(killCommand);
 } catch (_err) {
 // noop
 }
 }

 try {
 const result = await exec("pidof PlaydateSimulator");
 if (result.stdout.length > 0) {
 return;
 }
 } catch (_err) {
 // noop
 }

 const simulatorPath = quote(
 path.resolve(sdkPath, "bin", "PlaydateSimulator"),
 );
 const args = [];
 if (openGamePath) {
 args.push(quote(openGamePath));

 if (argv?.length) {
 for (const arg of argv) {
 args.push(quote(arg));
 }
 }
 }

 const command = `${simulatorPath} ${args.join(" ")}`;

 onMessage("Starting Playdate Simulator...");
 onMessage(`> ${command}`);

 const child = childProcess.spawn(simulatorPath, args, {
 shell: true,
 detached: true,
 stdio: "ignore",
 });
 child.unref();
 }
}

import * as childProcess from "child_process";
import * as path from "path";

import { OnTaskRunnerMessage, TaskRunner } from "../core";
import { exec, quote } from "../util";

import { getKillSimulatorCommand } from "./getKillSimulatorCommand";

/**
 * SimulatorWin32TaskRunnerOptions contains extra properties asigned to the
 * `playdate-simulator` task in `tasks.json`.
 */
export interface SimulatorWin32TaskRunnerOptions {
 sdkPath: string;
 openGamePath?: string;
 kill?: boolean;
 argv?: string[];
}

/**
 * SimulatorWin32TaskRunner is responsible for launching the Playdate Simulator
 * executable on Windows if it is not already running.
 */
export class SimulatorWin32TaskRunner implements TaskRunner {
 constructor(private options: SimulatorWin32TaskRunnerOptions) {}

 async run(onMessage: OnTaskRunnerMessage): Promise {
 const { sdkPath, openGamePath, kill, argv } = this.options;

 if (kill === true) {
 onMessage("Stopping Playdate Simulator...");
 const killCommand = getKillSimulatorCommand("win32");
 onMessage(`> ${killCommand}`);
 try {
 await exec(killCommand);
 } catch (_err) {
 // noop
 }
 } else {
 onMessage("Checking for running Playdate Simulator...");
 const listCommand = "tasklist";
 onMessage(`> ${listCommand}`);
 const { stdout } = await exec(listCommand);
 if (stdout.match(PLAYDATE_SIMULATOR_WIN32_RE)) {
 onMessage("Playdate Simulator is already running!");
 return;
 }
 }

 onMessage("Starting Playdate Simulator...");
 const simulatorPath = quote(
 path.resolve(sdkPath, "bin", "PlaydateSimulator.exe"),
 );
 const args = [];
 if (openGamePath) {
 args.push(quote(openGamePath));

 if (argv?.length) {
 for (const arg of argv) {
 args.push(quote(arg));
 }
 }
 }
 onMessage(`> ${simulatorPath} ${args.join(" ")}`);

 const child = childProcess.spawn(simulatorPath, args, {
 shell: true,
 detached: true,
 stdio: "ignore",
 });
 child.unref();
 }
}

/**
 * PLAYDATE_SIMULATOR_WIN32_RE is used on Windows to parse the output of the
 * tasklist command. We know the Playdate Simulator is already running when the
 * regex matches the output of the command.
 */
const PLAYDATE_SIMULATOR_WIN32_RE = /PlaydateSimulator\.exe/g;

import * as path from "path";

import { quote } from "../util";

export interface GetMacOSSimulatorCommandOptions {
 sdkPath: string;
 openGamePath?: string;
 argv?: string[];
}

export function getMacOSSimulatorCommand({
 sdkPath,
 openGamePath: gamePath,
 argv,
}: GetMacOSSimulatorCommandOptions): string {
 const simulatorPath = path.resolve(sdkPath, "bin", "Playdate Simulator.app");
 const args = ["-a", quote(simulatorPath)];
 if (gamePath) {
 args.push(quote(gamePath));

 if (argv?.length) {
 args.push("--args");
 for (const arg of argv) {
 args.push(quote(arg));
 }
 }
 }
 return `/usr/bin/open ${args.join(" ")}`;
}

export function getKillSimulatorCommand(
 platform: NodeJS.Platform = process.platform,
): string {
 switch (platform) {
 case "darwin":
 return 'killall -9 "Playdate Simulator"';
 case "win32":
 return "taskkill /IM PlaydateSimulator.exe";
 case "linux":
 return "(pidof PlaydateSimulator | xargs -r kill -9)";
 default:
 throw new Error(`Unsupported platform: ${process.platform}`);
 }
}

import * as net from "net";

import { SIMULATOR_DEBUG_PORT } from "../constants";
import { waitForDebugPort, WaitForDebugPortOptions } from "../util";

import { DebugAdapterLogger } from "./DebugAdapterLogger";
import { Fixer } from "./fix";

/**
 * ProxyServer is used to improve the experience of debugging Playdate games
 * in VS Code. It works around compatibility issues between the Playdate
 * Simulator debug adapter protocol server and the VSCode client.
 *
 * See https://microsoft.github.io/debug-adapter-protocol/ for details about
 * the Debug Adapter Protocol.
 */
export class ProxyServer {
 private clientSocket!: net.Socket;
 private simulatorSocket!: net.Socket;

 private constructor(
 private fixer: Fixer | null,
 private logger: DebugAdapterLogger | null,
 ) {}

 /**
 * Connect to the Playdate Simulator debugger and then start the proxy server.
 *
 * @returns The proxy socket server instance. Calling code must call `listen`
 * on the socket server to accept incoming connections from VS Code.
 */
 static async start(
 fixer: Fixer | null,
 logger: DebugAdapterLogger | null,
 options: Partial = {},
 ): Promise {
 const proxy = new ProxyServer(fixer, logger);
 await proxy.connect(options);

 return net.createServer((socket) => {
 if (proxy.clientSocket) {
 return;
 }

 proxy.clientSocket = socket;
 proxy.clientSocket.on("data", (data) => proxy.proxyClientData(data));
 });
 }

 private async connect(
 options: Partial = {},
 ): Promise {
 // The Playdate Simulator's debug adapter protocol server takes ~250ms to
 // respond on the debug port after launching the app. waitForDebugPort will
 // attempt to continuously connect to the Playdate Simulator up to a certain
 // number of times with a short timeout. We return the connected socket
 // because closing it immediately after a successful connection can cause
 // the Playdate Simulator to become unresponsive to new connections.
 const socket = await waitForDebugPort(SIMULATOR_DEBUG_PORT, options);
 if (!socket) {
 throw new Error(`Could not connect to Playdate Simulator`);
 }

 this.simulatorSocket = socket;
 this.simulatorSocket.on("data", (data) => this.proxySimulatorData(data));
 this.simulatorSocket.on("close", () => this.clientSocket?.end());
 }

 private proxyClientData(dataIn: Buffer): void {
 this.logger?.log(dataIn.toString(), "client");

 if (!this.fixer) {
 this.simulatorSocket?.write(dataIn);
 return;
 }

 const messages = decodeMessages(dataIn);
 for (const message of messages) {
 const response = this.fixer.onProxyClient(message);
 if (response) {
 const dataOut = encodeMessage(response);
 this.clientSocket?.write(dataOut);
 }

 const dataOut = encodeMessage(message);
 this.simulatorSocket?.write(dataOut);
 }
 }

 private proxySimulatorData(dataIn: Buffer): void {
 this.logger?.log(dataIn.toString(), "server");

 if (!this.fixer) {
 this.clientSocket?.write(dataIn);
 return;
 }

 const messages = decodeMessages(dataIn);
 for (const message of messages) {
 this.fixer.onProxyServer(message);

 const dataOut = encodeMessage(message);
 this.clientSocket?.write(dataOut);
 }
 }
}

// See https://microsoft.github.io/debug-adapter-protocol/overview#base-protocol
// for a description of the base protocol used to transmit Debug Adapter
// Protocol messages.

function decodeMessages(data: Buffer): any[] {
 let payload = data.toString();
 const messages = [];
 while (payload) {
 const prefixIndex = payload.indexOf(CONTENT_LENGTH_PREFIX);
 if (prefixIndex < 0) {
 throw new Error(
 "Failed to decode message: expected Content-Length prefix",
 );
 }

 const prefixEnd = prefixIndex + CONTENT_LENGTH_PREFIX.length;
 const separatorIndex = payload.indexOf(SEPARATOR);
 const contentLengthData = payload.slice(prefixEnd, separatorIndex);

 let contentLength: number;
 try {
 contentLength = parseInt(contentLengthData, 10);
 } catch (_err) {
 throw new Error(
 "Failed to decode message: Content-Length data must be an integer",
 );
 }

 const separatorEnd = separatorIndex + SEPARATOR.length;
 const contentEnd = separatorEnd + contentLength;
 const message = payload.slice(separatorEnd, contentEnd);
 payload = payload.slice(contentEnd);

 try {
 messages.push(JSON.parse(message));
 } catch (_err) {
 throw new Error(
 "Failed to decode message: content must be in JSON format",
 );
 }
 }
 return messages;
}

function encodeMessage(message: any): Buffer {
 const content = JSON.stringify(message);
 const components = [`${CONTENT_LENGTH_PREFIX}${content.length}`, content];
 const payload = components.join(SEPARATOR);
 return Buffer.from(payload);
}

const CONTENT_LENGTH_PREFIX = "Content-Length: ";
const SEPARATOR = "\r\n\r\n";

import * as net from "net";

import { inject, injectable } from "inversify";
import * as vscode from "vscode";

import { CROSS_PLATFORM_DEBUG_SDK_VERSION } from "../constants";
import { ConfigurationResolver } from "../core";
import { WaitForDebugPortOptions } from "../util";

import { DebugAdapterLoggerFactory } from "./DebugAdapterLoggerFactory";
import { ProxyServer } from "./ProxyServer";
import { FixerFactory } from "./fix";

/**
 * ProxyDebugAdapterDescriptorFactory launches the Playdate debugger proxy
 * server and tells VS Code how to connect to it.
 */
@injectable()
export class ProxyDebugAdapterDescriptorFactory
 implements vscode.DebugAdapterDescriptorFactory, vscode.Disposable
{
 private server?: net.Server;
 private loggerFactory = new DebugAdapterLoggerFactory();

 constructor(
 @inject(ConfigurationResolver) private config: ConfigurationResolver,
 @inject(FixerFactory) private fixerFactory: FixerFactory,
 ) {}

 async createDebugAdapterDescriptor(
 session: vscode.DebugSession,
 ): Promise {
 this.server?.close();

 const {
 disableWorkarounds: disableWorkaroundsConfig,
 logDebugAdapter,
 retryTimeout,
 maxRetries,
 } = session.configuration;

 const config = await this.config.resolve(session.workspaceFolder);
 if (!config) {
 return undefined;
 }

 const { sdkVersion } = config;
 const disableWorkarounds =
 disableWorkaroundsConfig ||
 sdkVersion >= CROSS_PLATFORM_DEBUG_SDK_VERSION;

 const options: Partial = {};
 if (retryTimeout !== undefined) {
 options.retryTimeout = retryTimeout;
 }
 if (maxRetries !== undefined) {
 options.maxRetries = maxRetries;
 }

 const fixer = await this.fixerFactory.buildFixer(disableWorkarounds);
 const logger = this.loggerFactory.createLogger(logDebugAdapter);

 this.server = await ProxyServer.start(fixer, logger, options);
 this.server.listen(0);

 const address = this.server.address() as net.AddressInfo;
 const port = address.port;
 return new vscode.DebugAdapterServer(port);
 }

 dispose(): void {
 this.server?.close();
 this.loggerFactory?.dispose();
 }
}

