import { inject, injectable } from "inversify";
import * as vscode from "vscode";

import {
 CROSS_PLATFORM_DEBUG_SDK_VERSION,
 DebugType,
 TaskType,
} from "../constants";
import { ConfigurationResolver, getGamePathFromSource } from "../core";
import { PDCTaskProvider } from "../pdc";
import { SimulatorTaskProvider } from "../simulator";
import { runTask } from "../util";

import { DebugSessionRegistry } from "./DebugSessionRegistry";

@injectable()
export class EditorContentsCommand {
 constructor(
 @inject(ConfigurationResolver) private config: ConfigurationResolver,
 @inject(PDCTaskProvider) private pdcTaskProvider: PDCTaskProvider,
 @inject(SimulatorTaskProvider)
 private simulatorTaskProvider: SimulatorTaskProvider,
 @inject(DebugSessionRegistry)
 private debugSessionRegistry: DebugSessionRegistry,
 ) {}

 async execute(resource?: vscode.Uri, debug = false): Promise {
 const targetResource = this.getTargetResource(resource);
 if (!targetResource) {
 return;
 }
 const sourcePath = targetResource.fsPath;

 const config = await this.config.resolve(targetResource);
 if (!config) {
 return;
 }

 const { sdkPath, sdkVersion, outputPath } = config;
 const gamePath = getGamePathFromSource(sourcePath, outputPath);

 const pdcTask = await this.pdcTaskProvider.createTask({
 type: TaskType.pdc,
 sdkPath,
 sourcePath,
 gamePath,
 });
 await runTask(pdcTask);

 const debugUnsupported =
 process.platform !== "darwin" &&
 sdkVersion < CROSS_PLATFORM_DEBUG_SDK_VERSION;

 const simulatorTask = await this.simulatorTaskProvider.createTask({
 type: TaskType.simulator,
 kill: debugUnsupported,
 openGame: debugUnsupported,
 sdkPath,
 gamePath,
 });
 await runTask(simulatorTask);

 if (debugUnsupported) {
 return;
 }

 await this.debugSessionRegistry.stopAll();

 const parentOptions = this.getParentOptions(debug);
 await vscode.debug.startDebugging(
 undefined,
 {
 type: DebugType.playdate,
 name: this.getName(debug),
 request: "launch",
 sourcePath,
 gamePath,
 },
 parentOptions,
 );
 }

 private getName(debug: boolean): string {
 return `${debug ? "Debug" : "Run"} Editor Contents`;
 }

 private getParentOptions(
 debug: boolean,
 ): vscode.DebugSessionOptions | undefined {
 return debug ? undefined : { noDebug: true };
 }

 private getTargetResource(
 resource: vscode.Uri | undefined,
 ): vscode.Uri | undefined {
 return !resource && vscode.window.activeTextEditor
 ? vscode.window.activeTextEditor.document.uri
 : resource;
 }
}

import { injectable } from "inversify";
import * as vscode from "vscode";

import { DebugType } from "../constants";

@injectable()
export class DebugSessionRegistry {
 private sessions = new Map ();

 activate(): vscode.Disposable[] {
 const startDisposable = vscode.debug.onDidStartDebugSession((session) =>
 this.handleStartSession(session),
 );

 const stopDisposable = vscode.debug.onDidTerminateDebugSession((session) =>
 this.handleTerminateSession(session),
 );

 return [startDisposable, stopDisposable];
 }

 async stopAll(): Promise {
 const sessions = Array.from(this.sessions.values());
 const promises = sessions.map((session) =>
 vscode.debug.stopDebugging(session),
 );
 await Promise.all(promises);
 }

 private handleStartSession(session: vscode.DebugSession): void {
 if (session.type === DebugType.playdate) {
 this.sessions.set(session.id, session);
 }
 }

 private handleTerminateSession(session: vscode.DebugSession): void {
 this.sessions.delete(session.id);
 }
}

import * as path from "path";

import { injectable } from "inversify";
import * as vscode from "vscode";

import { toAbsolute } from "../util";

import { getWorkspaceRoot } from "./getWorkspaceRoot";
import { readPDXInfo } from "./readPDXInfo";
import { readSDKPath } from "./readSDKPath";
import { readSDKVersion } from "./readSDKVersion";

export interface Configuration {
 workspaceRoot: string;
 sdkPath: string;
 sdkVersion: string;
 sourcePath: string;
 outputPath: string;
 productName: string;
 productPath: string;
 gamePath: string;
}

export type ConfigurationScope =
 | vscode.Uri
 | vscode.WorkspaceFolder
 | vscode.TaskScope
 | undefined;

/**
 * ConfigurationResolver is responsible for resolving the final PlaydateSDK and
 * game configuration. It resolves configuration from the VS Code workspace
 * configuration and the user's environment.
 */
@injectable()
export class ConfigurationResolver {
 async resolve(scope: ConfigurationScope): Promise {
 const workspaceFolder = getWorkspaceRoot(scope);
 if (!workspaceFolder) {
 return undefined;
 }
 const workspaceRoot = workspaceFolder.uri.fsPath;

 const {
 sdkPath: sdkPathConfig,
 sourcePath: sourcePathConfig,
 outputPath: outputPathConfig,
 productName: productNameConfig,
 } = vscode.workspace.getConfiguration("playdate-debug", workspaceFolder);

 let sdkPath = sdkPathConfig;
 if (!sdkPath) {
 sdkPath = await readSDKPath();
 } else {
 sdkPath = toAbsolute(workspaceRoot, sdkPath);
 }

 const sdkVersion = await readSDKVersion(sdkPath);

 let sourcePath = sourcePathConfig;
 if (!sourcePath) {
 sourcePath = path.resolve(workspaceRoot, "source");
 }
 sourcePath = toAbsolute(workspaceRoot, sourcePath);

 let outputPath = outputPathConfig;
 if (!outputPath) {
 outputPath = workspaceRoot;
 } else if (
 typeof outputPath === "object" &&
 "sdkFolder" in outputPath &&
 outputPath.sdkFolder === "simulatorGames"
 ) {
 outputPath = path.resolve(sdkPath, "Disk/Games");
 }
 outputPath = toAbsolute(workspaceRoot, outputPath);

 let productName = productNameConfig;
 if (!productName) {
 try {
 const pdxInfo = await readPDXInfo(sourcePath);
 productName = pdxInfo.name;
 } catch (_err) {
 productName = path.basename(sourcePath);
 }
 }

 const productPath = path.resolve(outputPath, productName);
 const gamePath = productPath + ".pdx";

 return {
 workspaceRoot,
 sdkPath,
 sdkVersion,
 sourcePath,
 outputPath,
 productName,
 productPath,
 gamePath,
 };
 }
}

import * as path from "path";

import { WIN32_FORWARD_SLASH_SDK_VERSION } from "../constants";
import { quote } from "../util";

export interface GetPDCCommandOptions {
 sdkPath: string;
 input: string;
 output: string;
 strip?: boolean;
 noCompress?: boolean;
 verbose?: boolean;
 quiet?: boolean;
 skipUnknown?: boolean;
 libPath?: string[];
 sdkVersion: string;
}

export function getPDCCommand(options: GetPDCCommandOptions) {
 let { input } = options;
 const {
 sdkPath,
 output,
 strip,
 noCompress,
 verbose,
 quiet,
 skipUnknown,
 libPath,
 sdkVersion,
 } = options;

 const executable = quote(path.join(sdkPath, "bin", "pdc"));

 const optionalArgs = [];
 if (input.endsWith(".lua")) {
 optionalArgs.push("--main");
 if (
 process.platform === "win32" &&
 sdkVersion >= WIN32_FORWARD_SLASH_SDK_VERSION
 ) {
 input = input.split(path.win32.sep).join(path.posix.sep);
 }
 }
 if (strip) {
 optionalArgs.push("--strip");
 }
 if (noCompress) {
 optionalArgs.push("--no-compress");
 }
 if (verbose) {
 optionalArgs.push("--verbose");
 }
 if (quiet) {
 optionalArgs.push("--quiet");
 }
 if (skipUnknown) {
 optionalArgs.push("--skip-unknown");
 }
 if (libPath) {
 for (const lib of libPath) {
 optionalArgs.push("--libpath", quote(lib));
 }
 }

 const requiredArgs = [
 "-sdkpath",
 quote(sdkPath),
 quote(input),
 quote(output),
 ];

 const args = optionalArgs.concat(requiredArgs);
 return `${executable} ${args.join(" ")}`;
}

import {
 incrementBuildNumber,
 OnTaskRunnerMessage,
 readPDXInfo,
 TaskRunner,
 writePDXInfo,
} from "../core";
import { exec } from "../util";

import { getPDCCommand, GetPDCCommandOptions } from "./getPDCCommand";

/**
 * PDCTaskRunnerOptions contains extra properties asigned to the `pdc` task in
 * `tasks.json`.
 */
export interface PDCTaskRunnerOptions {
 workspaceRoot: string;
 sdkPath: string;
 sourcePath: string;
 gamePath: string;
 strip?: boolean;
 noCompress?: boolean;
 verbose?: boolean;
 quiet?: boolean;
 skipUnknown?: boolean;
 incrementBuildNumber?: boolean;
 sdkVersion: string;
 libPath?: string[];
}

/**
 * PDCTaskRunner is responsible for executing the PlaydateSDK's `pdc` binary
 * in order to compile a Playdate game's source into a `.pdx` bundle.
 */
export class PDCTaskRunner implements TaskRunner {
 constructor(private options: PDCTaskRunnerOptions) {}

 async run(onMessage: OnTaskRunnerMessage): Promise {
 const { workspaceRoot } = this.options;
 const pdcOptions = this.getPDCOptions();
 const pdcCommand = getPDCCommand(pdcOptions);

 if (this.options.incrementBuildNumber) {
 try {
 const { sourcePath } = this.options;
 const pdxInfo = await readPDXInfo(sourcePath);
 incrementBuildNumber(pdxInfo);
 await writePDXInfo(pdxInfo, sourcePath);
 } catch (_err) {
 // noop
 }
 }

 onMessage("Compiling...");
 onMessage(`> ${pdcCommand}`);
 await exec(pdcCommand, { cwd: workspaceRoot });
 }

 private getPDCOptions(): GetPDCCommandOptions {
 const {
 sdkPath,
 sourcePath,
 gamePath,
 strip,
 noCompress,
 verbose,
 quiet,
 skipUnknown,
 libPath,
 sdkVersion,
 } = this.options;

 return {
 sdkPath,
 input: sourcePath,
 output: gamePath,
 strip,
 noCompress,
 verbose,
 quiet,
 skipUnknown,
 libPath,
 sdkVersion,
 };
 }
}

import { injectable, unmanaged } from "inversify";
import * as vscode from "vscode";

import { TaskExecutionFactory } from "./TaskExecutionFactory";
import { TaskProviderErrorTerminal } from "./TaskProviderErrorTerminal";

/**
 * TaskProviderOptions stores the vscode Task options that a TaskProvider uses
 * to create a Task instance.
 */
export interface TaskProviderOptions {
 type: string;
 problemMatchers: string[];
 name: string;
 source: string;
}

/**
 * TaskProvider is a generic vscode.TaskProvider that can be configured for
 * different tasks using the options argument of the constructor.
 */
@injectable()
export class TaskProvider implements vscode.TaskProvider {
 constructor(
 @unmanaged() private factory: TaskExecutionFactory,
 @unmanaged() private options: TaskProviderOptions,
 ) {}

 async provideTasks(): Promise {
 let task: vscode.Task;
 try {
 task = await this.createTask();
 } catch (err) {
 task = this.createErrorTask(err);
 }
 return [task];
 }

 async resolveTask(
 task: vscode.Task,
 _token: vscode.CancellationToken,
 ): Promise {
 const { definition, scope } = task;
 try {
 return await this.createTask(definition, scope);
 } catch (err) {
 return this.createErrorTask(err, definition, scope);
 }
 }

 async createTask(
 maybeDefinition?: vscode.Task["definition"],
 maybeScope?: vscode.Task["scope"],
 ): Promise {
 const { type, problemMatchers, name, source } = this.options;
 const definition = maybeDefinition ?? { type };
 const scope = maybeScope ?? vscode.TaskScope.Workspace;
 const execution = await this.factory.createExecution(definition, scope);

 return new vscode.Task(
 definition,
 scope,
 name,
 source,
 execution,
 problemMatchers,
 );
 }

 protected createErrorTask(
 error: unknown,
 maybeDefinition?: vscode.Task["definition"],
 maybeScope?: vscode.Task["scope"],
 ): vscode.Task {
 const { type, problemMatchers, name, source } = this.options;
 const definition = maybeDefinition ?? { type };
 const scope = maybeScope ?? vscode.TaskScope.Workspace;
 const execution = new vscode.CustomExecution(() =>
 Promise.resolve(new TaskProviderErrorTerminal(error)),
 );

 return new vscode.Task(
 definition,
 scope,
 name,
 source,
 execution,
 problemMatchers,
 );
 }
